-- ─────────────────────────────────────────────────────────────
--  THE OLD WEBSITE'S NEWS — part 6 of 7: 68 articles kept as drafts (not live)
--  Generated by scripts/import-old-news.py from Rich's export of the old WordPress database.
--  Run the news files in order, after the other files in supabase/legacy/ (SQL Editor → paste → Run), each once.
--
--  All 528 old articles: 186 league and competition articles from 2019 on go live, with their real dates.
--  The other 342 wait in Admin → News as drafts (Rich, round 30): Professional Snooker, CueViews,
--  Snooker Memories, and the old archive — whose articles all carry the date 1 January 2014 on the old site
--  (their real dates were lost long ago). Tick "Published" on any of them to put it on the website.
--  The text keeps its paragraphs, the opening paragraph and the pull quote. Pictures are not brought across
--  (Rich is sorting them): real-data/legacy/news-pictures.csv says which article had which picture.
--  None is "featured", so the News page and the banner keep showing the newest articles.
--  Nothing already on the website is changed. All one transaction.
-- ─────────────────────────────────────────────────────────────
begin;

do $$ begin
  if exists (select 1 from articles where slug in ('osullivan-captures-fifth-world-crown', 'osullivan-crushes-ding', 'osullivan-lands-english-open-crown', 'osullivan-the-champion-again', 'osullivan-the-master')) then
    raise exception 'This part of the old news is already in: nothing to do.';
  end if;
end $$;

insert into categories (name, sort)
  select r.name, 100 + row_number() over (order by r.name) from (values
  ('Competitions'),
  ('Cue View'),
  ('League Meetings'),
  ('League News'),
  ('Match Reports'),
  ('Professional Snooker'),
  ('Snooker Memories')) r(name)
  where not exists (select 1 from categories c where lower(c.name) = lower(r.name));

create temp table _news (title text, slug text, category text, more_categories jsonb, excerpt text, lead text, quote_text text, body text, published_at date, is_published boolean, author text) on commit drop;
insert into _news values
  ('O''Sullivan Captures Fifth World Crown', 'osullivan-captures-fifth-world-crown', 'Professional Snooker', '[]'::jsonb, 'Ronnie O''Sullivan beat Barry Hawkins 18-12 in the final of the Betfair World Championship to become the first player to win back-to-back Crucible crowns since Stephen Hendry''s heyday.', null, '""I thought it was a brilliant final," said O''Sullivan. "The snooker overall was very good. Barry has got the game to do well at a tournament like this. He looks like he could do another World Championship to me. He looks as fresh as a daisy and he is a very efficient player. I put him under a lot of pressure this afternoon, I felt I had to. Tonight he came out all guns blazing and I feared the worst. I had to make my chances count because if I did not then he could have got it back to 15-14.""', 'Ronnie O''Sullivan beat Barry Hawkins 18-12 in the final of the Betfair World Championship to become the first player to win back-to-back Crucible crowns since Stephen Hendry''s heyday.

more Not since Hendry reigned supreme on snooker''s biggest stage from 1992 to 1996 has a player successfully defended the title, but a wonderful display from O''Sullivan in the final saw him take the trophy again. It is his fifth world title - adding to those he won in 2001, 2004, 2008 and 2012 - a feat only previously achieved by Hendry and Steve Davis. In one of the best conclusions to the tournament in recent years, O''Sullivan produced mesmerising spells of heavy scoring and compiled six centuries, a feat never achieved before in the final, as well as ten more breaks over 50. Hawkins also played his part with a brave display, but ultimately couldn''t hold back an opponent who added discipline and determination to his sublime skill. The Rocket, whose prize was £250,000, has won all five of the world finals he has contested. At 37, O''Sullivan is the oldest winner since Ray Readon who was 45 when he won the sixth of his crowns in 1978. Three weeks ago, Chigwell''s O''Sullivan stated his goal of winning the event while in his 40s. Despite his subsequent suggestions that this could be his last Crucible campaign, he will surely be back for several more tilts and could yet match the tallies of Davis (six) and Hendry (seven). Remarkably, he has won the title having played just one competitive match this season - at an untelevised PTC event last September - prior to the Sheffield showpiece. There can be few others in any sport capable of overcoming such a lack of competitive sharpness through sheer natural ability. In all, O''Sullivan has now won 25 ranking titles, equal with John Higgins and behind only Davis (28) and Hendry (36). Hendry was 30 when he won the last of his seven world crowns, whereas O''Sullivan''s game has matured through his 30s. His work with renowned psychiatrist Dr Steve Peters has helped him deal with the stress of being under the spotlight, allowing his talent to thrive. O''Sullivan admitted tonight he wonders how many more titles he could have won if he had met Peters 20 years ago. Hawkins, who had never previously been beyond the second round at the Crucible, had a brilliant fortnight, knocking out the likes of Mark Selby and Ding Junhui. He was not over-awed by the final, when others might have crumbled against an unstoppable opponent. Hawkins goes back to Ditton in Kent with £125,000, by far his biggest pay-day, and the knowledge that he has the game to compete at the very top level. O''Sullivan led 15-10 after the afternoon session, which was watched by celebrities including actor Stephen Fry, darts king Phil Taylor, artist Damien Hirst and musicians Serge Pizzorno and Noel Fielding. Hawkins started the evening in superb style with a break of 127, equalling the record of eight centuries in the final. And when he took the next with a run of 66 to make it 15-12, he looked in with a chance of causing the biggest upset since Joe Johnson stunned Davis in 1986. But O''Sullivan - as he did throughout the event - responded to pressure in clinical fashion. Breaks of 77, 88 and 86 saw him reel off the last three frames in just 30 minutes. His young son Ronnie Jnr as well as mum Maria and sister Danielle joined him on stage as the Crucible crowd rose to applaud their hero. "I thought it was a brilliant final," said O''Sullivan. "The snooker overall was very good. Barry has got the game to do well at a tournament like this. He looks like he could do another World Championship to me. He looks as fresh as a daisy and he is a very efficient player. I put him under a lot of pressure this afternoon, I felt I had to. Tonight he came out all guns blazing and I feared the worst. I had to make my chances count because if I did not then he could have got it back to 15-14." Asked which of his five titles meant the most, he said: "The first one was always one for me to get over. That was a massive relief. The next two I just kind of won and did not really feel much. I was in that place where I was over analysing and criticising myself too much. Last year I came here off the back of two lean years and people were writing me off. At times I felt I played some of the best snooker I had ever played and it was the same again this year. Having worked with Steve Peters I was able to hold my emotions a lot more than before. "In the final I had everything to lose and nothing to gain. I know how good Barry is - to the outside world they think I should never lose but on the snooker circuit everybody knows how good Barry is. "I will enjoy the moment and enjoy one of the best moments of my career. It has not really sunk in yet and I feel like I have just done a job. It will probably sink in a few days time." Asked how many events he is likely to play in next year, O''Sullivan added: "I just do not know what is going to happen because things are always changing. Come December or January I will have a much better idea of what I will be doing." Hawkins said: "I put him under as much pressure as I could. But every time I missed an easy ball he punished me. I tried my hardest in that final and I just made a few more mistakes than Ronnie. You cannot afford to do that against a player of his calibre because he is just unbelievable. The way he makes it look so easy is just amazing. "I still felt I could win the match. I felt really good out there even with all the pressure. I was just gutted that I missed some balls. I was hitting some nice big breaks. I am delighted with the tournament that I have had and hopefully I will have a lot more years in me yet. "It is a strange feeling to be honest - all of my friends and family are buzzing a lot more than me. I am just pleased that I gave him some sort of a game. I just kept trying hard. I am sure I will collapse now, especially after the last couple of weeks. "I hope that I will be able to win it here one day but Ronnie is by far the best player in the world. There is no shame in that at all really. I tried my hardest out there and I am proud of what I did." Article courtesy of the World Snooker Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('O''Sullivan Crushes Ding', 'osullivan-crushes-ding', 'Professional Snooker', '[]'::jsonb, 'Ronnie O’Sullivan beat Ding Junhui 10-3 in the final of the Ladbrokes World Grand Prix, and has now won four ranking titles in a single season for the first time in his career.', null, '“It wasn’t the best performance, I dragged Ding down to my level,” said O’Sullivan, who won his first ranking title back in 1993 at the same venue, when the UK Championship was staged in Preston. “He lost his concentration and I took bits and pieces. I’m always going to score, even when I’m not at my best my cue ball control is still good.”', 'Ronnie O’Sullivan beat Ding Junhui 10-3 in the final of the Ladbrokes World Grand Prix, and has now won four ranking titles in a single season for the first time in his career.

more O’Sullivan made three centuries and three more breaks over 50 in a dominant display at the Guild Hall in Preston to take this title for the first time and capture the £100,000 top prize. It’s the 32nd ranking title of his career, leaving him just four behind Stephen Hendry’s record of 36. O’Sullivan has now won over £600,000 in prize money during the 2017/18 campaign and could become the first player to go past the £1 million barrier in a single season – indeed the £425,000 winner’s cheque at the World Championship alone would take him past that mark. He had only once previously won three ranking titles in a season – back in 2004/05 – but having landed the English Open in October, Shanghai Masters in November and UK Championship in December, he has now surpassed that – and with five ranking events still to go this term. One more crown would see him equal the record of five in a season, held by Hendry, Ding and Mark Selby. At the age of 42, O’Sullivan has produced the most consistently excellent snooker of his career over the past five months, with his long potting, break building and tactical game all in superb shape. He remains second behind Selby in the world rankings but the gap is closing. China’s Ding missed out on the 14th ranking title of his career and second of the season, having won the Yushan World Open in September. The world number four banks £40,000 as runner-up. The first four frames today were shared, then Chigwell’s O’Sullivan pulled away as breaks of 124 and 105 put him 4-2 ahead. Ding won frame seven on the colours to stay in touch, but his opponent made 59 and 120 (his tenth century of the tournament) to lead 6-3 at the end of the first session. O’Sullivan took the first two frames of the evening session to extend his advantage to 8-3. Ding had a scoring chance in frame 12 but made only 16, then banged his head on the side of the table in frustration as the contest slipped away. O’Sullivan punished him to make it 9-3, and a quickfire break of 83 in the next completed the scoreline. “It wasn’t the best performance, I dragged Ding down to my level,” said O’Sullivan, who won his first ranking title back in 1993 at the same venue, when the UK Championship was staged in Preston. “He lost his concentration and I took bits and pieces. I’m always going to score, even when I’m not at my best my cue ball control is still good.” Asked whether he felt when he won that 1993 title he would still be collecting silverware a quarter of a century later, O’Sullivan replied: “Yes, I always believed I could dominate the table, if the form is there titles will just come. It’s great to have 25 years since my first title and hopefully this isn’t my last.” O’Sullivan now heads straight to Cardiff for the Welsh Open which starts on Monday (click here for the match schedule). He added: “It sounds weird but it might be good to lose early there, spend a week in the punditry box, do some analysis and watch the others slug it out. I’ve got my title in the bank.” And looking ahead to the Crucible in the Spring, where O’Sullivan has triumphed five times, he said: “I don’t think I’m capable of winning another world title. You need a lot of staying power there and I am too old. I can play well over a few days, but the World Championship is all about stamina and consistency which is not suited to my game at the moment. But we’ll wait and see.” Ding said: “I had chances in the first session but didn’t take them. It looks like I played rubbish. It is a always dream to play Ronnie in a final and I wanted to play well against him – it doesn’t always happen, but I tried. For the last few months I didn’t play well, but I felt good this week.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('O''Sullivan Lands English Open Crown', 'osullivan-lands-english-open-crown', 'Professional Snooker', '[]'::jsonb, 'Ronnie O’Sullivan won the 29th ranking title of his career, matching the total of John Higgins, by beating Kyren Wilson 9-2 in the final of the Dafabet English Open in Barnsley.', null, 'It is great to win another ranking title. I am my own worst critic at times but it was very, very good today,” said the Rocket. “I made a lot of good and important breaks, and felt good among the balls. I will keep driving myself on to reach a higher level.', 'Ronnie O’Sullivan won the 29th ranking title of his career, matching the total of John Higgins, by beating Kyren Wilson 9-2 in the final of the Dafabet English Open in Barnsley.

more O’Sullivan was in superb break building form as he made four centuries and five more contributions over 50 in a one-sided final. His pot success rate was 98% over the contest and he won the last six frames in just 70 minutes before receiving the Steve Davis Trophy and a cheque for £70,000. This was the first of the season’s Home Nations events and O’Sullivan is now a quarter of the way to winning a £1 million bonus. If he goes on to win the remaining three events in Belfast, Glasgow and Cardiff then he would bank that unprecedented prize. He heads to the Northern Ireland Open next month to continue the quest. It’s O’Sullivan’s first ranking title since he won the 2016 Welsh Open, 20 months ago. The 41-year-old from Chigwell has now overtaken Steve Davis on the all-time list of ranking event winners and drawn level with Higgins on 29 crowns, though he’s still well short of Stephen Hendry’s record of 36. An ankle injury suffered while running almost forced O’Sullivan to pull out before the event started, but he overcame that discomfort and ended the week by proving that, when in-form and focused, he remains a devastating force on the baize. The presence of psychiatrist Steve Peters in his corner for much of this week’s tournament was surely a factor in O’Sullivan’s success. He moves up from 12th to 9th in the world rankings ahead of a busy schedule which could see him play in seven more tournaments before Christmas. Kettering’s 25-year-old Wilson missed the chance to win his second ranking title having earned his first at the 2015 Shanghai Masters. He has now lost his last three ranking finals, against tough opponents in Anthony McGill, Ding Junhui and now O’Sullivan. The £30,000 runner-up prize sees the Warrior up from 15th to 12th in the rankings. O’Sullivan carved out a 6-2 lead in the first session with top breaks of 115, 54, 131, 77, 87 and 96. Wilson had chances to close the gap in the first frame of the evening session but couldn’t take them and a run of 50 from O’Sullivan made it 7-2. By now unstoppable, O’Sullivan compiled brilliant runs of 127 and 132, his 11th and 12th centuries of the tournament, to finish the match in style. “It is great to win another ranking title. I am my own worst critic at times but it was very, very good today,” said the Rocket. “I made a lot of good and important breaks, and felt good among the balls. I will keep driving myself on to reach a higher level. “I am enjoying the challenge of hanging in there against these young players, but you play well if you have to – and I know what a good player Kyren is. The foot is ok, I suppose I have to give some credit to the trainers I have been wearing all week!” Asked about the £1 million bonus, O’Sullivan added: “Listen, it is another 21 matches and it is do-able. Anything is possible but over these short matches that are best-of-seven frames, it will be very tough.” Wilson said: “I feel like I made it too comfortable for Ronnie at times. He obviously put me right under pressure, he played out of his skin today. To hold that level of concentration throughout the whole day was very impressive. “I didn’t feel like I was completely out of the match after the first session. I wasn’t making elementary mistakes, but I was catching the odd safety thick. I felt like when I got in to score, I was alright. I knew I had to try and get off to a good start. “I’ve lost to Ding and Ronnie in finals this season. They both played out of their skin. They both said it was one of their best performances in finals. It’s nice to know that they feel they have to play like that to beat me. But I wouldn’t mind doing it to somebody else! “Ronnie was a hero of mine growing up. So it is nice to have him say good things about me. I just have to focus on my own game and try not to get too carried away with myself.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('O''Sullivan The Champion Again', 'osullivan-the-champion-again', 'Professional Snooker', '[]'::jsonb, 'Ronnie O''Sullivan defended his Dafabet Champion of Champions title in magnificent style as he beat Judd Trump 10-7 in a match of the highest quality.', null, '"One hundred percent I would have won if it was against anyone else, I would have won comfortably. For me, that is what the game is all about, getting that sort of opponent to bring you on and in other sports there is that kind of rivalry and I think I need Ronnie to push myself to the next level."', 'Ronnie O''Sullivan defended his Dafabet Champion of Champions title in magnificent style as he beat Judd Trump 10-7 in a match of the highest quality.

more It capped a week that saw the Rocket record victories over Stuart Bingham, Marco Fu, Ding Junhui and then Trump in Coventry to claim the £100,000 top prize. Such was the standard of both men that there were six centuries in the 17 frames as well as another 11 breaks over 50 as both players were at the peak of their respective games. In the end, it was 38 year-old O''Sullivan''s relentless break-building that secured him the victory after Trump had clawed his way back from 8-3 down to win four successive frames including back to back centuries. That had got him to within one of his opponent but O''Sullivan turned the screw, taking the last two frames as he ended with another fabulous century, his fourth of the match. "That was as well as you can play," said O''Sullivan after winning his first title of the season. "I had four centuries, two or three 70s and a couple of 80s. That is nine frames without reply. Judd played some good stuff as well and I am happy to have been involved in a match of such quality. "At 8-3 I knew Judd is an aggressive player and would come out all guns blazing, he wasn''t going to sit on the fence and wait for his chances, he was going to try and make something happen. He potted some fantastic balls and got back in, but I always said in my mind that if he gets to within one or two frames then the balls get a bit harder, a bit more pressure mounts. "I thought be patient, try and keep him honest and that is what I did. That is when it matters, at the end of the match." O''Sullivan had set the scene in the opening rack with a blistering 137 total clearance and then followed that with a frame-winning break of 82 to take the early lead. Trump to his credit, took the next two frames before runs of 87 and 80 restored the Rocket''s two frame margin. It was mesmerising stuff from O''Sullivan and after Trump secured the seventh frame, a brace of 130-plus breaks from the defending champion crowned an outstanding session as he took a 6-3 lead into the evening. O''Sullivan won the first two when they resumed to get to 8-3 as Trump looked dead and buried. He mounted his superb fight back though, before O''Sullivan pulled away to win. For Trump, there were plenty of positives to take in defeat: "It was a good game, I really enjoyed it. It was probably one of the only games where I am not really too disappointed about losing. "One hundred percent I would have won if it was against anyone else, I would have won comfortably. For me, that is what the game is all about, getting that sort of opponent to bring you on and in other sports there is that kind of rivalry and I think I need Ronnie to push myself to the next level. "I knew I was playing okay at 8-3 down but it just wasn''t going right for me. Then he missed one or two and that was it, I got a bit of confidence and momentum, got back into the game and then even at 8-7 I nearly nicked that frame and that would have been a big frame. The way he shut out the match was just typical Ronnie. "I showed a lot of maturity this week. At times I wasn''t playing great stuff but I just stuck in there, which I probably wouldn''t have done a few seasons ago. The way I came back today under pressure, there is a lot to take and a lot to look forward to." Ronnie O''Sullivan 10-7 Judd Trump 137-0 (137), 82-0 (78), 25-100 (31, 39, 30), 63-73 (O''Sullivan 40, Trump 47), 137-0 (50, 87), 80-0 (80), 34-89 (58), 139-0 (139), 134-0 (134), 70-61 (Trump 56, O''Sullivan 71), 114-23 (40, 70), 9-113 (102), 0-100 (100), 0-70 (69), 0-90 (90), 82-46 (63), 109-0 (109) Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('O''Sullivan The Master', 'osullivan-the-master', 'Professional Snooker', '[]'::jsonb, 'Ronnie O''Sullivan beat Mark Selby 10-4 in the final of the Dafabet Masters to win the title for the fifth time.', null, '""I''ve got five World, five Masters and four UKs now and I never dreamed I would do this well. It''s just nice to be playing and competing at 38 because most of the others now are in their late 20s or early 30s.', 'Ronnie O''Sullivan beat Mark Selby 10-4 in the final of the Dafabet Masters to win the title for the fifth time.

more O''Sullivan did most of the damage in the first session by taking a 7-1 lead, and despite a few late wobbles, he clinched victory with plenty to spare to win the £200,000 top prize. The 38-year-old from nearby Chigwell received vibrant supported from a packed house at Alexandra Palace during his record tenth final appearance. His fifth victory in snooker''s most prestigious invitation event brought him within one of Stephen Hendry''s record of six. Matching the imperious form which gave him the World Championship crown in 2012 and 2013, O''Sullivan conceded just seven frames during the tournament, beating Robert Milkins 6-1, Ricky Walden 6-0 and Stephen Maguire 6-2. His performance against Walden was one of the most devastating displays ever seen in a televised event. Over his four matches he made two centuries and 19 more breaks over 50. It was his third final against Selby; in 2009 O''Sullivan won 10-8 and a year later fierce competitor Selby gained revenge with a 10-9 success. O''Sullivan''s work with psychiatrist Dr Steve Peters in recent years has helped him cope with the frustrations of not having everything his own way during matches, and the challenge of tussling with never-say-die opponents like Selby. This time last year, O''Sullivan was doing voluntary work on a farm in Essex, during a long sabbatical from snooker. He now seems to have found a balance in his life on and off the table which has enabled him to play the best snooker of his career over the past two years. With five World titles and four in the UK Championship, O''Sullivan now has 14 ''triple crown'' victories and it is conceivable that he could beat Hendry''s record of 18. Leicester''s Selby was playing in his fifth Masters final in seven years and chasing his fourth title, but had to settle for the £90,000 runner-up prize. Encouraged by a vast entourage including Rolling Stone Ronnie Wood, artist Damien Hirst, actor Marc Warren, and girlfriend Laila Rouass, as well as his kids Lily (7) and Ronnie Jnr (6), O''Sullivan started the evening session 7-1 up following breaks of 97, 70, 96 and 53 during the afternoon. He quickly extended his lead tonight with a run of 90. A 9-1 lead looked certain until, in a bizarre end to the tenth frame, O''Sullivan missed a sitter of a brown off the last red. Selby cleared to the black then rattled it in the jaws, only for O''Sullivan''s attempt to finish hanging over a top corner. Selby tapped in the black for 8-2, then made an impressive 67 to win the next after his opponent had failed on a red at 27-0. Selby had a clear chance in the next as he threatened a trademark fight-back, but missed the pink off its spot on 23. O''Sullivan edged ahead and potted the last red to make it 9-3 at the interval. When they returned, a run of 67 from Selby saw him pull one back, but a clinical 72 from O''Sullivan in the next sealed the title. "It''s a great feeling," said O''Sullivan. "I expected it to be 10-9 or 10-8 because Mark is such a competitor and there''s not much between us. He plays better when he''s behind and you''re never over the line against him until you pot the last ball. "I missed an awful brown to go 9-1 and then I was concerned he would get it back to 8-4, so I was pleased to win the frame to go 9-3 at the interval. I told myself to just keep competing. The match against Ricky Walden was a one-off, I was never going to be able to do that against Mark. "I''ve got five World, five Masters and four UKs now and I never dreamed I would do this well. It''s just nice to be playing and competing at 38 because most of the others now are in their late 20s or early 30s. I have set myself a target of winning the world title when I''m in my 40s. Tom Watson nearly won the Open at 59. "I''m competing with the players from the new era and the standard is high. To beat Mark 10-4 after the epic finals we have had is great. The way I''ve played in the last two years is how I wanted to play for the previous 18. Better late than never I suppose." Selby said: "There''s no one who wins frames in one visit like Ronnie, and makes it look so easy. I should have won the fourth frame and it might have been different if it had gone 3-1. Even at 7-1 I never felt I was out of it and believed I could win. I tried to put pressure on him and build my own confidence. "I''m disappointed to lose in the final of both the UK and the Masters but if I keep working hard hopefully I''ll be winning again soon. I have won this before so it doesn''t hurt as much." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('O''Sullivan Wins UK Classic', 'osullivan-wins-uk-classic', 'Professional Snooker', '[]'::jsonb, 'Ronnie O''Sullivan triumphed in one of snooker''s all-time classics, beating Judd Trump 10-9 in the final of the Coral UK Championship.', null, '"From 9-5 up to 9-9, he''s not missed a ball really - he''s just knocked everything in and I didn''t get a chance. At 9-8 I had a good chance but to be honest my mind was just gone, I felt really nervous after having such a big lead because you think if I lose it from there, the disappointment would''ve been unbelievable."', 'Ronnie O''Sullivan triumphed in one of snooker''s all-time classics, beating Judd Trump 10-9 in the final of the Coral UK Championship.

more A wonderful match between arguably the sport''s two most exciting talents saw Trump come from 9-4 down to 9-9 with a series of rapid breaks. But it was O''Sullivan who grasped his chance in the deciding frame to win the UK title for the fifth time. A capacity crowd of over 1,000 at the York Barbican were left gasping as snooker once again showcased its capacity to provide great drama. A contest which included three centuries and nine more breaks over 50, with an average frame time of just 15 minutes, was finally settled when O''Sullivan laid a clever snooker in the 19th frame, and held his nerve with a break of 51 to take the £150,000 top prize. O''Sullivan has now won 15 Triple Crown events - his five UK crowns matching his five World Championships and five Masters - just three behind Stephen Hendry''s record of 18. And his haul of ranking events moves to 27, just one behind Steve Davis though still nine adrift of Hendry. He is up to third in the world rankings, behind Ding Junhui and Neil Robertson. Remarkably, the Rocket first won the UK crown 21 years ago at the age of just 17, the youngest player ever to land a ranking title. He went on to win it in 1997, 2001 and 2007. Few competitors in any sport have been prolific winners over such a long period. Ten days ago, he travelled from Chigwell to York uncertain whether he would even be able to compete in the tournament, having injured his left ankle while running. With the help of Sheffield United''s physio team, the injury healed quickly and O''Sullivan - literally - got into his stride as the tournament progressed. He made a magical 147 maximum break en route to the final - earning a £44,000 bonus - and ended up clutching the trophy. It has been quite a year for O''Sullivan, bookended by fabulous displays at the Dafabet Masters in January and here in York in December. In between he has also captured the BetVictor Welsh Open and Dafabet Champion of Champions (beating Trump 10-7 in another excellent final). His defeat at the hands of Mark Selby at the World Championship in May was his only blemish, and that''s a title the 39-year-old will be determined to recapture next Spring. Bristol''s 25-year-old Trump - who goes home with £70,000 - has found consistency in his game this season and only O''Sullivan has been able to stop him in the last two domestic tournaments. Up to seventh in the rankings, he will surely be competing for major titles in the coming months. O''Sullivan led 5-3 after the first session with top breaks of 82 and 81. Trump had first chance in the opening frame of the evening session but could only make 48, and O''Sullivan eventually took it with a 53 clearance. The next followed a similar pattern as Trump made 56 before O''Sullivan replied with 36 then cleared from the last red to extend his lead to 7-3. Trump pulled one back but a marvellous 133 total clearance from O''Sullivan left him 8-4 ahead at the mid-session interval. And when the Essex cueman compiled runs of 54 and 35 to take frame 13, victory seemed a formality. Trump''s fight-back began when he took a scrappy 14th frame. Playing with total freedom, he suddenly found his rhythm and fired in breaks of 120, 127 and 86 to close to 9-8. O''Sullivan had a winning chance in the next but ran out of position at 59-0 and Trump cleared with 67 to bring the match to a fitting conclusion. O''Sullivan had first chance in the decider and made 16, then Trump replied with 14. After a safety exchange, O''Sullivan trapped his opponent in a tough snooker behind the green, and from the chance that followed he clinched the title with 51. O''Sullivan said: "I had the upper-hand for most of the match and I just lost a bit of concentration at 5-1. I went off the boil a bit and let him back to 5-3. "From 9-5 up to 9-9, he''s not missed a ball really - he''s just knocked everything in and I didn''t get a chance. At 9-8 I had a good chance but to be honest my mind was just gone, I felt really nervous after having such a big lead because you think if I lose it from there, the disappointment would''ve been unbelievable. "The pressure was just mounting and mounting and it''s difficult to put that out of your mind but in the last frame I managed to get a chance. The balls were nice and I had to just concentrate on hitting solid shots. "Years ago at 9-4 down, you would''ve probably expected to have got three or four chances and someone wouldn''t have come at you that quick, but nowadays you get players who can reel off three, four or five frames off on the bounce. "It''s just a game of momentum really - I had the early bit of momentum with things going for me and Judd had it towards the end. "Judd is a tough opponent. He''s very dynamic and he''s very explosive. He''s got so much cue power, he can pot like you wouldn''t believe, he''s fearless and that''s difficult because he''s in your face the whole time. "If you go slightly off the boil he''s on you and everyone else is going to have to get on their game to stay with him or keep him in check because if he''s allowed to get away he will do some damage in the game because he''s a strong player." Trump, who missed out on his fifth ranking title and second UK crown, said: "I knew I had that form in me but when Ronnie clears up on you every time it is kind of demoralising. I did it to a couple of opponents and it really hurts. "Towards the end I was kind of giving in but then I managed to get to 9-5 and then I got a few chances and made a few breaks and felt good. I made a really good clearance to go 9-9 and then I felt so relaxed going out there. "I''m a bit annoyed that I didn''t really have a chance in the last but I didn''t bottle it and gave it my best. "You''ve got to get off to a good start against Ronnie. You can''t be giving him five frame leads. I know when I get going in most matches I tend to reel off three or four frames so I know I''ve always got it in me. But once again I left it too late and fair play to Ronnie, he took them well in the last frame and overall he was a deserving winner." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('O''Sullivan equals Hendry record', 'osullivan-equals-hendry-record', 'Professional Snooker', '[]'::jsonb, 'Ronnie O’Sullivan won his sixth Dafabet Masters title with a 10-1 demolition of Barry Hawkins in the final.', null, '“I was pleased with the way I approached the game from the off,” said five-time World Champion O’Sullivan. “I kept my focus, my discipline and my temperament, and tried to control all the things that you can control. (Psychiatrist) Steve Peters gave me some things to work with, and it made sense. I was able to contain my emotions and not think about the importance of the match. I relaxed into the game and played well in spells.', 'Ronnie O’Sullivan won his sixth Dafabet Masters title with a 10-1 demolition of Barry Hawkins in the final.

more O’Sullivan has now won snooker’s biggest invitation event six times, having previously lifted the trophy in 1995, 2005, 2007, 2009 and 2014, matching the record set by Stephen Hendry, who won five titles in a row from 1989-93 and another in 1996. Watched by a capacity crowd of nearly 2,000 at Alexandra Palace in London, O’Sullivan banked the £200,000 top prize after dominating the final, making a century and six more breaks over 50. It was the most one-sided Masters final since Steve Davis beat Mike Hallett 9-0 in 1988. The 40-year-old from Chigwell has now won 16 Triple Crown tournaments, just two shy of Hendry’s record of 18, and he’s the oldest Masters champion since Ray Reardon won in 1976 age 43. In 22 appearances at the Masters, O’Sullivan has played 63 matches and reached 11 finals, both also records. O’Sullivan took several months away from snooker at the start of this season, returning to action in mid-December and playing his first televised tournament this week. It was a triumphant return to the limelight, reminiscent of his 2013 World Championship victory (also coming with a final defeat of Hawkins) after almost a year’s sabbatical. Once again the Rocket has proved that his sheer natural brilliance can make up for any lack of competitive sharpness. At the very top level, he remains the man to beat. He insists that a slipped disc in his lower spine has caused an imbalance in his cue action – yet he has produced spells of sublime snooker this week and has looked destined to win the trophy since coming from 4-2 down to beat Mark Williams 6-5 in the opening round. Mark Selby and Stuart Bingham were his other victims. Hawkins may have been on the wrong end of an emphatic scoreline today but he must take heart from his run this week as he had never got past the first round in five previous Masters appearances. He goes back to Ditton with a cheque for £90,000 and a confidence boost ahead of a packed schedule in the coming months. World number six O’Sullivan led 7-1 after the opening session with top breaks of 70, 136, 52, 77 and 72. If eighth seed Hawkins was to launch a fight back he had to win the first frame of the evening session. He had chances, but it came down to the colours and O’Sullivan led by 13 points when he fluked the pink, missing a pot to one top corner only for the pink to glance off the white and drop into another. Hawkins failed to score another point as his opponent rattled through the last two frames with runs of 66 and 82. O’Sullivan has now won nine matches in a row against Hawkins having lost their first meeting back in 2002. “I was pleased with the way I approached the game from the off,” said five-time World Champion O’Sullivan. “I kept my focus, my discipline and my temperament, and tried to control all the things that you can control. (Psychiatrist) Steve Peters gave me some things to work with, and it made sense. I was able to contain my emotions and not think about the importance of the match. I relaxed into the game and played well in spells. “It’s unbelievable to win six titles, and I’ve lost in five finals so I could have had a few more. John Higgins and I should be playing in the seniors event this year so it’s great that we are still winning big titles. This gives me massive confidence because it shows that I don’t have to be at the top of my game as long as I’m mentally on the ball. You can play your way into form sometimes. I got lucky that no one played their best against me this week. “My back and my legs are still weak so I need to work on that with a physiotherapist. I am not able to stabilise myself as well as I was before the injury. It’s at the back of my mind so I just want to clear that out of the way so I can concentrate on playing.” Hawkins said: “If someone had told me at the start of the week I would make it to the final and play Ronnie, I would have ripped their arm off. But I didn’t perform today. It was disappointing for me that’s for sure – it feels like the final was over in a blink of an eye. “I was sitting there and I was thinking I don’t feel like I’ve even been involved in the final. I felt so good against Judd in the semi-final and I was hoping to feel the same out there today but I just didn’t get going at all. I was definitely cueing around corners today – it didn’t feel like my arm.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('O''Sullivan wins 30th ranking title', 'osullivan-wins-30th-ranking-title', 'Professional Snooker', '[]'::jsonb, 'Ronnie O’Sullivan beat Judd Trump 10-3 in the final of the Shanghai Masters to win the 30th ranking title of his career.', null, '““I knew Judd was in good form because he has been playing well all week,” said O’Sullivan. “My mind has been as good as it has ever been this week. There were a few moments where it got a big edgy but I managed to think my way through. I wasn’t at my best today but mentally I was in the right place. ”', 'Ronnie O’Sullivan beat Judd Trump 10-3 in the final of the Shanghai Masters to win the 30th ranking title of his career.

more O’Sullivan did the bulk of the damage in the first session by going 7-0 ahead, and he shared the next six frames to secure the trophy and £150,000 top prize. The Chigwell cueman moves ahead of John Higgins – who he beat in yesterday’s semi-finals – to second on his own on the all-time list of ranking event winners. It’s his second ranking title within a month having won the English Open in October, and he also reached the final of last week’s Champion of Champions where he lost to Shaun Murphy. O’Sullivan turns 42 next month but given the consistent excellence of his recent form, coupled with his dedication to health and fitness, it may not be long before he overtakes Stephen Hendry’s record of 36 ranking crowns. The opportunities to add to his tally come thick and fast as the Rocket now heads to Belfast to compete in the Dafabet Northern Ireland Open, followed by the Betway UK Championship and Scottish Open before Christmas (tickets for all of these events are still available – for details click here). In winning his second Shanghai Masters title, O’Sullivan moves from seventh to fourth in the official world rankings and leaps to the top of the one year list. Bristol’s Trump has now lost in the final in Shanghai three times having finished runner-up to Higgins in 2012 and Kyren Wilson in 2015, and overall he has lost nine of his 17 career ranking finals. He still banks £75,000 and he’s up to second in the rankings, behind only Mark Selby. Breaks of 91, 76, 81, 56 and 70 helped O’Sullivan to win the first seven frames today. Trump finally got going with a run of 102 then cleared from blue to black in the last frame of the opening session to give himself hope of a fight back at 7-2. O’Sullivan started the evening session strongly with a 108 to go 8-2 up. Trump made a 64 in winning frame 11 and looked set to take the 12th until he broke down on 63, allowing his opponent to clear from the last red for 9-3. And when O’Sullivan cleared the colours to win frame 13 the contest was over. “I knew Judd was in good form because he has been playing well all week,” said O’Sullivan. “My mind has been as good as it has ever been this week. There were a few moments where it got a big edgy but I managed to think my way through. I wasn’t at my best today but mentally I was in the right place. “I have had a fantastic last four weeks. I feel a bit tired but I don’t mind that if it means winning tournaments. I’ve got my titles in the bank and I can build on that. “I’m not one for setting myself targets, but there’s nothing that can’t be done. If you said to me I would have another ten or 15 years playing snooker and be happy, but not get (Hendry’s) record, I would take that. I’d prefer that to playing for two or three more years and getting to 38 titles. It’s all about longevity for me. I enjoy the tour and the travelling and having a good life. “People talking about beating Hendry’s records but it doesn’t really enter my thought process. The main thing for me is to enjoy playing and to keep it going as long as I can.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('O''Sullivan wins record seventh masters crown', 'osullivan-wins-record-seventh-masters-crown', 'Professional Snooker', '[]'::jsonb, 'Ronnie O’Sullivan beat Joe Perry 10-7 in the final of the Dafabet Masters to become the first player to take the title seven times.', null, '“Joe’s a fantastic player. You don’t get to the final of the Masters without being a really top quality player. Even if everything had gone well for me, I’d still have had a massive match on my hands.', 'Ronnie O’Sullivan beat Joe Perry 10-7 in the final of the Dafabet Masters to become the first player to take the title seven times.

more The Rocket had previous shared the record of six with Stephen Hendry but now stands alone with one more crown, after coming from 4-1 down to win nine of the last 12 frames against under-dog Perry at Alexandra Palace. O’Sullivan received a cheque for £200,00 and lifted the Paul Hunter Trophy which was named after Hunter for the first time, in memory of the three-time Masters winner who died in 2006. Chigwell’s O’Sullivan has now won 17 Triple Crown titles in total, with five wins apiece at the World and UK Championships, which is one behind Hendry’s record of 18. World number 13 O’Sullivan won his first piece of silverware since the Welsh Open last February, having lost in the final of the European Masters, Champion of Champions and UK Championship this season. In fact he has produced his best snooker only in spells this week – notably in his semi-final win over Marco Fu on Saturday – but, at the age of 41, O’Sullivan remains a formidable force, particularly in London where most of the 2,000-strong crowd get behind him. This was his 12th Masters final in all and ninth since 2004. It was also a landmark week for Perry as he reached the final of a Triple Crown event for the first time, albeit one which finished in disappointment as he failed to capitalise on his early dominance. The 42-year-old from Chatteris receives £90,000, his second biggest career pay day after the £100,000 he banked for winning the 2015 Players Championship. It was 4-4 at the end of the first session then O’Sullivan won a scrappy opening frame tonight to go ahead for the first time. That gave him a momentum boost and he sailed through the next three frames with top breaks of 68, 56 and 85 to lead 8-4. Perry’s resistance appeared to be fading at that stage, having lost seven frames in a row, but the world number nine found new impetus after the interval and fired runs of 117 and 92 to close to 8-6. And he had a chance early in the next but missed a tricky opening red along the top cushion. O’Sullivan punished him with a superb 112 to get to the brink of victory. Perry dominated the 16th frame with runs of 39 and 53 to make it 9-7. Frame 17 came down to a safety exchange on the last red. Perry went full-blooded for a pot to a baulk corner but it missed its target and that proved his last shot as O’Sullivan cleared to cross the winning line. “That’s probably the best win I’ve had in my life,” said O’Sullivan. “Given the circumstances with my cue tip (which he had to change during his match with Fu). Yesterday it played fantastic, today I couldn’t do much with it. I just managed to hold it together under the most extreme pressure. I couldn’t play three quarters of the shots that I wanted to. I just had to hang in there and I’m proud I was able to do that. “Joe’s a fantastic player. You don’t get to the final of the Masters without being a really top quality player. Even if everything had gone well for me, I’d still have had a massive match on my hands. “I’m not really into history and records. I just like to play, I just like to enjoy. I don’t want to stop at seven titles. I just want to keep enjoying playing the sport that I’ve played for a long time. “I’m over the moon to still be competing. I don’t expect to be the best player in the world because I don’t play as much as the other guys. I’ve done everything there is to do in the game. I’ve got nothing to prove. I just enjoy competing at tournaments, getting up in the morning and putting the practice in. I love a challenge. I will keep going until the wheels come off. “Paul Hunter was a legend of the game. A beautiful guy, loved by all the players. I always say if he is looking down on us, we love you very much. You’re not forgotten. It’s great that this tournament is named after Paul. I’m just so happy to have put my name on that trophy.” Perry said: “I’m a little bit disappointed. I enjoyed every minute of it. I got Ronnie on the day you want to get him on. He wasn’t in full flow today, but it just goes to show the way his mind is now, and his all round game is good. “I just missed the boat a bit at 4-1. I didn’t start seeing the winning line or anything but the pressure switched and I didn’t handle it very well. I came out tonight in the same sort of vein. That was the worst four frames I’d played all week. The interval came at a good time. I got my head back on it and really enjoyed the conclusion of the match. I was just a fraction away from making it 9-8 – and then who knows.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Oh what a night for Mevagissey!', 'oh-what-a-night-for-mevagissey', 'Match Reports', '[]'::jsonb, 'It was a great night for the Mevagissey teams as all four sides won in their respective leagues.', null, 'Tregonissey ‘B’ came from 2-0 down to record their sixth successive win with victory at third-placed Bethel ‘C’. Howard Brett and Ben Stunnell, who beat Richard Opie put the home side in the driving seat but Phil and Justin Hooley along with Ryan Thomas’ last frame win over Leigh Rosevear sees Treggy open up a four-point lead at the top.', 'It was a great night for the Mevagissey teams as all four sides won in their respective leagues.

more The ‘A’ team have opened up a six-point lead in the Victory League after whitewashing Bugle ‘B''. Matt Mills, James Popperwell, Leighton Varcoe, Phil Staley and Pete Chambers were all victorious. Mevagissey ‘B’ picked up a useful 3-2 win at St Stephen ‘A’ but the home side’s point move them up level with Bugle ‘B’ at the bottom. Adrian Bowyer and Anthony Garside got their wins with Meva’s coming from Ben Rothwell, Dave Kendall and Matt Rowe. St Blazey ‘A’ are starting to motor and recorded a 4-1 home win over Pelynt. Phil Ormand’s black ball win in the first frame over Mark Craddock was the visitors’ only bright spot as Stewart Dewings, Aiden Maxwell-Craddock, Mickey Meares’ blackball win over Len Flower and Nick Kendall all recorded victories. Mevagissey ‘C’ recorded the result of the night in the Rees League with a 4-1 win at second-placed Bethel ‘B’. Predator Tregale was buying the sausage rolls at work last Wednesday after his win over Rich Bolt, inflicting his first defeat of the season. Jim Tamblyn levelled things up beating Charlie Prynn but Ben Prynn plus Joe and Matt Chesterfield brought a great win for the away team. Tregonissey ‘B’ came from 2-0 down to record their sixth successive win with victory at third-placed Bethel ‘C’. Howard Brett and Ben Stunnell, who beat Richard Opie put the home side in the driving seat but Phil and Justin Hooley along with Ryan Thomas’ last frame win over Leigh Rosevear sees Treggy open up a four-point lead at the top. Lerryn started well at Mevagissey ‘D’ with Terry Middleton’s good form continuing with victory over Ian Latham but wins for Neil Parker, Richard Lakeman, Mark Ashton and George Lory moves the home side on the fringe of the promotion slots. Andy Spearman finally broke his duck for the season beating Richard Holmes to get Bethel ‘D’ underway at Gorran Haven, Rob Bunney levelled things beating Ross McMenemy, Dave Morsheard (Andy Reddall), Paul Grimmett (Lee Searle) left things level at 2-2 which left Jason Pascoe’s win over Matt Fox the decider.

FULL RESULTS

Victory League: St Blazey ‘A’ 4 (S Dewings, A Craddock-Maxwell, M Meares, N Kendall) Pelynt 1 (P Ormand), Mevagissey ‘A’ 5 (M Mills, J Popperwell, L Varcoe, P Staley, P Chambers) Bugle ‘B’ 0, St Stephen ‘A’ 2 (A Bowyer, A Garside) Mevagissey ‘B’ 3 (B Rothwell, D Kendall, M Rowe), Bugle ‘A’ 4 (G Spencer (36), I Ball, J Moore, P Sturtridge) St Neot 1 (D Lock (43)). Rees Memorial League: Bethel ‘C’ 2 (H Brett, B Stunnell) Tregonissey ‘B’ 3 (P Hooley, J Hooley, R Thomas), Gorran 2 (R Bunney, P Grimmett) Bethel ‘D’ 3 (A Spearman, D Morshead, J Pascoe), Mevagissey ‘D’ 4 (N Parker, R Lakeman, M Ashton, G Lory) Lerryn 1 (T Middleton), Bethel ‘B’ 1 (J Tamblyn) Mevagissey ‘C’ 4 (D Tregale, B Prynn, M Chesterfield, J Chesterfield). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: G Spencer 36, D Lock 43 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('On form Andy delights packed house', 'on-form-andy-delights-packed-house', 'Professional Snooker', '[]'::jsonb, 'A packed house saw Andy produce some wonderful snooker with the highlight of the evening a break of 122 only missing a difficult pink when a 135 clearance was possible.', null, '"The second half saw some wonderful snooker from Andy with Matt Mills making the highest frame score (46) which included a well constructed 36 break for this effort Matt was presented with a trophy at the end of the evening."', 'A packed house saw Andy produce some wonderful snooker with the highlight of the evening a break of 122 only missing a difficult pink when a 135 clearance was possible.

more There were many breaks of 30+ to 90+ throughout the exhibition and an interval was called at approx 8:30pm which saw all the spectators and officials retire to the function room below where they all enjoyed a most well appointed buffet which they all enjoyed immensely. Also during the interval there was a grand raffle prize draw which was well received by all. Then it was back to the number 1 match snooker room for the second half of the exhibition, before play was re-started Andy conducted a quick view Q&A. The second half saw some wonderful snooker from Andy with Matt Mills making the highest frame score (46) which included a well constructed 36 break for this effort Matt was presented with a trophy at the end of the evening. Andy Hicks Pro Snooker Exhibition - Friday 15th March 2013, at the Mevagissey Social Club - 7pm till late. Referees for the evening: John Daniels (Lostwithiel Social Club) and Gerald Goode (Mevagissey Social Club), MC for the evening Leighton Varcoe (Mevagissey Social Club). Play started at 7pm with Andy playing against local players and then later on in the second half Andy played against 4 very young prospects from the Belgrave Snooker Club in Plymouth (coached and brought on by Derek Walker). Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('On top of the world', 'on-top-of-the-world', 'Professional Snooker', '[]'::jsonb, 'Judd Trump became the new world number one today - and he did it with his stylish touch.', null, '"Since his breakthrough to stardom winning the 2011 China Open, he’s won the UK Championship, reached the final at the Crucible, picked up points all over the place and put on a show at every opportunity".', 'Judd Trump became the new world number one today - and he did it with his stylish touch.

more Needing to reach the final of the International Championship to overtake Mark Selby at the top of the rankings, he was brutal in his 9-1 demolition of Peter Ebdon in the semi-final. It was everything we have come to expect from Judd in its delivery. Fast, furious and entertaining. This is a big milestone in Trump''s inevitable rise to becoming one the greats. He''s still a world title or a few away from becoming a legend, but the way he audaciously plays the game means he''s already well on the way. He''s already is great company. He is only the tenth player to occupy the number one spot in the rankings since they were designed in 1976. His name goes next to Ray Reardon, Cliff Thorburn, Steve Davis, Stephen Hendry, John Higgins, Mark Williams, Ronnie O''Sullivan, Neil Robertson and Mark Selby. This is a stellar list but his name is certainly not out of place. I''d expect him to be in or around top spot for man more years to come. There is much to admire about Trump.

STAR IN THE MAKING FOR MANY YEARS

Since his breakthrough to stardom winning the 2011 China Open, he''s won the UK Championship, reached the final at the Crucible, picked up points all over the place and put on a show at every opportunity. His outrageous shot-making ability, unwavering temperament, unshakable confidence and enviable good looks make him a ready-made star, but he appreciates he must work for his success. Unlike lots of young players, Trump appears to see the bigger picture. He has an admirable work hard, play hard attitude and is always keen to keep improving putting in long hours on the practice table. He''s clearly motivated by winning the most prestigious titles and entertaining the crowds on the biggest occasions, but this doesn''t disrupt his consistent dedication. I''m not saying he''s perfect. He''s had plenty of critics; more than he deserves. But this is part and parcel of being a such a phenomenal and a sure sign of his dramatic rise and continuous success. Encouragingly, Judd hasn''t let it put him off doing what he does best. The tag of being world number one could easily weigh heavy round the neck of a player so young, but I can''t see this being a problem for Trump. He''s taken everything he''s achieved so far in his stride, but always stays grounded. In today''s press conference he talked down his new ranking position insisting he still has a job to do in Chengdu and that his primary aim is to become world champion. Judd has been a star in the making for many years. He has good people around him and has had plenty of time to prepare for the limelight. These have clearly been factors in helping him to handle life at the top. He does so many things well and plays snooker in a way you can''t help but enjoy. He is a complete breath of fresh air. Article courtesy of the OneCue Images Courtesy of: Jon Enoch & Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('On your marks… get set… Snow', 'on-your-marks-get-set-snow', 'Professional Snooker', '[]'::jsonb, 'So after an eventful few days at the masters it''s back down to earth in Cornwall for the continued resumption of league snooker.', null, '"Strangely the snow and there was a lot of it in London this past weekend didn''t seem to deter the crowds coming out in force for both afternoon and evening sessions, the atmosphere is electric at times and being there on live TV in front of all those people didn''t faze me at all, after a while you just forget they are there and get on with the job in hand."', 'So after an eventful few days at the masters it''s back down to earth in Cornwall for the continued resumption of league snooker.

more But first lets have a quick re-cap of the 2013 Betfair Masters. A week which saw Mark Selby capture his third title, a week of comebacks and cracking close matches, and a week of snow, all held in the fabulous venue ''Alexandra Palace'' or Ally Pally as it''s better known. For me going as a representative of the league was a great honour, of course I have experienced this before back in the 90''s when I was with the press at the British Open in Plymouth and to be fair not much has changed behind the scenes. When I had managed to trudge my way through the snow and finally got there via 3 modes of London transport I got my press pass from Gary Wilkinson, yes some of you will remember that name from the 90''s as well, Gary was a very good player in his time, seems now though he is working for World Snooker in the media side. The press room is how I remember it from the 90''s loads of reporters and photographers sitting around chatting, with the odd player, referee and tv commentator popping in for a coffee and a chat. John Parrott, and Rob Walker spend a lot of time in the press room during the day chatting away freely to everyone, in-fact Rob was telling me he knows the St Blazey area well as he did a lot of football reporting in his early years whilst studying at Falmouth. So after settling in, I decided to do a recky of backstage to see what images I could capture whilst it was quiet, it''s amazing how many wires, computers, cameras and general BBC gear there is that you cannot see on the TV. Watching snooker on the TV is odd when you have been to a live setup, they are so very different and it''s understandable how the players can be put off so easily, there is a hive of noise and camera''s, people everywhere, coffing, spluttering, and commentary that can be heard from any part of the arena. One thing I noticed more than anything is how amazing the tables are, pristine and so very fast, when a player forces a ball on the TV it really does look like they have hit it quite hard, but that''s not the case it really is a touch game when your there in front of it. The pockets are very forgiving as well nothing like a club table, balls do just seem to drop in off the jaw. Anyway back to the article, as you will see from the images on the site and Facebook I took a fair few and tried to capture the essence of snooker from all angles. My first task at 1pm was to get settled in the arena just behind the main TV cameras with my camera gear and giant lens (which was kindly leant to me by David Levene) this lens allowed me to get close to the action without having to move very much, a little bit of etiquette is involved nether the less in that you need to wear dark clothing and only take shots when the player has played his shot (although not always the case). Of course at one point the inevitable happened, yes you guessed it Jan Ver Haas told me off for moving in the wings and told me to sit down, this was on live TV as well so i''m sure somewhere that has been captured. The first semi final was between Shaun Murphy and defending champion Neil Robertson, everyone expected a tight encounter here but as it turned out this was the case and although Shaun let by 40 points in 4 frames he ran out the loser 2-6 to Robertson, Robertson including 2 century breaks in this match, as it was over fairly quickly I didn''t managed to quite get all the shots I wanted, but never mind the evening match between Dott & Selby went on and on and on so I had plenty of time to catch up. Strangely the snow and there was a lot of it in London this past weekend didn''t seem to deter the crowds coming out in force for both afternoon and evening sessions, the atmosphere is electric at times and being there on live TV in front of all those people didn''t faze me at all, after a while you just forget they are there and get on with the job in hand. So into the break for the afternoon involved a lot of work for me processing images and mingling with journos and photographers not to mention getting a few exclusive interviews with the likes go John Parrott and John Virgo. The evening session soon crept up on us and before I knew it I was out in the arena again taking more pictures for the 2nd semi-final featuring Graham Dott & Mark Selby, this match was a marathon which I didn''t get to see the end of in the arena as i needed to leave before midnight to catch the last train back to the centre of London, Graham missed a black for 5-1 at it was at that point where we all knew the Selby comeback was on. Not for the first time in the week Mark managed to slow things down and tactically drag himself back in to the back, which in the end ended 6-5 to Mark Selby at 12:45am. I didn''t have a press pass for the final on Sunday but I did have tickets so watched the final from the stands with everyone else, it''s odd though as this was far more mentally tiring than being behind the scenes, all those people crammed in like battery hens, not being able to wander round without asking whole rows of people to move and not being able to take many pictures. Still I had a great time whilst I was there and I must say everyone was very friendly and accommodating, I will look forward to the next tournament which hopefully will be a Premier League match in Penzance, where I can bring you all more exclusive interviews and images, lastly before I sign off a big thank you to World Snooker for letting me have the press pass and looking after me so well. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('O’Sullivan Matches Major Records', 'osullivan-matches-major-records', 'Professional Snooker', '[]'::jsonb, 'Ronnie O’Sullivan beat Shaun Murphy 10-5 in the final of the Betway UK Championship to equal two long-standing records held by Steve Davis and Stephen Hendry.', null, '“It’s just nice to win another title, though I don’t even really feel excited by it, I don’t get too emotionally involved now. Playing snooker keeps me out of trouble, if I wasn’t playing I’d probably be going off the rails. As long as I play snooker it’ll keep me reeled in.', 'Ronnie O’Sullivan beat Shaun Murphy 10-5 in the final of the Betway UK Championship to equal two long-standing records held by Steve Davis and Stephen Hendry.

more O’Sullivan rose to the occasion at the business end of a high quality final in York by pulling away from 5-5 to reel off the last five frames in just 60 minutes to take the £170,000 top prize. During the contest he made three centuries and seven more breaks over 50. It’s his sixth UK Championship title, bringing him level with Davis, and 18th Triple Crown victory, a record held by Hendry since 1999. O’Sullivan adds his half dozen UK titles to seven at the Masters and five at the World Championship. Ronnie O’Sullivan’s Triple Crown Wins World Championship (5) 2001, 2004, 2008, 2012, 2013 UK Championship (6) 1993, 1997, 2001, 2007, 2014, 2017 Masters (7) 1995, 2005, 2007, 2009, 2014, 2016, 2017 Playing arguably the most consistently impressive snooker of his career at the age of 42, O’Sullivan has won three ranking titles in an golden seven-week spell in which he has banked nearly £450,000 in prize money. He landed the English Open in October and the Shanghai Masters in November and his career tally of ranking crowns now stands at 31, just five behind another of Hendry’s records. He also reached the final of the Champion of Champions last month, losing to Murphy. Chigwell’s O’Sullivan, who won his first UK title 24 years ago, is up from fourth to second in the world rankings. Only Mark Selby – with whom he has shared the last six Triple Crown titles – is ahead of him. One of the fittest players on the tour in body and – with the help of psychiatrist Steve Peters who was present tonight – in mind, he clearly has the sharpness, form and motivation to win silverware again and again. O’Sullivan now heads straight to Glasgow for the Scottish Open which starts on Monday. Murphy missed the chance to double his tally of UK titles having lifted the trophy in 2008, and also lost a ranking final for the third time this season, though he did land the Champion of Champions crown. The 35-year-old, winner of seven ranking titles, earns £75,000 and climbs to fifth in the world. Tied at 4-4 after the first session, O’Sullivan won the opening frame tonight with a break of 75. He led 32-4 in the next when he missed a tricky red to a top corner, and Murphy capitalised clinically with an 80 clearance. O’Sullivan regained the advantage with a 104 then made a 76 in the next to lead 7-5 at the interval. Murphy had two early chances in frame 13 but could only make 18 and O’Sullivan punished him with 103, his tenth century of the tournament, to go three clear. Again in the 14th Murphy was in first but he over-cut a tough black with the rest on 49. And again O’Sullivan punished him with an 86 clearance as he went 9-5 ahead. And runs of 59 and 49 in the next frame saw secure him the title. “I just went out there and tried to be professional and ignore how I was feeling,” said O’Sullivan, whose only defeat in a UK Championship final came last year against Selby. “I missed a lot of balls all tournament and you don’t expect to win titles unless you’re on 70 or 80% of your game. So I’m a little bit surprised to come out on top this week but I’ll take it. “It’s just nice to win another title, though I don’t even really feel excited by it, I don’t get too emotionally involved now. Playing snooker keeps me out of trouble, if I wasn’t playing I’d probably be going off the rails. As long as I play snooker it’ll keep me reeled in. “I look forward to the Masters because it’s around the corner and it is a great event. Hopefully I can pick my game up and dominate a tournament rather than just scramble through.” Asked how he would spend his recent earnings, O’Sullivan added: “I’m not motivated by money. It’ll help my friends and my family and maybe I could put it into a foundation for people that really need it because giving is a much better feeling. I enjoy my happiness and money can’t get you that.” Murphy said: “I thought the better man won by far. When you play Ronnie O’Sullivan in any match your game has to be the best it could possibly be. He is the greatest player we’ve ever seen and unfortunately today for whatever reason my game wasn’t good enough. “I thought the difference today was his safety, it had me in real trouble most of the time. I’m not the world’s best tactical safety player and he exposed those weaknesses as true legends do. “This was my fourth final of the season so the positives of this season drastically outweigh the negatives. I’ll be a little bit sore on the train up to Glasgow tomorrow thinking about what could have been, but I can’t do anything about it and I’ll be trying my best next week. “For Ronnie to still be winning majors and to have equalled records while playing against opponents who are so much better than they ever were in snooker’s perceived heyday is a massive feather in his cap. As long as he keeps enjoying playing we’ve all got the pleasure of seeing him for many years to come.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Perry Wins Maiden Title', 'perry-wins-maiden-title', 'Professional Snooker', '[]'::jsonb, 'Joe Perry won the first world ranking title of his 24-year career by beating Mark Williams 4-3 in the final of the Players Championship in Bangkok.', null, null, 'Joe Perry won the first world ranking title of his 24-year career by beating Mark Williams 4-3 in the final of the Players Championship in Bangkok.

more World number 13 Perry came from 3-0 down to win a dramatic final in Thailand, to take the trophy plus the biggest cheque of his career: £100,000. Perry, from Chatteris in Cambridgeshire, turned professional in 1991 but has played the best snooker of his life in recent years. He made a breakthrough by winning an Asian Tour event last season, and repeated that feat in January this year with victory in the Xuzhou Open in China. He also reached the final of the Wuxi Classic last June and came agonisingly close to the title but lost 10-9 to Neil Robertson. His only other ranking final was at the 2001 European Open when he lost 9-2 to Stephen Hendry. Today, 40-year-old Perry has finally tasted glory in a full ranking event. Welshman Williams, who was chasing his 19th ranking title and first since 2011, looked to be cruising to the title when he won the first three frames with top breaks of 64, 57 and 103. But Perry got the better of a scrappy fourth frame then took the next two with runs of 50 and 56 for 3-3. In the decider, Perry potted a long red and made an excellent 54 before missing a red with the rest. Williams had a chance to counter, but could only make 7, and his opponent added 24 points to seal the result. "It has been a lifelong ambition for me," said Perry. "I''ve been playing snooker since I was 12, and all I''ve ever wanted to do is win a major tournament. When I lost 10-9 in the final in Wuxi I thought that might have been my chance. So I''m delighted to do it at last. "I''ve been really composed all week. I have been very calm at the table, haven''t got nervous and just felt very confident. I never expected anything other than to prepare well and try my best. "The turning point today was the fourth frame because I didn''t feel comfortable until then. It was a long frame and I managed to pinch it, and that helped me settle down. After that I was able to play my game. "I''m really good friends with Mark and to play one of my favourite players in the final - and to win - is just the icing on the cake. The fans here have been brilliant, we''ve had good crowds all week. And the sponsor D88 has been fantastic, all the players really appreciate their support." Earlier today in the semi-finals, Perry beat Stuart Bingham 4-1 with a top break of 86, while Williams saw off Judd Trump 4-2 with a top run of 85. Both players now head to Beijing for the Baic Motor China Open, which starts on Monday and is the last event before the Betfred World Championship. Article courtesy of the World Snooker Images Courtesy of: World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Play-offs needed to decide who finishes as runners-up', 'play-offs-needed-to-decide-who-finishes-as-runners-up', 'Match Reports', '[]'::jsonb, 'A very tense end of season sees play-offs in both the Victory and the Rees League to determine the runners-up spots.', null, 'Mark Sturtridge’s 43 break was the highlight of Bugle ‘B’s 3-2 home win over Pelynt. Jake and Keith Moore also won, with Phil Ormond and Len Flower replying.', 'A very tense end of season sees play-offs in both the Victory and the Rees League to determine the runners-up spots.

more In the Victory League Bugle ‘A’ went to St Neot confident of a victory but got dumped 4-1. Chris Perring, Darren Lock’s black ball victory over Andrew Best, Steve Court with a 38 break and Cyril Dickenson’s 59-5 victory over Ian Powell left them shell shocked. With Paul Stuthridge’s win over Anthony Maddams their only reward. With that result Mevagissey ‘A’ needed four points to clinch second but after Chris Kendall, Pete Chambers and Matty Mills put them three up, Nick Kendall and Stewart Dewings, who beat Paul Williams, got two back for St Blazey ‘A’. Treggy ‘A’ clinched the league title with a 3-2 win at Bethel ‘A’. Jason Simmons, Ryan Bilson and Chris Stephenson put them 3-0 up before Geoff Hawken and Leon Collard replied to secure a fifth-placed finish for the home side. Bethel ‘C’ secured a 5-0 victory over their ‘D’ team, who remain winless all season. Courtney Crockford, Ben Stunnell and Roger Smithson recorded easy victories with Howard Brett and Martin Powell both winning on the black. Mark Sturtridge’s 43 break was the highlight of Bugle ‘B’s 3-2 home win over Pelynt. Jake and Keith Moore also won, with Phil Ormond and Len Flower replying. Bethel ‘B’ and St Stephen ‘A’ played their play-off game last night at Tregonissey. Scott Mills and Ian Latham put Mevagissey ‘D’ 2-0 up against the Bethel boys only for Jim Tamblyn and Clive Stuthridge, who knocked in a 35, to level it, leaving George Lory’s black ball victory over Guy Buckle to win it for the Meva boys. St Stephen ‘A’ found themselves 2-1 down at Gorran Haven with Matt Fox and Lee McKinstry replying to Dan Allen’s victory but comfortable wins for John Bennett and Brian Green clinched the victory and a play-off spot. Bodmin Q-Bar ended the season in fourth place, only one point behind the play-offs courtesy of a 4-1 win at St Stephen ‘B’. Darren Biggen hammered Marcus Causton first off but the visitors replied through Barnicoat, Bampton, Ashton and Bolt respectively. Mevagissey ‘C’ finished the season with a whitewash of Tregonissey ‘B’. Matt and Joe Chesterfield, James and Ben Prynn and last one Predator Tregale were their winners.

FULL RESULTS

Victory League: St Neot 4 (Chris Perring, Darren Lock, Steve Courts (38), Cyril Dickenson) Bugle ‘A’ 1 (Paul Sturtridge), Mevagissey ‘A’ 3 (Chris Kendall, Pete Chambers, Matt Mills) St Blazey ‘A’ 2 (Nick Kendall, Stewart Dewings), Bethel ‘A’ 2 (Geoff Hawken, Leon Collard) Tregonissey ‘A’ 3 (Jason Simmons, Ryan Bilson, Chris Stephenson), Bugle ‘B’ 3 (Mark Sturtridge (43), Jake Moore, Keith Moore) Pelynt 2 (Phil Ormond, Len Flower), Bethel ‘D’ 0 Bethel ‘C’ 5 (Courntey Crockford, Ben Stunnell, Roger Smithson, Howard Brett, Martin Powell). Rees Memorial League: Gorran Haven 2 (Matt Fox, Lee McKinstry) St Stephen ‘A’ 3 (Dan Allen, John Bennett, Brian Green), Mevagissey ‘D’ 3 (Scott Mills, Ian Latham, George Lory) Bethel ‘B’ 2 (Jim Tamblyn, Clive Stuthridge (35)), St Stephen ‘B’ 1 (Darren Biggen) Bodmin Q-Bar 4 (Brian Barnicoat, Steve Bampton, Phil Ashton, Richard Bolt), Tregonissey ‘B’ 0 Mevagissey ‘C’ 5 (Matt Chesterfield, James Prynn, Ben Prynn, Joe Chesterfield, Dave Tregale). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: S Courts 38, M Sturtridge 43, C Stuthridge 35 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Plenty of festive cheer for Tregonissey', 'plenty-of-festive-cheer-for-tregonissey', 'Match Reports', '[]'::jsonb, 'Victory League leaders Tregonissey ‘A’ were very relieved to beat Bethel ‘A’ in a night of tight frames.', null, '"The St Blazey derby went the way of the ‘B’ side to keep their chance of silverware alive. Mike Hancock, Paul Baron and Andrew Gooch won for them with Mickey Meares and the in-form Nick Kendall replying."', 'Victory League leaders Tregonissey ‘A’ were very relieved to beat Bethel ‘A’ in a night of tight frames.

more Geoff Hawken and Leon Collard had put Bethel 2-1 up, before Steve Allen produced a 35 break to lead Barrie McIntosh, but he recovered to clear the colours to the pink to take it to a final frame shootout, which saw Ryan Bilson narrowly defeat Gary Stephens. Mevagissey ‘A’ closed the gap on the leaders by a point after defeating their ‘B’ side 4-1. Dave Kendall’s victory the only bright spot for the basement boys as Paul Williams, Chris Kendall, Matt Mills and Phil Staley were victorious. Bugle ‘A’s season continues to crumble after a 4-1 home defeat to Lostwithiel ‘A’. Andrew Best saw off Steve Courts, but wins for Anthony Maddams, Chris Perring, Cyril Dickenson and Darren Lock sent the visitors home happy. The St Blazey derby went the way of the ‘B’ side to keep their chance of silverware alive. Mike Hancock, Paul Baron and Andrew Gooch won for them with Mickey Meares and the in-form Nick Kendall replying. Lostwithiel ‘B’ power on after a good 4-1 home win over Bugle ‘C’ for who Kevin Spencer won again. Four teams now lie in second place on 37 points. Mevagissey ‘D’ defeated their own ‘C’ team 3-2 as James Tomlinson, Rob Blamey and Richard Lakeman ran out winners to put a dent in their opponents’ promotion charge. Dave ‘Predator’ Tregale on target for the ‘C’ team along with Charlie Prynn. Lerryn fought hard for victory at Bethel ‘D’ but came up just short. Gordon Brimicombe and Charles McMiram won with John Hancock agonisingly close to beating Ben Stunnell. St Stephen ‘A’ beat their own ‘B’ side 5-0 to close to within two points of second place. There were two very close frames on the night but both went their way. Tregonissey ‘B’ joined Bethel ‘B’ on 37 points after a 3-2 home victory.

FULL RESULTS

Victory League: St Blazey ‘B’ 3 (M Hancock, P Baron, A Gooch) St Blazey ‘A’ 2 (M Meares, N Kendall), Mevagissey ‘B’ 1 (D Kendall) Mevagissey ‘A’ 4 (P Williams, C Kendall, M Mills, P Staley), Bethel ‘A’ 2 (G Hawken, L Collard) Tregonissey ‘A’ 3 (C Stephenson, B McIntosh, R Bilson), Bugle ‘A’ 1 (A Best) Lostwithiel ‘A’ 4 (A Maddams, C Perring, C Dickenson, D Lock). Rees Memorial League: St Stephen ‘B’ 0 St Stephen ‘A’ 5 (J Bennett, A Harrison, C Clark, A Garside, D Allen), Lostwithiel ‘B’ 4 (L Flower, A Parnell, R Broad, J Daniell (41)) Bugle ‘C’ 1 (K Spencer), Mevagissey ‘C’ 2 (D Tregale, C Prynn) Mevagissey ‘D’ 3 (J Tomlinson, R Blamey, R Lakeman), Bethel ‘D’ 3 (B Stunnell, R Tonkin, A Spearman) Lerryn 2 (G Brimicombe, C McMiram), Tregonissey ‘B’ 3 Bethel ‘B’ 2. Top breaks of the week: Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Premier prize for Bingham', 'premier-prize-for-bingham', 'Professional Snooker', '[]'::jsonb, 'Snooker-mad Stuart Bingham could hardly be happier after becoming the 2012 Premier League champion.', null, '"It''s quite fitting that Bingham''s win came in Grimsby, a Lincolnshire town that loves its snooker as much as him.".', 'Snooker-mad Stuart Bingham could hardly be happier after becoming the 2012 Premier League champion.

more His 7-2 victory against Judd Trump in the final in Grimsby was thoroughly deserved and rich reward for the man who lives and breathes the game. The Premier League is an event carrying great prestige. This is why Bingham has always had a burning desire to compete in it. His maiden ranking event win at the Australian Open earned him his place and now he''s Premier League champion in his debut campaign. His performances in the final four matches during the run-in to lifting silverware means no-one can argue against his success. He earned a place in the play-offs courtesy of back-to-back 6-0 wins against Mark Selby and Neil Robertson in Guildford, forced his way to the final edging out John Higgins 5-4 and then finally landed top prize with a demolition job on Trump. Bingham leaped for joy and so he should as he proves his name belongs alongside the very best in the sport right now. It''s quite fitting that Bingham''s win came in Grimsby, a Lincolnshire town that loves its snooker as much as him. Even when Stuart wasn''t dining at snooker''s top table, his attitude to playing the game was as exemplary as it is today. There was a discussion on Twitter last night about which of his big titles ranks most highly. The Premier League is a fine competition and has been for many years, but I''ll always back a ranking event against it. You might disagree, but the debate is void anyway. Bingham has experienced both great highs and doesn''t have to choose between them. He has been dreaming of winning big titles all his career and now he''s living his best years. He has always loved playing snooker, but probably never more than right now. Article courtesy of the OneCue Images Courtesy of: Snooker Picture Collection', '2014-01-01', false, 'Richard Pearson'),
  ('Read leads the way as Blazey keep up one-point lead at the top', 'read-leads-the-way-as-blazey-keep-up-one-point-lead-at-the-top', 'Match Reports', '[]'::jsonb, 'Leaders of the St Blazey and District Snooker League Victory League St Blazey ‘B’ kept their one-point lead at the top of the table after beating St Neot 3-2.', null, 'Q-Bar Bodmin have moved to the top of the league as a result of their win at Lerryn. Graham Hoskin beat Malcolm Meneer for the home side’s point but wins for Matt Woodward, Phil Ashton, debutant Mike Bolt and Jon Rosevear saw the Bodmin boys rise to the summit.', 'Leaders of the St Blazey and District Snooker League Victory League St Blazey ‘B’ kept their one-point lead at the top of the table after beating St Neot 3-2.

more Wins for Graham Taylor, Jamie Read, who had a 62 break and Paul Baron got their points with Darren Lock and Steve Courts, who took Andrew Gooch’s unbeaten record, got St Neot’s frames. Bugle ‘A’ remain second after a 3-2 home win over Bethel ‘D’. Ryan Tonkin and Steve Benallack played well to overcome Paul Sturtridge and Ian Ball for the away team’s point but Andrew Best’s 37, Ian Powell and Gary Spencer got Bugle home. Mevagissey ‘A’ kept up the pressure on the top two beating Pelynt 4-1. Andy Parnell beat Phil Staley for the visitors’ point but Pete Chambers, Matt Mills (36), Chris Kendall and Paul Williams got Meva’s point and they are handily placed place in third with a game in hand over the top two. Bethel ‘A’s 4-1 home win over Bugle ‘B’ moved them up to fourth. A very close, but long, first frame saw Mark Sturtridge take the black to beat Gary Stephens but Bob Stephens, Leon Collard, Matt Green and the impressive Andy Peers saw the Bethel boys home. Bethel ‘C’ picked up their first point of the season as Martin Powell beat Ryan Bilson but Martin Knight, Jason Cocks, Chris Stephenson and Barrie McIntosh got the points to move Tregonissey ‘A’ up to sixth. Only three games were played in the Rees League as Bethel ‘B’ and Mevagissey ‘C’ re-arranged for last night but all three games ended in 4-1 scores. Q-Bar Bodmin have moved to the top of the league as a result of their win at Lerryn. Graham Hoskin beat Malcolm Meneer for the home side’s point but wins for Matt Woodward, Phil Ashton, debutant Mike Bolt and Jon Rosevear saw the Bodmin boys rise to the summit. Mevagissey ‘D’ are looking for more consistent form to help them climb the table and they had a hard-fought win over St Stephen ‘B’. Rob Garside played very well to see off Adam Pollard but victories for Neil Parnell, Rich Lakeman, George Lory and captain Rob Blamey saw Meva home. St Stephen ‘A’ have up to fifth and have games in hand on all above as they kept their unbeaten record going seeing off Tregonissey ‘B’ 4-1. Phil Hooley made a good 33 break when defeating John Bennett, but that was the only bright spot as Clark, Harrison, Allen and Garside put the seal on a good win. All competition draws have been made

FULL RESULTS

Victory League: Bugle ‘A’ 3 (Andrew Best (37), Gary Spencer, Ian Powell) Bethel ‘D’ 2 (Steve Benallack, Ryan Tonkin), Tregonissey ‘A’ 4 (Martin Knight, Jason Cocks, Barrie McIntosh, Chris Stephenson) Bethel ‘C’ 1 (Martin Powell), Mevagissey ‘A’ 4 (Pete Chambers, Matt Mills (36), Chris Kendall, Paul Williams) Pelynt 1 (Andy Parnell), Bethel ‘A’ 4 (A Peers, Matt Green, Leon Collard, Bob Stephens) Bugle ‘B’ 1 (Mark Sturtridge), St Neot 2 (Darren Lock, Steve Courts) St Blazey ‘B’ 3 (Graham Taylor, Jamie Read (62), Paul Baron). Rees Memorial League: St Stephen ‘A’ 4 (A Garside, A Harrison, C Clark, D Allen) Tregonissey ‘B’ 1 (Phil Hooley (36), Lerryn 1 (Graham Hoskin) Bodmin Q-Bar 4 (Matt Woodward, Phil Ashton, Mike Bolt, Jon Rosevear), Mevagissey ‘D’ 4 (George Lory, Neil Parker, Rob Blamey, Rich Lakeman) St Stephen ‘B’ 1 (Rob Garside). Top breaks of the week: A Best 37, M Mills 36, J Read 62 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Reardon at 80 and Paul Hunter remembered', 'reardon-at-80-and-paul-hunter-remembered', 'Professional Snooker', '[]'::jsonb, 'For all the bad press that social networks get these days and perhaps rightly so at times their are instances where they prove their worth by allowing people the chance to mark certain events.', null, '"My first memory of seeing Paul play would have been an early round UK Championship against Hendry at the top of his game." -John Doe', 'For all the bad press that social networks get these days and perhaps rightly so at times their are instances where they prove their worth by allowing people the chance to mark certain events.

LIKE ALL GREAT CHAMPIONS THEY KNEW HOW TO WIN

That was the case this week as Snooker fans paid tribute to two men whose contribution to the game will never be forgotten, The first of these is Ray Reardon who on Monday celebrated his 80th birthday. I am of course too young to remember Ray in his prime so my memories are of him towards the end of his career but his record speaks for itself. You don''t win six World Championships beating the players he did without been an excellent player. Like all great champions he knew how to win and didn''t wilt when the pressure was on.He was the best player in the world and carried himself as such.He was also it seems not adverse to using a little bit of psychology.In Steve Davis''s autobiography from 1981 he tells the story of a match he played against him as a teenager in a round robin pro/am.By the time these two had met Davis knew he only needed to win one frame of the four in the match to advance but having lost the first two Reardon had a heated argument with the ref about the position of the reds for the break off.This resulted in the balls been re racked a total of six times before Reardon eventually broke.By this stage the young Davis''s concentration had completely gone and he exited the tournament losing the match 4-0.but with a valuable lesson learnt.

PAUL HUNTER''S PLAN B

Of course Davis would go onto dominate the game in the 80''s and I think perhaps unfairly the achievements of Reardon became quickly overlooked by the new generation of snooker fan much in the way Davis''s achievements are by the current generation. Regardless of this I think whenever snooker minds meet to discuss the games greatest players Ray Reardon deserves his place near the top on every list. Unfortunately the other player remembered this week would not get the chance to fulfill his undoubted destiny in the game. I refer of course to Paul Hunter. Tuesday. marked the sixth anniversary of his passing and it is still a day no snooker fan will forget, My first memory of seeing Paul play would have been an early round UK Championship against Hendry at the top of his game. I can''t remember the year but I do remember Paul lead after the first session before Hendry asserted in the night session.The result didn''t matter though,it was the style of this kid still in his teens that caught the eye.He seemed to have that rare ability to flow around the tables that only the very best possess. He will rightly be remembered for his three final frame victories in the Masters where he first became the darling of the red tops with his infamous "Plan B" victory over Fergal O Brien as well as his three ranking event victories but the memory of him that will always stick with me came in the 2003 World Championship.In his semi final with Ken Doherty he lead 15-9 going into the last session but in one of the most extraordinary sessions ever seen at the Crucible Doherty fought back to win 17-16.Anyone would have forgiven Paul for wanting the ground to open up and swallow him and probably inside he did as well but outwardly he gave Ken a smile and took the defeat with grace and dignity. This told me all I needed to know about the character of the man.Of course its impossible to predict how his career would have panned out I find it hard to believe he wouldn''t have at least challenged for the games top honours. Lets take a moment this week to reflect on what these two great men have done for the sport we love. Article courtesy of The Green Baize Snooker Blog Images Courtesy of: Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('Robertson Cracks China', 'robertson-cracks-china', 'Professional Snooker', '[]'::jsonb, 'Australia''s Robertson won six consecutive frames to lead 6-1 after the first session, and survived a flurry from Selby to nurse home his lead and win his seventh ranking title.', null, '"Having won a title, it''s my best season so far, going into the World Championship," said Robertson. "I''d lost in a few finals recently. Today was a titantic struggle, a real battle of determination. The first session was tough, Mark''s a very good safety player and I had to work for everything"', 'Australia''s Robertson won six consecutive frames to lead 6-1 after the first session, and survived a flurry from Selby to nurse home his lead and win his seventh ranking title.

more It''s the 31-year-old''s first ranking title since the World Open in September 2010 - though he has won the Masters and PTC events since - and brings to an end a run of defeats in finals for Robertson. He has been one of the most consistent players on the circuit this season but was denied at the last hurdle at the International Championship, the Masters and the PTC Grand Finals. Robertson, who is based in Cambridge, is the tenth different winner in ten ranking events so far this season, and will now go into the Betfair World Championship full of confidence as he aims for his second Crucible crown. The left-hander earned a cheque for £85,000 and is up to number two in the world rankings, behind Selby, with Judd Trump pushed down to third. Leicester''s Selby lost for the sixth time in nine ranking finals and missed out on his fifth title of the season having won the UK Championship, the Masters and two PTC events. Earlier in the tournament, he also missed out on a £23,500 bonus for a 147 maximum break when he failed to pot the final black. Nevertheless it was an impressive week for the 29-year-old and he will also go to the Crucible in the knowledge that his game is in good shape. Selby took the opening frame with breaks of 42 and 58 before Robertson made 50 and 91 to go 2-1 up then edged a 40-minute fourth frame on the last black. He cleared from yellow to black to win the fifth and got the better of two more scrappy frames to make it 6-1 when the first session was pulled off. Selby looked a different player from the restart and rattled in breaks of 81, 125 and 66 to close to 6-4. But Robertson rose to the challenge, making a 110 to stop his opponent''s momentum then nicking a fragmented 12th frame for 8-4 before a smooth 90 brought him to the brink of victory. Still Selby battled and runs of 116 and 63 helped him close to 9-6. But an early 45 put Robertson in control of frame 16 and he finally sealed it on the colours. "Having won a title, it''s my best season so far, going into the World Championship," said Robertson. "I''d lost in a few finals recently. Today was a titantic struggle, a real battle of determination. The first session was tough, Mark''s a very good safety player and I had to work for everything. "Tonight he played well and up until 9-6 it was very good snooker. I was relieved to win the last frame because he kept getting snookers and I started to fear the worst, until I potted a good long green. "I read what Shaun Murphy said about Mark after the semi-finals yesterday and he explained the way Mark plays perfectly. If someone doesn''t get in early in the frame, then neither player will have a good chance for the rest of the frame, all you can do is make 10, 20 or 30. I was really pleased with my safety today, I matched Mark as well as I could do." Selby said: "I came into this tournament on the back of some bad results so I didn''t know what to expect. In patches during the week I played ok. Today I was poor in the first session and Neil capitalised on my mistakes. I''m really proud of the way I fought back in the second session. I put up a good fight but it just wasn''t to be in the end. "For the last two days I haven''t been feeling great and haven''t eaten much. I''ve only managed to eat bananas and drink water. But I''m not going to use that as an excuse because Neil played a lot better than me today and deserved to win. "I can take a lot of positives from the week and go to the World Championship full of confidence. I always enjoy coming to China, I have great support here and I look forward to coming back again." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Robertson Rules In Wuxi Again', 'robertson-rules-in-wuxi-again', 'Professional Snooker', '[]'::jsonb, 'Neil Robertson won a dramatic final 10-9 against Joe Perry to win the Wuxi Classic in China for the second consecutive year.', null, '"Joe is one of my best friends on tour and if it wasn''t for him I wouldn''t be here today," said Robertson. "He has taught me so much about the game and been such a great influence on my career over the past ten years. "', 'Neil Robertson won a dramatic final 10-9 against Joe Perry to win the Wuxi Classic in China for the second consecutive year.

more From 9-8 down, Robertson rose to the occasion with breaks of 87 and 78 to win the last two frames of an exciting contest. His practice partner Perry had been chasing the first ranking title of his career but was denied despite winning three frames in a row from 8-6 down. Robertson showed his ruthless streak on the table at the key moment, but the 32-year-old was in tears afterwards having denied his close friend what would have been his greatest triumph. Melbourne-born Robertson took the £85,000 top prize and the first ranking title of the season, perfect preparation for his home tournament, the Australian Goldfields Open, which starts tomorrow. It''s the tenth ranking title of his career, bringing him level with Jimmy White on the all-time list and behind only Stephen Hendry (36), Steve Davis (28), Ronnie O''Sullivan (26), John Higgins (25), Mark Williams (18) and Ding Junhui (11). Cambridgeshire''s Perry won the first three frames with a top break of 56. Robertson pulled two back before runs of 74 and 61 put Perry 4-2 up. Robertson''s 72 gave him frame seven, and after he lost the eighth, a crucial 31 clearance left the former World Champion just 5-4 behind at the end of the first session. In the concluding session, Robertson won four of the first five frames despite a top break of just 44. Perry, whose only previous ranking final was the 2001 European Open when he lost 9-2 to Stephen Hendry, hit back with three in a row, taking frame 16 on the final black then making a 93 in the 17th to lead 9-8. But Robertson kept his composure and finished in style with two superb breaks. "Joe is one of my best friends on tour and if it wasn''t for him I wouldn''t be here today," said Robertson. "He has taught me so much about the game and been such a great influence on my career over the past ten years. "The first session today was really tense. At 5-4 down I felt as if I was 6-3 up. The last frame of the first session was huge because Joe should have won it to go 6-3. I just gave it everything I had in the last session and the match got better as it went on. I''m delighted to defend my title here and to start the season in this fashion. It will be a very proud moment for me to go to Australia having won this trophy and it will give next week''s tournament a good boost. "At the end I was really emotional. Maybe people thought it was because I''d won, but in fact it was for Joe as he was there at the start of my career. He should be winning tournaments and hopefully this experience will help him push on and win a big one and get into the world''s top ten where he belongs. Everyone saw that with the way he played against Ronnie O''Sullivan at the World Championship. If he was playing anyone else today I would have been following every shot. Even my Aussie friend Vinnie Calabrese texted me before the match saying he wanted Joe to win!" Perry said: "I had a chance early in the deciding frame but missed a difficult blue. I made my mind up that if I got a chance I was going to go for it. Neil showed his class. I made a good break to go 9-8 up but then he produced two fantastic breaks under pressure. He showed why he''s probably the best player in the world and one of the hardest to beat. In a few days time I''ll be pleased with what I''ve done this week but at the moment I''m absolutely gutted. "Neither of us played that well today, the best stuff was at the end of the match. I fought hard all day long and just came up short. I can''t think about the positives at the moment, I''m too distraught." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Robertson Takes Gdynia Glory', 'robertson-takes-gdynia-glory', 'Professional Snooker', '[]'::jsonb, 'Neil Robertson won a European Tour event in Poland for the third time by beating Mark Williams 4-0 in the final of the Gdynia Open.', null, '"It was a fine sporting day for Chelsea-fan Robertson as he saw his team beat Tottenham 2-0 in the League Cup final, helped by a goal from friend John Terry. "I had a bit of time before my semi-final so I watched the second half in the hotel," said Robertson. "It gave me a really good boost before my next match. It''s a great double for me today.""', 'Neil Robertson won a European Tour event in Poland for the third time by beating Mark Williams 4-0 in the final of the Gdynia Open.

more Robertson won his first title since the Wuxi Classic at the start of the season as he claimed the 25,000 Euro top prize on Poland''s Baltic coast. It''s his second victory in the city of Gdynia having triumphed in 2012, and he also won a tournament in Warsaw in 2011. The Australian won seven matches at the season''s sixth and last Kreativ Dental European Tour event, culminating in an impressive whitewash over Williams. Breaks of 65 and 46 helped Robertson win the first two frames, and he made a superb 63 clearance to snatch the third after Williams had opened with a run of 67. And Robertson completed the result in fine fashion with a break of 109. The top 24 on the Kreativ Dental European Tour will now be eligible to enter the Players Championship Grand Finals in Thailand later this month, alongside the top eight from the Asian Tour Order of Merit. "I played well over the two days and scored heavily," said Robertson. "I''m really pleased because I hadn''t done well in the European Tour events so far this season, and coming here I wasn''t sure of my place in the Grand Finals. I haven''t entered the Shoot-Out or the Indian Open so making sure of a place in Thailand now gives me a good run up to the World Championship. Since winning in Wuxi I had gone too long without taking a title so I''m glad to end that run. I can really enjoy the rest of the season now and focus on winning again. "We''ve played four tournaments in Poland and I''ve won three of them so that shows how much I enjoy playing here. I get great support from the fans, and the events here feel like the big ranking events because the crowds are so good. " It was a fine sporting day for Chelsea-fan Robertson as he saw his team beat Tottenham 2-0 in the League Cup final, helped by a goal from friend John Terry. "I had a bit of time before my semi-final so I watched the second half in the hotel," said Robertson. "It gave me a really good boost before my next match. It''s a great double for me today." Welshman Williams continued his return to form with his run to the final and the two-time World Champion has further boosted his hopes of being inside the top 16 in April and avoiding having to qualify for the Crucible. Article courtesy of the World Snooker Images Courtesy of: World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Robertson Takes UK Glory', 'robertson-takes-uk-glory', 'Professional Snooker', '[]'::jsonb, 'Neil Robertson became the first overseas player to win snooker''s ''triple crown'' by beating Mark Selby 10-7 in the final of the williamhill.com UK Championship.', null, '"It''s the most emotional I''ve ever been after winning a title and the first time I''ve had tears in his eyes at the finish," said Robertson. "To win the triple crown means that I join the really big boys. And it keeps going the incredible run of wins for overseas players."', 'Neil Robertson became the first overseas player to win snooker''s ''triple crown'' by beating Mark Selby 10-7 in the final of the williamhill.com UK Championship.

more Australia''s Robertson completed a remarkable turnaround in the final at the York Barbican by coming from 5-1 down to win nine of the last 11 frames. A devastating burst of break-building in the middle of the match, with three centuries in four frames, helped the 31-year-old to the £150,000 top prize. He has now made 58 tons this season and looks set to smash Judd Trump''s record of 61. Robertson becomes only the eighth player in snooker history to have won the World and UK Championship and Masters titles - joining Steve Davis, Stephen Hendry, John Higgins, Ronnie O''Sullivan, Mark Williams, Terry Griffiths and Alex Higgins. It''s Robertson''s ninth world ranking title, bringing him level on the all-time list with Ding Junhui, John Parrott and Peter Ebdon. Only Hendry, Davis, O''Sullivan, John Higgins, Williams and Jimmy white have won more. The left-hander also kept going a remarkable sequence of six consecutive ranking event victories for non-British players. He has won two this season - having taken the Wuxi Classic in June - while Ding Junhui has three to his name and Marco Fu the other. A tournament which started with 128 players finished with the top two in the world rankings battling for the title. Robertson would have surrendered his number one status to Selby if he had lost tonight, but instead he goes into 2014 at the top of the tree. Selby may be concerned by the number of mistakes he made after surging ahead in the early stages. However, more than anything, this event will be remembered for his magical 147 during yesterday''s semi-final, the 100th official maximum break in snooker history. That was worth a handy £59,000 bonus to go with the Leicester man''s £70,000 runner-up prize. Selby led 5-3 after the first session and took the first frame tonight to extend his advantage. Robertson then produced a golden spell of cueing and scored 410 points without reply, firing in breaks of 56, 122 and 132. Having levelled at 6-6, Robertson built a 55-0 lead in frame 13 then finished it off after Selby missed a red to a centre pocket on 22. That gave him the lead for the first time and he capitalised on further errors from Selby in the next to make it 8-6. Selby opened frame 15 with a break of 42 before missing a red to a top corner. But Robertson''s attempted long red didn''t find its target and Selby was able to add 74 to end a losing sequence of five frames in a row. The 16th frame was the most dramatic of the match, after Robertson missed an easy pink which would have put him 44 ahead with two reds left. Selby clawed his way back and had a chance to clear when Robertson missed a long pot on the brown. But after taking brown, blue and pink, Selby left a close-range black in the jaws of a top corner, leaving Robertson to tap it in right-handed for 9-7. Selby built a 36-0 lead in the next but Robertson then took control, and when his chance came he compiled a nerveless 57, which included a fine pot on the penultimate red along the top cushion, to secure the title. "It''s the most emotional I''ve ever been after winning a title and the first time I''ve had tears in his eyes at the finish," said Robertson. "To win the triple crown means that I join the really big boys. And it keeps going the incredible run of wins for overseas players. "Mark is the best safety player in the world and he put me out of my rhythm in the first session, there were times when I went 30 minutes without potting a ball. It was important for me to win the last two frames of the session and he would have been disappointed at 5-3. I knew I had the ability to win three or four frames in a row and when you score heavily it scares your opponent. I was really positive tonight, I was aggressive and I picked up the pace. It worked perfectly." Asked about Selby''s black ball miss in frame 16, Robertson added: "He had the black and the white cleaned and maybe that gave time for negative thoughts. With a black like that you have to aim for the far jaw, and he just hit it too thin and it caught the near jaw. I couldn''t believe it, everyone was in shock. I came to the table and decided not to get the long rest out, I just wanted to pot it right-handed then get out of the arena. I was proud of the way i finished the match off from 9-7." Robertson''s mother Alison flew to the UK earlier this week to support him, and he added: "Without the help of my mum and dad I wouldn''t be here. We can have a nice Christmas now!" Selby said: "I''m disappointed by my performance. I played ok this afternoon but the last two frames were key because if I had gone 6-2 up it might have been different. I still had enough chances tonight but I couldn''t take them. Anything half difficult, I didn''t feel comfortable with. Neil played well and deserved to win." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Robertson is champion of champions', 'robertson-is-champion-of-champions', 'Professional Snooker', '[]'::jsonb, 'Neil Robertson won his first title of the season by beating Mark Allen 10-5 in the final of the 188BET Champion of Champions.', null, 'Frame 14 was absolutely huge. Mark was playing the better safety and was creating the chances. I played a really good shot on the blue and happened to snooker him which was a bit fortunate and thankfully he couldn’t have left the balls any better. I was relieved to get to nine while he was still on five because had he got to seven or eight then anything could have happened.', 'Neil Robertson won his first title of the season by beating Mark Allen 10-5 in the final of the 188BET Champion of Champions.

more Australia’s Robertson collected the £100,000 top prize at the Ricoh Arena in Coventry after getting the better of Northern Ireland’s Allen in a battle of two left-handers. Former World, UK and Masters champion Robertson has had a quiet spell since winning the Wuxi Classic at the start of last season, his only other title coming at the Gdynia Open in February. But the 33-year-old looked close to his best in winning four matches this week to win the event for the first time. World number three Robertson took a very cautious opening frame with a run of 36 then Allen knocked in a brilliant 103 to level. Robertson then surged ahead as breaks of 53, 114 and 69 helped put him 4-1 up. The next four frames were shared, Robertson making a 71 in the ninth to lead 6-3 at the end of the first session. As the evening session got underway, Robertson picked up where he left off as runs of 60 and 40 helped extend his lead to 8-3. Allen, who grabbed the 16th and last place in this event by winning last week’s Bulgarian Open, needed a response and pounced on a mistake from his opponent to clear from the last red in frame 12. And when he fired in a break of 112 for 8-5, the fight back looked on. But a scrappy 52-minute 14th frame proved to be crucial, as a safety error from Allen allowed his opponent to clear from blue to black to move one away from the title. It came down to the colours again as the next frame was equally untidy. A miss on the black from world number 11 Allen allowed Robertson to clear from yellow to blue to seal the victory. “The support all week has been wonderful and this tournament is a real challenger as our fourth major of the season, it is absolutely amazing,” said Robertson. “It is a brilliant event and conditions were superb. “Commiserations to Mark, he has had a great week but he just wasn’t quite at his best today and didn’t have much luck either. “My long game was really good. I played well in the semi-final against Joe Perry yesterday and I knew if I could cut out the minor mistakes I would have a very good chance today. “In the first session I played really well, the second session was a bit tighter and overall I was really happy. “This is the first major title I have picked up in over 12 months now so it is nice to be able to break the duck there and now I can move on for the rest of the season. “Frame 14 was absolutely huge. Mark was playing the better safety and was creating the chances. I played a really good shot on the blue and happened to snooker him which was a bit fortunate and thankfully he couldn’t have left the balls any better. I was relieved to get to nine while he was still on five because had he got to seven or eight then anything could have happened.” Robertson was especially pleased to have picked up the title with five-year-old son Alexander in attendance. “I said not to come until I looked like winning because I brought him up for the final of the Masters and Shaun Murphy beat me 10-2,” he laughed. “It is a great moment and all his friends at school I am sure will be looking at it and maybe be a bit jealous.” A disappointed Allen reflected: “Neil played very well in spells and showed why he is a former world champion and former world number one. I am disappointed with the way I played myself, I had more than enough chances in different parts of the match but I just wasn’t up to it today. “I was nervous from the first frame and never settled down really and I got what I deserved. “You have to be at your very best if you are going to compete with the likes of Neil. I said last week I thought Neil was the best all-round player in the world and he showed that in spells today. People like Neil drive me on to get better and I will go straight back to the practice table and I will get better. “There are lots of positives to take from the last nine days, I wasn’t even in this event a week ago. The support I have had this week has been fantastic. This is what we play snooker for, to play in big arenas, packed out and have lots of support.” Neil Robertson 10-5 Mark Allen 63-35 (36), 20-107 (103), 97-6 (43, 53), 133-0 (114), 69-20 (69), 45-57 (Robertson 43), 69-44 (54, 44), 5-81 (60), 75-25 (71), 86-0 (60), 76-35 (40, 35), 55-65 (Robertson 54), 0-112 (112), 46-38, 56-24 (34) Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Robertson wins UK and makes 147', 'robertson-wins-uk-and-makes-147', 'Professional Snooker', '[]'::jsonb, 'Neil Robertson won his first title of the season by beating Mark Allen 10-5 in the final of the 188BET Champion of Champions.', null, '“Liang played his part in a really good final,” said Robertson, who received encouraging text messages from Chelsea captain John Terry before the final and again after the 147. “I don’t think you’ll ever see as high a standard from both players in the first session, usually there’s one player who does very well and the other struggles, but we both went blow for blow.', 'Neil Robertson won his first title of the season by beating Mark Allen 10-5 in the final of the 188BET Champion of Champions.

more Neil Robertson beat Liang Wenbo 10-5 to win the Betway UK Championship, and made the first ever 147 in a Triple Crown final. Australia’s Robertson won his second UK title to become the eighth player in snooker history to lift the trophy more than once. The first UK final between two non-British players was highlighted by a sensational 147 from Robertson in the sixth frame. Never before had a UK, World Championship or Masters final featured a maximum break. Robertson landed the first prize of £150,000 plus a £44,000 bonus for the 147, bringing his earnings for the past four weeks to £294,000 having also won the Champion of Champions in Coventry. Prior to this golden spell, the 33-year-old left-hander had endued a barren period of 17 months since winning his previous ranking title at the 2014 Wuxi Classic. But he is clearly now back to his best as his powerful high-scoring, shrewd tactical game and ability to pot key balls at crucial moments made him the outstanding player in York over the past fortnight. The world number three has now won 11 ranking titles, moving him level with Ding Junhui in sixth place on the all-time list. Liang missed out on his first ranking title, having lost his only previous final at the 2009 Shanghai Masters. But this was clearly the best week of his snooker career so far and his best run in a BBC-televised event. The charismatic Chinese cueman finished with a cheque for £70,000, his biggest pay-day, out-stripping his earnings for a World Cup triumph alongside Ding in 2011 and an Asian Tour title in 2013. Liang, age 29, also makes a huge jump to 15th in the rankings which earns him a place in the Masters. He’ll make his debut in the invitation event against John Higgins in London next month. Liang trailed 5-3 after the first session then made a strong start tonight with a break of 82 to halve the deficit. He was first among the balls in frame ten but broke down on 47 and Robertson made a brilliant 78 clearance which he later described as his best break of the tournament. He added a scrappy 11th to lead 7-4. A run of 78 from Liang reduced the gap at the interval, but in frame 13 he failed on a red to a top corner when leading 35-5, which proved a vital miss. Robertson made 56 before running out of position, but later took the frame after Liang had gone in-off the final yellow. Liang also had chances in the 14th but missed the pink to a baulk corner with one red left at 55-25, and again Robertson punished him with a fine clearance to go 9-5 up. In the 15th, Robertson made 42 before missing the green, but Liang’s counter ended at 9 when he rattled the black in the jaws of a top corner, and that proved his final shot as a further 20 from Robertson took him over the line. A record 104 centuries were made during the tournament, including nine from Robertson and eight from Liang. “Liang played his part in a really good final,” said Robertson, who received encouraging text messages from Chelsea captain John Terry before the final and again after the 147. “I don’t think you’ll ever see as high a standard from both players in the first session, usually there’s one player who does very well and the other struggles, but we both went blow for blow. “He kept coming back and I wondered when he was going to start missing. When I got to 8-5 I think he started to feel it a little bit. Tonight was about getting the job done and I won a couple of crucial frames to do that. “It’s an incredibly proud moment. To win the Champion of Champions and then this, winning two major tournaments in a row, is something I’ve not done before.” Reflecting on the 147, he added: “As a kid you always want to make one on the BBC, especially in a final. To do it under such pressure was an incredible feeling, the crowd were absolutely amazing. It was probably on par with when I got my 100th century in a season at the Crucible 18 months ago. The pressure of the century of centuries was building up for months but the pressure of the crowd today was very similar. I’m fortunate to have done both. “The Masters is firmly in my sights now and it’s a tournament that brings out the best in me. I’ve got to keep my foot down, work hard over Christmas and try to win that one. Now I’ve won the UK I’m looking at the three Triple Crown events in one season. It’s an incredibly difficult goal but I have to try and set it for myself. But I’m going to enjoy this moment now and I’ll have a pretty decent Christmas to say the least.” Liang was supported in the arena by wife Chen Xue Jiao and son Liang Chen, who flew from China’s Heilongjiang province to the UK this morning. He said: “Neil played very well today. I’m very happy to have got to the final and happy I can play in the Masters. Today I had chances but I missed some shots because of pressure. I didn’t concentrate enough. I needed this experience to learn, I think next time I will be better. I liked playing in front of this crowd.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Robertson wins epic glasgow final', 'robertson-wins-epic-glasgow-final', 'Professional Snooker', '[]'::jsonb, 'Neil Robertson produced an incredible fightback to overturn an 8-4 deficit and defeat Cao Yupeng 9-8 in the final of the Dafabet Scottish Open in Glasgow.', null, '“It was an unbelievable way to cap off the year. My form was definitely coming and I showed that in the UK last week. I just needed to maintain it. I cant remember being involved in too many finals like that, where I had to come from so far behind. I was millimetres from losing with Cao rattling the black.', 'Neil Robertson produced an incredible fightback to overturn an 8-4 deficit and defeat Cao Yupeng 9-8 in the final of the Dafabet Scottish Open in Glasgow.

more It’s a first ranking title since the 2016 Riga Masters for the Thunder from Down Under and it sees him move up to 15th in the world after dropping down to 20th in the rankings at last week’s UK Championship, meaning he now misses out on next month’s Dafabet Masters. Defeat for Cao in his maiden ranking final came in the most excruciating manner. However, the world number 67 can take solace from his best ever career run and the fact that he made his first professional 147 in his opening round tie with Andrew Higginson. The afternoon session belonged to Cao, who played the more composed snooker as he opened up a 5-3 advantage. It would prove to be an evening of unfathomable drama at the Emirates Arena. However, Cao began the session in equally calm measure, making breaks of 72, 81 and 66 to take an 8-4 lead at the mid-session and he required just one for the title. When they returned Robertson applied the pressure with a gutsy contribution of 85 to move three behind at 8-5. With the title within his grasp, the gravity of the situation began to take its toll on Cao, who regained his tourcard at Q School in 2016. He started to miss opportunities which he was hoovering up earlier in the match. Both players had chances as the tension grew, but it was Robertson who claimed the following two frames to draw within one at 8-7, before an incredible 16th frame. Cao looked set to dramatically clinch the title by clearing the colours, before missing a straightforward pink. He had another chance on the final black, but jawed it and the ball remained over the pocket to allow Robertson to set up a decider. The 35-year-old Triple Crown winner showed his metal by firing in a break of 59 under extreme pressure. He eventually crossed line to take home the title. Robertson has now won four of his 13 ranking titles in Scotland, having previously secured victories at the 2006 and 2009 Grand Prix and the 2010 World Open. It was a remarkable showing of break building this week, as he fired in 11 centuries to equal the tally Marco Fu accumulated winning the title last year. The 2010 World Champion said: “I started to notice some nerves and jitters in his cue action and I was super aggressive the next few frames. It was all out attack to put him under pressure. “He just completely outplayed me for a lot of the match. Up to 8-4 it was one of the best performances ever against me He played as the underdog and was free flowing with no pressure. I was expecting some of the mistakes he made at the end to come at the start of the match. “It was an unbelievable way to cap off the year. My form was definitely coming and I showed that in the UK last week. I just needed to maintain it. I cant remember being involved in too many finals like that, where I had to come from so far behind. I was millimetres from losing with Cao rattling the black. “I would much rather win this and pick up a huge victory, than scrape into the Masters and not have a shot at winning it. I can rest up now. I have practised so much over the last couple of months. I must have been playing 200 long pots a day. My main threat is with my long potting. When my hand is on the table I will go for it.” Afterwards a despondent Cao admitted that the nerves got to him in the latter stages of the match. Cao said: “I am just a little bit sad, because I put too much pressure on myself when I got close to winning. My heart needs to be a bit stronger and that is what I need to learn from Neil and the top 16 players. They don’t lose control in the big moments of the game. “i don’t want to think about it too much. Today was not a good day. I just needed one more frame. I was 8-4 up. Hopefully it won’t be too bad for my confidence.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Rock Blast For Dynamite Day', 'rock-blast-for-dynamite-day', 'Professional Snooker', '[]'::jsonb, 'Ryan Day doubled his tally of ranking titles by beating Cao Yupeng 4-0 in the final of the ManBetX Gibraltar Open.', null, 'Day said: “To win two tournaments in a short space of time is really good and there are a lot of positives to take from this week. I scored well when I got chances in the final.', 'Ryan Day doubled his tally of ranking titles by beating Cao Yupeng 4-0 in the final of the ManBetX Gibraltar Open.

more Welshman Day took just 59 minutes to win the final at the Victoria Stadium, capturing the trophy and £25,000 top prize. Breaks of 58, 72 and 100 put him 3-0 up, and he got the better of a scrappy fourth frame to seal victory. It’s another boost for 37-year-old Day in what was already the best season of his 19-year career. At the start of the campaign he had never won a ranking title, despite reaching four finals. He broke that duck at the Riga Masters in June, and has now added a second. He also reached the semi-finals of the UK Championship and is up to 17th in the world rankings. Day won seven matches in Gibraltar, notably beating Joe Perry 4-1 in the quarter-finals and edging out Scott Donaldson 4-3 in the semis having been hauled back from 3-0 up to 3-3. China’s Cao reached the final of a ranking event for the second time; the first coming at the Scottish Open in December when he squandered an 8-4 lead and lost 9-8 to Neil Robertson. This time he was no match for his opponent in the final, though the 27-year-old suffered the added disappointment of missing out on a place at the lucrative Players Championship later this month. Victory would have shot Cao into the top 16 of the one-year ranking list and given him a spot in Llandudno, but the £12,000 runner-up prize is not enough, so Graeme Dott clings on to 16th position (click here for the line up). On the official two-year list, Cao is up seven places to 43rd. Day said: “To win two tournaments in a short space of time is really good and there are a lot of positives to take from this week. I scored well when I got chances in the final. “My goal now is to get into the top 16 in time for the World Championship so I don’t have to qualify (he currently lies 17th in the race to the Crucible). Everyone in the mix is desperate to do that because it’s a massive advantage. I’m not in the China Open so I’ll need a good run in Llandudno to achieve that. “At the Welsh Open I played with a new cue, I only got it 15 minutes before my first match and I thought it was the cue I had been looking for since my old one snapped in September. I lost in the first round there, but this week I have cemented the fact that it was the right decision and this is going to be the cue going forward.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Rocket Flies To Magical Maximum', 'rocket-flies-to-magical-maximum', 'Professional Snooker', '[]'::jsonb, 'Ronnie O''Sullivan made a stunning 147, the 13th maximum break of his career, in a 6-0 victory over Matthew Selt at the Coral UK Championship.', null, '"I was shaking like a leaf at the end - the blue just about went in and on the pink I was shaking but I hit it good. I celebrated before the black because I thought I can''t really miss. Although Ken Doherty missed one once so I thought don''t make yourself look stupid."', 'Ronnie O''Sullivan made a stunning 147, the 13th maximum break of his career, in a 6-0 victory over Matthew Selt at the Coral UK Championship.

more By Mark Rawlinson WATCH RONNIE COMPLETE THE 147 147 Facts It''s the 109th official maximum in snooker history. O''Sullivan has now made a record 13. Stephen Hendry has had 11. The Rocket''s 12th came at the Welsh Open in March, in the last frame of the final. He will win a £40,000 bonus from the rolling 147 prize pot, plus the £4,000 high break prize. However if someone else makes one during the Coral UK Championship, the prizes will be shared. It''s the fourth 147 of the season. Aditya Mehta, Ryan Day and Shaun Murphy made the others. It''s the third consecutive year that a 147 has been made in the final stages here in York. John Higgins made one in 2012 and Mark Selby last year. O''Sullivan created another piece of snooker gold as he hit a brilliant maximum break in the final frame, bringing the York Barbican crowd to their feet. The Rocket dominated the match from start to finish to secure his place in the quarter-finals, against Anthony McGill on Friday afternoon. In the last frame, he had the reds open early in the break and cleared the 15 reds with blacks with little trouble. With the adrenaline pumping, the four-time UK Champion almost over-cut the blue to a middle pocket, but it just dropped in after hitting the jaw. Firing the pink into the middle and screwing back for the black, O''Sullivan gave a fist pump before sinking the black to send the near-capacity crowd into raptures. Earlier, he eased into a 4-0 lead with top breaks of 76, 61 and 52. O''Sullivan then went for a 147 in the fifth frame, but could only make 89 before missing the 12th black. "I''m lucky that I''m able to play to such a level and perform like that," said O''Sullivan after winning his eighth consecutive competitive match. "I don''t think there are many sports people that feel that feeling in their job. So I feel extra lucky and special that I''m able to create the great moments. "147s definitely still excite me and get the adrenaline going. I already had the record at 12 and I thought someone will have to go far to beat that, but it''s always nice to add to that and make it more difficult for someone to reach. "The fans will go home and feel like they want to come back and watch another snooker game. I feel like I''ve done my job to make people want to come back and watch snooker again. "I was shaking like a leaf at the end - the blue just about went in and on the pink I was shaking but I hit it good. I celebrated before the black because I thought I can''t really miss. Although Ken Doherty missed one once so I thought don''t make yourself look stupid." Selt said: "I just didn''t settle at all. I had a couple of chances early in the first frame - I think I missed the black and nearly fell over. I didn''t play how I wanted to and didn''t settle and I felt it was always going to be 6-0 from 3-0 onwards. "I''m more happy than he is that he made that 147. It was a great experience and I had the best seat in the house to watch it. I was sat in my chair when he went up for the yellow and I could barely sit down, I was shaking that much for him." Stephen Maguire was the last man through to the quarter-finals as he beat David Morris 6-3 on the other table. Morris was playing in the last 16 in York for the second year running, but he started tonight''s match slowly. Maguire led 3-1 at the interval, thanks to a top break of 108. Morris hit back to win the next two to draw level, with a 90 break in the fifth. But Maguire, who won the UK Championship ten years ago, saw out the win by taking the next three without reply, including breaks of 41, 74 and 41. "It was a strange game," said Maguire, who faces Marco Fu tomorrow evening in the next round. "I was looking at the score at 3-2 and I couldn''t believe it was 3-2 because I felt like I was the only one that was making chances. "He had a couple of cracking flukes to get him involved in the game and it could have been anyone''s really. To pull away from 3-3, I was chuffed to bits. "I''m pleased that I''m playing in the evening again tomorrow because I''m a little bit tired now. It means I can go out now and get a meal and watch everyone else twitching tomorrow afternoon." Article courtesy of the World Snooker Images Courtesy of: World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Rocket romps to Welsh title', 'rocket-romps-to-welsh-title', 'Professional Snooker', '[]'::jsonb, 'Ronnie O’Sullivan came from 5-2 down to beat Neil Robertson 9-5 in the final of the BetVictor Welsh Open in Cardiff.', null, '“Robertson had the first clear chance in frame 12 but could only make 21 before missing a tricky red to a top corner. O’Sullivan punished him with a run of 70 to lead 7-5. Keeping his momentum building after the interval, O’Sullivan dominated the 13th frame with a break of 61 to move within one of the title. Typically, he finished in fabulous fashion as a long red set up a 141 total clearance."', 'Ronnie O’Sullivan came from 5-2 down to beat Neil Robertson 9-5 in the final of the BetVictor Welsh Open in Cardiff.

more An enthralling match appeared to be going Robertson’s way when he controlled the early stages, but a handful of errors in the evening session cost him as O’Sullivan caught fire. It was a blistering finish to the tournament from O’Sullivan in a week which has seen him produce brilliant snooker even by his own high standards. The Rocket won his fourth Welsh Open crown, matching the record set by John Higgins last year, and the 28th ranking title of his career, equalling the tallies of Higgins and Steve Davis. Only Stephen Hendry is ahead of that formidable trio on 36. The £60,000 top prize moves Chigwell’s 40-year-old O’Sullivan up one place to fourth in the world rankings and also makes him eligible to enter the World Grand Prix in Llandudno next month. In winning seven matches this week, O’Sullivan has won 36 frames and conceded just 11, making ten centuries in the process. After taking a few months off at the start of the season, he has won 19 consecutive matches in 2016, capturing the Masters and Welsh Open titles as well as winning a Championship League group. Unusually, O’Sullivan has admitted himself this week he has been close to his best, while his fellow professionals have been unanimous in their admiration of his sheer talent. Ben Woollaston perhaps put it best when he said: “I was watching him and laughing at how good he is. It’s as if he’s playing a computer game.” Yesterday, O’Sullivan had compared Robertson to RoboCop for his composure and ruthlessness, but the Australian finished the final disappointed with the mistakes he made when he was in charge. The 34-year-old missed out on the chance to win a 12th ranking title and add this trophy to those he won at the Champion of Champions and UK Championship before Christmas. He earns £30,000 and stays third in the rankings. Today’s two finalists will surely be the favourites for the World Championship title come the Spring. Leading 5-3 after the first session, Robertson had a chance to extend his lead in the opening frame tonight but missed a red to a centre pocket on 39. O’Sullivan replied with 57 before playing safe on the last red, and he later potted the red to reduce his arrears. Both players passed up chances in frame ten and it came down to the last two reds. Robertson narrowly failed to convert a long pot and his opponent took advantage to level at 5-5. And a break of 67 in the next gave the Englishman the lead for the first time. Robertson had the first clear chance in frame 12 but could only make 21 before missing a tricky red to a top corner. O’Sullivan punished him with a run of 70 to lead 7-5. Keeping his momentum building after the interval, O’Sullivan dominated the 13th frame with a break of 61 to move within one of the title. Typically, he finished in fabulous fashion as a long red set up a 141 total clearance. “I just hung in there in the first session because nothing quite happened for me,” said five-time World Champion O’Sullivan. “I tried to stay positive, using all the skills that I’ve learned from (psychiatrist) Steve Peters over the last four or five years. “Neil steam-rollered me, kept me tight and played some hard match snooker. I only got going towards the end. It wasn’t the best match in the world but not the worst either. “The record books don’t bother me, I’m not really interested in that. I’m interested in just enjoying the game, as I have this week. Even if I had lost in the final it still would have been a great week. “I’m not getting better, you don’t get better from 35 onwards. You just have to try to maintain what you’ve got and look after it. I’ve just recaptured what was always there and it’s nice to find it coming out now and again. “I haven’t slept for the last three nights, I think everybody knows I’ve got insomnia. I’m absolutely knackered and it was really hard for me out there. I had to ignore that and just try to pot some balls. I have to start taking some medication which helps me sleep. I think I need a nice easy month now so I can fill the tank up again.” “I just missed a couple of awkward shots tonight and he was getting into his groove. He never had to pot a ball more than two feet away to get in. I made it pretty easy for him and he’s a very special player to be able to construct the breaks as quickly as he does. But the first two frames tonight, I should never have lost those. I missed a tricky pink in the middle and a really tricky red in the middle, two shots that caught the jaws. If they go in I go on to win the frame. “From 5-5 he gathered pace and he is pretty hard to stop. Overall I had a good week, but losing any final is tough to take. I’ve won my previous two finals so the law of averages will say that I’m probably going to lose one. “The crowd has been fantastic all week and it’s a brilliant tournament, one of my favourite tournaments and I hope it is going to stay here at this venue for many years.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Ronnie Is Champion Of Champions', 'ronnie-is-champion-of-champions', 'Professional Snooker', '[]'::jsonb, 'Ronnie O''Sullivan won the inaugural 888casino Champion Of Champions tournament with a 10-8 final victory over Stuart Bingham.', null, '"I think sometimes when you get near the winning line you have to make it happen. I learnt my lesson years ago against Stephen Hendry, where I maybe played a couple of negative shots in the latter stages of the game and he didn''t, he took the bull by the horns and for me that was one of my biggest lessons in snooker."', 'Ronnie O''Sullivan won the inaugural 888casino Champion Of Champions tournament with a 10-8 final victory over Stuart Bingham.

more Ronnie O''Sullivan 10-8 Stuart Bingham 26-109 (109), 82-48 (66), 66-47 (55, 33), 53-57 (34 Bingham), 1-72 (72), 1-66 (52), 76-4 (76), 0-133 (109), 130-0 (130), 99-1 (93), 64-54 (32, 54), 37-64 (48), 35-65, 91-8 (62), 96-34 (96), 38-74 (38, 66), 65-29 (46),83-0 (33, 49) O''SULLIVAN put in another superb match play performance as he held off Bingham in the closing stages to claim the title and a cheque for £100,000 at the Ricoh Arena, Coventry. The World Champion, who has slumped right down the world rankings due to inactivity, showed that he is still the man to beat as he came through a star-studded field to claim snooker''s newest title. O''Sullivan had come through his group stage on Friday with a 4-0 win over Mark Davis and then a superb 6-5 victory over Ding Junhui in an outstanding encounter. That put him into Saturday''s semi-finals where he once again dug deep to beat Neil Robertson in the deciding frame. That set up Sunday''s best of 19 frame final against Bingham who had qualified for the event by virtue of his Premier League title a year ago. A delighted O''Sullivan said: "It has been brilliant, the facilities have been good, the venue has been great and it has been a great three days and I have really enjoyed it. "It is the first time this tournament has happened so I am really pleased to have got my name on the trophy and it will give me an invite to come back next year." Bingham took a 5-4 lead into the evening session, having made two centuries. On the resumption, O''Sullivan stormed out with a break of 93 to level things at 5-5. Bingham missed a black off the spot to give O''Sullivan a great opportunity in the next and he eventually took advantage to move into the lead. That didn''t last long though as Bingham stole two close frames to regain the lead at 7-6, but 30 minutes later it was O''Sullivan who went 8-7 up following breaks of 62 and 96. Bingham made it 8-8 with a break of 66 to set up a climactic finish. O''Sullivan took the next before breaks of 33 and 49 saw him clinch the title as the sell-out crowd of 700 cheered him home. "Stuart has had a great tournament and another good season and I am just pleased to have got the victory, that is all you can hope for," said the Rocket. "Whether you play well or not, sometimes you just have to grind out a result and that is what I managed to do here today. It was ebb and flow all the way, at one stage I didn''t think I was going to win, but I managed to hold it together in the end. "I think sometimes when you get near the winning line you have to make it happen. I learnt my lesson years ago against Stephen Hendry, where I maybe played a couple of negative shots in the latter stages of the game and he didn''t, he took the bull by the horns and for me that was one of my biggest lessons in snooker. "I knew then that if I was to become a regular winner of tournaments I needed to have the same philosophy. At the end of the game I always think this is the time you need to make it happen. "I played okay against Ding and Neil but we both struggled a bit today. It wasn''t terrible but I have not played as well this week as I have done over the last couple of years," he added. Bingham can take consolation with the £50,000 runners-up cheque and the fact that only a player of O''Sullivan''s outstanding ability ended his run in the tournament. "It''s great to be in a final with Ronnie," said Bingham. "It was a good day, neither of us played spectacularly but it was good for the crowd, they have been fantastic all week. It has given me a lot of confidence for the UK Championship next week. "I think everyone, all the players, have loved the tournament and we want more of it. Everyone involved in the tournament, ITV, the sponsors, they put on an amazing tournament and hopefully we will have this for many more years to come." Article courtesy of the World Snooker Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Ronnie O''Sullivan to return to snooker and defend his world title', 'ronnie-osullivan-to-return-to-snooker-and-defend-his-world-title', 'Professional Snooker', '[]'::jsonb, 'Ronnie O’Sullivan’s decision to defend his World Championship title is good news for snooker and, I suspect, good news for him.', null, '"For the event to have gone ahead without its defending champion would have been a blow. O’Sullivan has guaranteed media interest in the Crucible as the countdown to snooker''s version of the greatest show on earth begins.".', 'Ronnie O’Sullivan’s decision to defend his World Championship title is good news for snooker and, I suspect, good news for him.

more O’Sullivan admitted to being bored during his sabbatical from tournament play. Competing in major events creates a buzz difficult to replicate in ordinary life or exhibitions. A lucrative personal sponsorship deal with a vodka company would also have helped him make up his mind. Whether O’Sullivan is the best player in the game is a point for argument but that he is the biggest draw is not. This is why the media flocked to his press conference today. World Snooker say he is yet to formally enter the World Championship but he has until Thursday to do so. For the event to have gone ahead without its defending champion would have been a blow. O’Sullivan has guaranteed media interest in the Crucible as the countdown to snooker''s version of the greatest show on earth begins. O’Sullivan’s decision is good news too for Judd Trump. As probable no.1 seed in O’Sullivan’s absence he would have been walking out to play on the first day with all the pressure that comes with that. Plus, most of the pre-event media attention would have been on him. Now it will all be on O’Sullivan. I’m sure many players were hoping Ronnie would stay away. As he proved last year, he is still a potent force when his mind is finely tuned towards snooker. On the face of it, it seems unlikely that he can come back with barely any match snooker all year and defend his world title but O’Sullivan’s whole life has revolved around the unlikely. For a long time he has seemed to feel that not playing snooker was the answer to his problems but time away has convinced him that he does indeed love the game and the challenges it presents. Snooker has survived without him. Ticket sales and TV viewing figures have gone up this season. But O’Sullivan is a fascinating figure whose presence in tournaments adds to the general intrigue. Nobody, sometimes not even Ronnie himself, knows what he is going to do next. It appears come April 20th he is going to play snooker again. The king across the water is coming home. If he wins a fifth world title it will surely be his greatest ever triumph. Article courtesy of the Snooker Scene Images Courtesy of: Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('Ronnie takes a break', 'ronnie-takes-a-break', 'Professional Snooker', '[]'::jsonb, 'Ronnie O''Sullivan made the headlines again today as he announced he will not play on the main tour again this season.', null, '"O''Sullivan''s absence will be a sore loss, make no mistake. His manager Django Fung alluded to the fact that he may never return to the game, but again this is a decision he should be allowed to make freely.".', 'Ronnie O''Sullivan made the headlines again today as he announced he will not play on the main tour again this season.

more This means he will not play in the UK Championship or The Masters and, more crucially, he will not defend his world title at the Crucible. His decision has been prompted by yet more personal issues and World Snooker released this official statement earlier. As usual, Ronnie''s decision has been greeted with criticism and cynicism but, in fact, it is probably the right one. O''Sullivan''s battle against glandular fever has been long and troublesome. His fight to win access to his children has allegedly not been easy either. Health and family life are things Ronnie values dearly. And while snooker is not the cause of his problems, it certainly doesn''t help. So Ronnie has decided to take a break from the sport. He has given the it so much. He owes it nothing. He has won everything there is to win and has enough money to ensure a comfortable lifestyle. He has made a decision that will ultimately take off the pressure and make him a happier man. This deserves admiration. O''Sullivan''s absence will be a sore loss, make no mistake. His manager Django Fung alluded to the fact that he may never return to the game, but again this is a decision he should be allowed to make freely. The severity of today''s announcement may have shocked many but it puts an end to the ''will he or won''t he withdraw'' debate that arises before every ranking event. His intentions are clear and everyone knows where they stand. Ronnie has won more in snooker than most ever will. Sure, many people believe he could have won even more, but his place as legend was secured long ago. If he does choose to take his place back on the baize, he will be as popular as ever and welcomed with open arms. The challenge of having to fightback from potentially outside the top 32 of the world rankings may be the challenge he craves, or it could trigger him to call it a day. What will Ronnie do next? Is this the end of an era? Article courtesy of the OneCue Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Rory rules in Ruhr', 'rory-rules-in-ruhr', 'Professional Snooker', '[]'::jsonb, 'Rory McLeod won a title carrying ranking points for the first time by beating Tian Pengfei 4-2 in the final of the Ruhr Open in Mülheim, Germany.', null, 'It feels great, it’s everything that I really wanted,” said McLeod. “In the final I just tried to stick in there, stay positive and not get ahead of myself. I just wanted to enjoy it because this is where I want to be.', 'Rory McLeod won a title carrying ranking points for the first time by beating Tian Pengfei 4-2 in the final of the Ruhr Open in Mülheim, Germany.

more World number 61 McLeod beat 70th-ranked Pengfei in a surprise final at the season’s third Kreativ Dental Clinic European Tour event. Leicester-based 44-year-old McLeod, snooker’s only black professional, collected the 25,000 Euro top prize after winning seven matches. His only previous pro title came at the qualifying event for the Masters in 2009. McLeod, who has never been past the last 16 of a full ranking event, went 2-0 up in the final with top breaks of 57 and 41. China’s Tian, playing in his first pro final, pulled one back with a run of 78. Frame four went to McLeod thanks to a break of 58 then Tian hit back again with a superb 106. But McLeod was not to be denied as he sealed victory in frame six with a top run of 55. “It feels great, it’s everything that I really wanted,” said McLeod. “In the final I just tried to stick in there, stay positive and not get ahead of myself. I just wanted to enjoy it because this is where I want to be.” Earlier in the semi-finals, McLeod beat Mike Dunn 4-1 while Tian edged out David Gilbert 4-3. The Kreativ Dental Clinic European Tour is a series of six events across the continent, with the top 24 on the final Order of Merit to qualify for the Players Championship. The next event is the Bulgarian Open in Sofia from November 4-8. Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Runabout Shield heads to Meva', 'runabout-shield-heads-to-meva', 'Match Reports', '[]'::jsonb, 'In the Rees League the Runabout Shield changed hands as Mevagissey ‘C’ went to Bethel ‘D’ and thrashed the holders 4-1.', null, 'The Bugle derby was a tight affair as Gary Spencer and Ian Ball put the ‘A’ side 2-0 up. The ‘B’ team replied with wins for M Sturtridge and Tony Conroy levelling things up but a majestic break of 65 by Andrew Best in the last settled the tie.', 'In the Rees League the Runabout Shield changed hands as Mevagissey ‘C’ went to Bethel ‘D’ and thrashed the holders 4-1.

more Dayle Dyche was the home side’s only bright spot beating Adrian Evans but ‘Predator’ Tregale, Ben Prynn, Joe and Matty Chesterfield saw the trophy heading back to the Meva club. Lerryn’s first game of the season saw them take all five points off Tregonissey ‘C’. Stacey and Jackie Hancock pushed John Hancock and Dave Vipond all the way but just fell short. There were other wins for Terry Middleton, Graham Hoskin and Charles McMiram. Craig and Terry Nicholls got two good points for Lostwithiel at Bethel ‘C’, who are top, Ben Stunnell, Courtney Crockford and Paul Thomas got the home points. Chris Brown and Rob Garside put St Stephen 2-0 up at home to Bethel ‘B’ but the visitors finished strongly with wins for Dave Johnson, Jim Tamblyn and Richie Bolt. Top match in the Victory League was at Tregonissey. Where Barrie McIntosh knocked in a fine 48 break in the opener to see off Phil Staley, James Popplewell levelled things beating Ryan Bilson and Matt Mills gave the away side the lead getting the better of Jason Cocks only for Jason Simmons and Chris Stephenson to claim the spoils seeing off Paul Williams and Leighton Varcoe respectively. The Bugle derby was a tight affair as Gary Spencer and Ian Ball put the ‘A’ side 2-0 up. The ‘B’ team replied with wins for M Sturtridge and Tony Conroy levelling things up but a majestic break of 65 by Andrew Best in the last settled the tie. Phil Ormand and Andy Parnell put Pelynt 2-1 up at St Neot after Darren Lock’s win for the home side, but Cyril Dickenson and Steve Courts, who made a 53 got St Neot home. There were some excellent snooker at St Blazey who entertained Bethel. Matt Green, Gary Stephens and Leon Collard got the away points with Mickey Meares and Nick Kendall gaining the home points. Mike Hooley took the first frame for Tregonissey ‘C’ at Mevagissey ‘B’ who responded with close wins for Dave Kendall, Matt Rowe and Ben Rothwell and a walkover for Mark Gregory secured their four points. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Second defeat for early season pace setters', 'second-defeat-for-early-season-pace-setters', 'Match Reports', '[]'::jsonb, 'Victory League leaders Bugle ‘A’ slipped to their second defeat of the opening six games against Tregonissey ‘A’, who had Barry McIntosh’s 30 break and black ball win over Andrew Best to take the victory.', null, '"Lostwithiel ‘B’ showed they want a swift return to the top league after seeing off Bethel ‘B’ 3-2, Len Flower, Andy Parnell and George Lory were very impressive in their victories with Guy Buckle and Jim Tamblyn replying."', 'Victory League leaders Bugle ‘A’ slipped to their second defeat of the opening six games against Tregonissey ‘A’, who had Barry McIntosh’s 30 break and black ball win over Andrew Best to take the victory.

more Jason Cocks and Ryan Bison had put Treggy two up but Ian Powell and the unbeaten Gary Spencer replied leaving the last frame shootout. Only four points separate the top four but Bugle have played a game more in what is turning out to be a very unpredictable season. Mevagissey ‘A’s 3-2 victory at St Blazey ‘B’ saw them consolidate third place. Paul Williams, Matt Mills and Pete Chambers’ final-frame victory including a 31 break over Andrew Gooch saw Paul Baron’s team drop to sixth place. Gary Stephens’ 34 break and victory over Anthony Maddams was Bethel ‘A’s only bright note as they slumped to a 4-1 defeat at Lostwithiel ‘A’. Cyril Dickenson and Steve Courts were particularly good performers on the night. St Blazey ‘A’ pulled off an excellent 4-1 win at Mevagissey ‘B’, Kendall, Brown, Mears and Rosevear with victories with Mark Gregory replying. Lostwithiel ‘B’ showed they want a swift return to the top league after seeing off Bethel ‘B’ 3-2, Len Flower, Andy Parnell and George Lory were very impressive in their victories with Guy Buckle and Jim Tamblyn replying. Tregonissey ‘B’ have jumped to the top of the Rees League courtesy of a 4-1 victory over Bugle ‘C’, Nigel Couchman was the visitors’ only winner as Robins, Simon and the Hooleys ran riot. Gorran Haven recorded their second victory of the season with a 3-2 win over Lerryn. Richard Holmes gave Graham Hoskin his first defeat of the season along with wins for Lee McKinstry and Paul Grimmett. Mevagissey ‘C’s strong 4-1 home victory over St Stephen ‘A’ has put them well in the hunt. Charlie and Ben Prynn, Matt Chesterfield and Dave Tregale puts them second in the table. And finally Mevagissey ‘D’ are finding some momentum with a second straight win, this time 4-1 at St Stephen ‘B’. Graham Rosevear once again on target for the home side with Rob Blamey finally breaking his duck for the season for the visitors.

FULL RESULTS

Victory League: Mevagissey ‘B’ 1 (M Gregory) St Blazey ‘A’ 4 (N Kendall, C Brown, M Meares, L Rosevear), St Blazey ‘B’ 2 (P Baron, G Taylor) Mevagissey ‘A’ 3 (P Chambers (31), P Williams, M Mills), Bugle ‘A’ 2 (I Powell, G Spencer) Tregonissey ‘A’ 3 (J Cocks, R Bilson, B McIntosh (30)), Lostwithiel ‘A’ 4 (C Dickinson) Bethel ‘A’ 1 (G Stephens (34). Rees Memorial League: Mevagissey ‘C’ 4 (C Prynn, D Tregale, B Prynn, M Chesterfield), St Stephen ‘A’ 1 (C Clarke), Tregonissey ‘B’ 4 (S Simon, P Hooley, C Robins, J Hooley) Bugle ‘C’ 1 (N Couchman), Bethel ‘B’ 2 (G Buckle, J Tamblyn) Lostwithiel ‘B’ 3 (L Flower, A Parnell, G Lory), St Stephen ‘B’ 1 (G Rosevear) Mevagissey ‘D’ 4 (R Blamey, J Tomlinson, R Lakeman, S Mills), Gorran Haven 3 (R Holmes, L McKinstry, P Grimmett) Lerryn 2 (G Brimicombe, C McMiram). Top breaks of the week: P Chambers 31, B McIntosh 30, G Stephens 34 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Selby Conquers The World', 'selby-conquers-the-world', 'Professional Snooker', '[]'::jsonb, 'Mark Selby conquered the Crucible for the first time by beating Ronnie O''Sullivan 18-14 in the final of the Dafabet World Championship.', null, '"All tournament I''ve felt confident and I knew if I got a chances I felt like I was going to score even though I didn''t yesterday. Ronnie came back to 15-14 and asked me the question, and I probably played my best snooker of the match in those last three frames."', 'Mark Selby conquered the Crucible for the first time by beating Ronnie O''Sullivan 18-14 in the final of the Dafabet World Championship.

more Selby produced an astonishing fight-back to win 13 of the last 17 frames and inflict O''Sullivan''s first world final defeat on the five time champion. O''Sullivan was looking for a third consecutive crown and appeared to be cruising when he led 8-3 and 10-5 on Sunday. But Selby rallied to 10-7 overnight then won five of the six frames in the third session as O''Sullivan, uncharacteristically, crumbed under the intense pressure. And Leicester''s 30-year-old Selby produced his best snooker of the match in the concluding session, winning the last three frames and sealing victory with a stunning clearance. He goes home with the trophy and a record £300,000 top prize, which makes him world number one on the new money list. Since reaching his first Crucible final in 2007 - when he lost to John Higgins - Selby has become one of snooker''s most consistent competitors, enjoying previous spells at the top of the rankings and winning the Masters three times as well as the UK Championship. The world title was the one glaring omission on his CV, but he now has his name engraved on the sport''s most famous piece of silverware. The best safety player in the world, he also produced nerveless breaks at key moments throughout the Championship, notably in the deciding frame of a 10-9 first round win over Michael White, and in the last session of his superb 17-14 victory over world number one Neil Robertson in the semi-finals. Selby becomes the ninth player in snooker history to win the Triple Crown of major titles, joining Steve Davis, Stephen Hendry, John Higgins, Ronnie O''Sullivan, Mark Williams, Terry Griffiths, Alex Higgins and Neil Robertson. He was runner-up in both the UK and the Masters this season - thrashed 10-4 by O''Sullivan in the latter - but picked the perfect moment to win his first ranking title of the campaign and fourth of his career. O''Sullivan''s long unbeaten spell in Sheffield came to an end after winning 14 consecutive matches. He was denied the sixth world title of his career, which would have brought him level with Steve Davis and within one of Stephen Hendry''s record. The Rocket, who had won his quarter and semi-final matches with a session to spare, was a huge odds-on favourite for the title when he led 10-5. But he lost all confidence and fluency in the third session, and despite dressing room huddles with psychiatrist Steve Peters, he was unable to regain his rhythm. Trailing 12-11 going into the final session, O''Sullivan started strongly tonight with a break of 100, his 13th century of the tournament. But a missed black on 24 in the next stopped him from gathering momentum as Selby ground out that frame to regain the lead. Runs of 23 and 25 helped Selby gain control of frame 26 and he sealed it by potting the pink after his opponent failed to gain the snooker he needed. And safety errors from O''Sullivan in the 27th gave Selby the opportunity to make 56 and extend his lead to 15-12 at the interval. O''Sullivan took the next in two scoring visits, then made a stunning 37 clearance in frame 29, highlighted by a drilled yellow down the length of a side cushion. But Selby wrestled back the initiative emphatically, making a 127 - his only century of the final - followed by an 87 to lead 17-14. O''Sullivan looked certain to pull one back until he ran out of position at 56-0 in the next. Selby clawed back to within 29 points with one red left. And when his chance came, he proved himself a true champion. A long red was followed by a series of terrific pots, particularly the green which was close to the top cushion, as he cleared the table to capture the title. "It hasn''t sunk in yet," admitted Selby after winning the final watched by stars including actor Stephen Fry, darts supremo Phil Taylor, Iron Maiden drummer Nico McBrain and Muse frontman Matthew Bellamy. "In the next few days it will definitely settle in. To come through playing Ronnie in the final, it''s a dream come true if you''re going to win your first world title. "At 8-3 down, I knew Ronnie is one of the best front-runners in the world and I was just not playing well at all. I had my chances but kept missing and Ronnie was taking advantage most of the time. A couple of times he missed and I just kept digging in and nicking a few frames. "To get out 10-7 down yesterday, I felt I was winning 10-7. I was physically and mentally tired yesterday - the same as when I got to the final seven years ago against John Higgins. Ronnie outplayed me yesterday and I was still only 10-7 behind and I still felt I hadn''t turned up. "All tournament I''ve felt confident and I knew if I got a chances I felt like I was going to score even though I didn''t yesterday. Ronnie came back to 15-14 and asked me the question, and I probably played my best snooker of the match in those last three frames. "My father passed away with cancer when I was 16, two months before I turned professional, and his last words to me were ''I want you to become World Champion''. I said to him I will be one day it''s just a matter of when not if. "There have been a lot of people in my life that have helped my through. Willie Thorne''s brother, Malcolm, who sadly passed away a few years ago, spotted me when I used to go to Willie''s club. He put me on the right track and sponsored me for a few years before I turned professional so I owe a lot to him and I''m sure he and my father were looking down smiling as I lifted that trophy." O''Sullivan said: "I want to congratulate Mark on a brilliant match and a brilliant tournament. I tried my hardest but he was just too good. "As a top snooker player you accept the losses with the wins, you can''t have it your own way all the time. I''ve had some great victories here but losing is part of the sport and you''ve just got to accept that it''s part and parcel of it. You have to go away and lick your wounds and go one better next time. "It wasn''t the most free-flowing match. There were a lot of safety bouts and I just got dragged into it. I tried to make something happen and open the balls up a few times but when you''re forcing something to happen, it never quite happens. "Everything I did he just had an answer for and I was finding it hard to put any momentum together. At some points I felt a bit numb out there because I was sat in my chair for long periods of time." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Selby King in Beijing', 'selby-king-in-beijing', 'Professional Snooker', '[]'::jsonb, 'Mark Selby won his fourth ranking title of the season by beating Mark Williams 10-8 in the final of the Bank of Beijing China Open.', null, '“We both played so well, we scored when we got chances and the safety was good,” said Selby, who also won the China Open in 2015. “Overall it was a very good match and neither of us did much wrong. Just a few balls here and there made the difference for me.', 'Mark Selby won his fourth ranking title of the season by beating Mark Williams 10-8 in the final of the Bank of Beijing China Open.

more World number one Selby captured the 11th ranking title of his career and a top prize of £85,000 by coming from 8-7 down to win the last three frames. Defeat was a double blow for 42-year-old Williams as he missed out on his first ranking title in six years and also the chance to regain a place among the world’s top 16. Victory would have given him an automatic spot at the Crucible later this month, but now he must head to the Betfred World Championship qualifiers which start on Wednesday (tickets available – click here for details) and will need to win three matches to make the final stages. Ryan Day must have been the most relieved man following the final as he hung on to the 16th seeding position thanks to his fellow Welshman’s defeat. Selby, meanwhile, will head to the Crucible at the top of his game having had his most successful season to date. He had never previously won more than two ranking events in a single campaign, but following his victories at the Paul Hunter Classic, International Championship and UK Championship, the 33-year-old from Leicester has landed another piece of silverware. In fact Selby had a relatively quiet spell in recent months – failing to reach a semi-final in the seven tournaments which followed his UK triumph in December. But in winning seven matches in Beijing he has established himself as hot favourite as he goes to Sheffield attempting to win his third World title since 2014. A high quality start to the final saw Selby build a 3-1 lead with breaks of 54, 100 and 109, while Williams made a 124 in frame three. The next four were shared, then Williams made a 106 in the last frame of the opening session to trail just 5-4 heading into the conclusion. Williams, whose last ranking title came when he beat Selby in the final of the 2011 German Masters, took three of the first four frames of the evening session with top breaks of 68, 65 and 81 to move 7-6 ahead. Selby restored parity with a 95 before Williams won a tense 50-minute 15th frame on the pink. Selby rose to the occasion with runs of 70 and 124 to edge 9-8 ahead, and he dominated the 18th frame with a top break of 39 to seal the title. “We both played so well, we scored when we got chances and the safety was good,” said Selby, who also won the China Open in 2015. “Overall it was a very good match and neither of us did much wrong. Just a few balls here and there made the difference for me. “I’ll go to Sheffield trying my best. Winning here gives me a lot of confidence, though there are a lot of great players playing well at the moment. I’m going to keep on working hard to try to win more tournaments and stay at number one.” Williams, who won £35,000, said: “It was a fantastic game from start to finish. I was 8-7 up and then didn’t get much of a chance in the last three frames. I was playing the number one in the world and one of the best players ever, and I pushed him all the way. The likes of Trump, Robertson and Murphy are all good players but none of them are in Mark’s league. I had a tough draw and I’m happy with the way I performed all week.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Selby Makes Historic 147', 'selby-makes-historic-147', 'Professional Snooker', '[]'::jsonb, 'Mark Selby made the 100th official maximum break in snooker history at the williamhill.com UK Championship.', null, '"Ronnie O''Sullivan and Stephen Hendry share the record for the most maximum breaks with 11 each. John Higgins has made seven and Ding Junhui 5."', 'Mark Selby made the 100th official maximum break in snooker history at the williamhill.com UK Championship.

more Selby''s historic break came in the seventh frame of his semi-final match against Ricky Walden at the York Barbican. The maximum is worth £55,000 from the rolling prize for ranking events plus an extra £4,000 for the high break, as long as it is not equalled in the remainder of the tournament. Defending champion Selby got the pack of reds open early in the break and picked them off with blacks before taking the colours. He played a superb shot on the brown to go around the angles and finish on the blue. The pink was tricky, played with his cue extension, and he left the cue ball on the top cushion. But Selby rolled a brilliant black into a centre pocket to complete the 147. Given the circumstances, it must be considered one of the best ever blacks to finish a maximum - especially as he missed the last black on 140 at the China Open last season. It''s the third maximum of the season, following Neil Robertson at the Wuxi Classic qualifiers and Judd Trump at the Antwerp Open. And it''s the second of 30-year-old Selby''s career having made one at the 2009 Jiangsu Classic. World number two Selby added the next frame to lead Walden 6-2 and move within three frames of a UK final against Neil Robertson. The defending champion started the match well and took the opening two frames, a 69 break in the first, before winning a battle on the colours to seal the second on the final black (Mark Rawlinson writes). Walden pulled back a closely contested second with a break of 56 but the Chester man missed the final brown in frame four to see Selby take a 3-1 interval lead. Walden won the next with a top run of 43 but a missed pink in the sixth frame allowed Selby to restore his two-frame cushion at 4-2. Selby then took centre stage with the 147, and a break of 53 was enough to secure the last frame of the session. 147 facts: Snooker''s first official 147 was made by Steve Davis at the 1982 Lada Classic. The following year, Cliff Thorburn made the first in the World Championship. There were just eight maximum breaks in the 1980s but since then the standard of play in snooker has risen dramatically. During the 1990s there were 26 maximums, followed by 35 from 2000-2009 and another 31 maximums since 2010. Ronnie O''Sullivan and Stephen Hendry share the record for the most maximum breaks with 11 each. John Higgins has made seven and Ding Junhui 5. There have been ten 147s in the World Championship at the Crucible; three apiece from Hendry and O''Sullivan and one from each of Cliff Thorburn, Jimmy White, Mark Williams and Ali Carter O''Sullivan made the fastest 147 on record at the Crucible in 1997, timed at 5 minutes and 20 seconds The highest possible break in snooker is actually 155, if the player is awarded a free ball before a red has been potted. Only one break over 147 has ever been made in professional play, by Jamie Burnett who made a 148 at the 2004 UK Championship qualifiers. This did not count as a maximum break. The youngest player to make an official 147 is Thailand''s Thanawat Tirapongpaiboon, who did so in a 2010 PTC event, age of 16 years and 312 days. Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Selby Storms To China Title', 'selby-storms-to-china-title', 'Professional Snooker', '[]'::jsonb, 'Mark Selby won his second ranking title in as many months by crushing Gary Wilson 10-2 in the final of the Baic Motor China Open.', null, '"I don''t think I''ve ever won a title before without having to face a top 16 player, but that just shows how high the standard is these days because the likes of Gary and Ben Woollaston are good enough to reach finals."', 'Mark Selby won his second ranking title in as many months by crushing Gary Wilson 10-2 in the final of the Baic Motor China Open.

more World number one Selby dominated the final in Beijing against a player 55 places below him in the rankings to take the £85,000 top prize and the sixth ranking title of his career. Leicester''s 31-year-old Selby becomes the first player to win two ranking titles this season, having captured the German Masters crown in February. His first China Open title is also a confidence boost ahead of his World Championship defence, which starts on April 18th in Sheffield. Selby suffered from neck pain early in the week, but was relieved to discover it wasn''t a recurrence of the bulging disc he suffered in 2012 which forced him to pull out of this event. Instead, he took advantage of a draw which allowed him to win the title without facing a single player ranked within the world''s top 16. Selby won the first three frames of the final, taking two of those on the colours. Wilson, who had never previously got further than the quarter-finals of a ranking event, got a frame on the board with a break of 91 in the fourth. But Selby took the next two with clearances of 39 and 54, and that broke Wilson''s resistance as the Wallsend cueman scored just three points in the next four frames. Selby compiled a tournament-high break of 145 as well as a 136 in building a 9-1 lead. Wilson managed a century of his own - 101 - before Selby clinched the title in frame 12. "I played well for the majority of the match," said Selby. "To be 8-1 up at the end of the first session probably wasn''t a fair reflection on how the match had gone, as a few frames could have gone either way but I managed to pinch them. When I was 6-1 up, it could easily have been 4-3. "I don''t think I''ve ever won a title before without having to face a top 16 player, but that just shows how high the standard is these days because the likes of Gary and Ben Woollaston are good enough to reach finals. "I''m really happy to win this title for the first time, especially having lost in the final twice. It was a good crowd out there tonight with a good atmosphere. "I''ll get home tomorrow, have a few days off and then get back on the practice table to prepare for the Crucible." World number 56 Wilson, age 29, collected his biggest career cheque of £35,000. The former world under-21 champion, who gave up snooker for several years and worked as a taxi driver before returning to the pro tour in 2013, said: "I was looking forward to being in the final, but I let myself down today because I didn''t perform the way I can. "I''m disappointed to have played like that and lost by such a heavy scoreline. I missed a lot of chances. I can still take some positives from the tournament and look forward to the World Championship. Even though I beat Ding Junhui in the semi-finals yesterday, there was still something in the back of my mind saying I wasn''t playing well, and today I went backwards. It wasn''t pressure or nerves because I felt comfortable. I just cued across a lot of balls and played some very bad shots, which cost me a lot of frames." Article courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Selby Takes German Glory', 'selby-takes-german-glory', 'Professional Snooker', '[]'::jsonb, 'Mark Selby won his first ranking title since becoming World Champion by beating Shaun Murphy 9-7 in the final of the Kreativ Dental German Masters.', null, '"Coming here from China, I wasn''t expecting much," said Selby. "I always believe I can win, but with the fatigue I knew it would be difficult and I had to show a lot of character. Maybe that took pressure off me, but I was cursing myself because I knew if I lost I would only have myself to blame. It''s hard to believe I''m standing here having won the title. I have struggled this season so to win this by beating Shaun - who is the form player - is fantastic."', 'Mark Selby won his first ranking title since becoming World Champion by beating Shaun Murphy 9-7 in the final of the Kreativ Dental German Masters.

more A passionate crowd at the iconic Tempodrom in Berlin - widely recognised as one of the best venues on the circuit - were treated to a cracking final as Selby came from 5-2 down to win seven of the last nine frames. In fact the crucial moment of the match was the last frame of the opening session when Selby made a superb clearance to trail just 5-3 going into the evening''s play. Leicester''s 31-year-old Selby captured the 80,000 Euro top prize and fifth world ranking title of his career. Victory also sends him back to the top of the ranking list. Up until this week it had been a quiet season for Selby - his only title coming at the Riga Open European Tour event - and he had reached only one semi-final in the main ranking events. With the added expectation that comes with being World Champion - not to mention the arrival of a daughter in November - he had struggled to find the game which conquered the Crucible last May. Ironically, his preparation for this event was the worst of his season as he spent a week in China playing eight-ball pool, reaching the final. If cue sports do earn a place at the 2020 Olympics, Selby will surely be a contender for multiple gold medals. He flew from Shanghai to Berlin, arriving the night before the tournament started, and after battling jet-lag to scrape through his opening match, he gathered momentum as the week progressed, and looked close to his brilliant best in wins over Judd Trump, Stephen Maguire and Murphy. Runner-up to Mark Williams at the Tempodrom in 2011, Selby is now German Masters champion for the first time. Murphy missed out on a sixth title in 12 months and back-to-back crowns having won the recent Masters. Still, the past year has been the best of the Nottingham-based player''s career and he will surely - alongside Selby - be a among the favourites for the world title in the Spring. Selby started the evening session strongly with a break of 92, and took the next frame as well by clearing from the last red after Murphy had lost position. Selby''s 93 in the next saw him take the lead for the first time since 2-1. In frame 12, Selby missed the black off its spot at 53-6 and Murphy had a chance to clear, but wobbled a tricky final red in the jaws of a top corner. Selby came off a cushion to pot it and extended his lead to 7-5. Back came Murphy after the interval with a break of 80, helped by a fluked red mid-way through the break. In frame 14, Murphy missed a black on 33, but got another chance after Selby failed to gain position on the last red, and cleared to level at 7-7. Selby made an early 41 in the 15th frame and eventually sealed it with a cracking long pot on the last red. Another long red set up a break of 51 in the next, and when he added a further 18 points the title was his. "Coming here from China, I wasn''t expecting much," said Selby. "I always believe I can win, but with the fatigue I knew it would be difficult and I had to show a lot of character. Maybe that took pressure off me, but I was cursing myself because I knew if I lost I would only have myself to blame. It''s hard to believe I''m standing here having won the title. I have struggled this season so to win this by beating Shaun - who is the form player - is fantastic. "It was disappointing, up to now, not to perform at my best this season, having become World Champion, even though it was mainly top players I was losing to. So it''s nice to get the first ranking title under my belt and the performances this week were pleasing. "The clearance to go 5-3 was huge because at 6-2 I would have been dead and buried. Shaun had a couple of chances to win that frame and I held myself together to snatch it. When Shaun goes ahead he just keeps attacking. I played well tonight to go 7-5 up and then hung on in the end." Murphy said: "I knew today would be very close. Do I rue the missed red at 5-2? Perhaps a little bit, although there were eight other frames after that. I thought tonight Mark came out and played very well, like a World Champion. The match was a very high standard. I came into tonight feeling very good, but I got two kicks in the first two frames, otherwise the score could have been different. After that Mark was in control. The frame at 7-7 was big. I never had a chance to win the match. "I''m already making preparation for being in as good condition as I can for the World Championship, though I will try my best in every event before that. Everyone will have one eye on Sheffield now. I''m a far better played now than I was when I won it ten years ago - I was completely clueless then and went for every ball on the table. I still go for them, I''m just not as clueless now and I''ve got a few battle scars." Article courtesy of the World Snooker Images Courtesy of: Da Zhuang', '2014-01-01', false, 'Richard Pearson'),
  ('Selby Takes Riga Title', 'selby-takes-riga-title', 'Professional Snooker', '[]'::jsonb, 'World Champion Selby won his first title of the season and lifted the trophy at the campaign''s opening European Tour event as a trademark fight-back saw him overturn his opponent at the Riga Arena.', null, '"In the second and third frames I played a couple of poor safety shots and went 3-0 down. After that I found my game. Mark still had a couple of chances but luckily he didn''t take them and I managed to take mine."', 'World Champion Selby won his first title of the season and lifted the trophy at the campaign''s opening European Tour event as a trademark fight-back saw him overturn his opponent at the Riga Arena.

more Selby goes back to Leicester with a cheque for 25,000 Euros having shrugged off any early-season rustiness by winning seven matches, beating the likes of Peter Ebdon and Barry Hawkins. In the final, Northern Ireland''s Allen took the first frame with a break of 74 and the second with a superb 56 clearance, before adding a scrappy third for 3-0. But Selby hit back with breaks of 65, 100 and 62 for 3-3. In the decider, Allen, who won two European Tour events last season, had first chance and made 33 before missing a tricky red with the rest. Selby stepped in with a cool 63 and sealed victory after Allen failed to get the snooker he needed on the colours. "It has been a fantastic tournament all weekend and I''ve thoroughly enjoyed it," said Selby after snooker''s first ever professional event in Latvia, which was attended by thousands of enthusiastic fans. "It has been a great success. In Europe we always get good crowds and that''s what we play snooker for. "In the second and third frames I played a couple of poor safety shots and went 3-0 down. After that I found my game. Mark still had a couple of chances but luckily he didn''t take them and I managed to take mine." The 2014/15 European Tour series comprises six events across the continent, with the top 24 in the final Order or Merit to go through to the Players Championship next March to battle for the £100,000 jackpot. The next event is the Paul Hunter Classic in Germany from August 21 to 24. Article courtesy of the World Snooker Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Selby Wins Antwerp Thriller', 'selby-wins-antwerp-thriller', 'Professional Snooker', '[]'::jsonb, 'Mark Selby came from 3-1 down to beat Ronnie O''Sullivan 4-3 in a dramatic final at the Antwerp Open European Tour event in Belgium.', null, '"O''Sullivan said: "I never like losing but it is part of sport. There are a lot more tournaments coming up and I hope I''ll get a victory soon. I''m just enjoying being involved in big games and competing against top players."""', 'Mark Selby came from 3-1 down to beat Ronnie O''Sullivan 4-3 in a dramatic final at the Antwerp Open European Tour event in Belgium.

more A cool clearance in the deciding frame gave Selby his first title of the season and the 25,000 Euro top prize. The world number two from Leicester looks to be coming into form at the right time with the defence of his williamhill.com UK Championship title to start later this month. Watched by an enthusiastic crowd of 1,200 at the Lotto Arena, O''Sullivan won the opening frame with a break of 74. The second came down to the colours and Selby took it with a long pot on the blue. O''Sullivan regained the lead with a run of 54, then stole frame four with a fine clearance from the penultimate red to go 3-1 ahead. Selby dominated the next with 52 and 61, then made a superb 126 for 3-3. World Champion O''Sullivan had the first clear chance in the decider but surprisingly missed a black off its spot at 36-0. That proved his last shot as Selby''s 77 gave him the title. "Any time you play Ronnie you have to be on your game," said Selby. "From 3-1 down I played really well. I never give up but I didn''t expect to get another chance in the decider." O''Sullivan said: "I never like losing but it is part of sport. There are a lot more tournaments coming up and I hope I''ll get a victory soon. I''m just enjoying being involved in big games and competing against top players." The European Tour comprises eight events, with the top 24 on the final Order of Merit to qualify for the Grand Finals next March, to be joined by eight more players from the Asian Tour Order of Merit. The next event is the Gdynia Open in Poland from February 6 to 9. Article courtesy of the World Snooker Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Selby back on form with China Open victory', 'selby-back-on-form-with-china-open-victory', 'Professional Snooker', '[]'::jsonb, 'Mark Selby beat Barry Hawkins 11-3 in the final of the Fuhua Group China Open to win the title for a second consecutive year in Beijing.', null, '“In the early part of my career I got to a lot of ranking finals and lost. I doubted myself for a while. Since then it has been hard work, dedication and practice, I started winning them and gained more belief.', 'Mark Selby beat Barry Hawkins 11-3 in the final of the Fuhua Group China Open to win the title for a second consecutive year in Beijing.

more World number one Selby took the top prize of £225,000 – the biggest for any event other than the World Championship – by dominating the final against Hawkins. It’s a welcome return to form for Leicester’s 34-year-old Selby as he won the 14th ranking title of his career, moving him ahead of Ding Junhui and Neil Robertson into sixth place on his own on the all-time list. Selby has struggled for consistency this season; he won the International Championship in China in November but prior to this week he had reached the semi-finals of just one other ranking event this term. By winning the China Open for the third time, having lifted the trophy in 2015 and 2017, he gives himself a huge boost of confidence going into the Betfred World Championship, which starts on April 21. Selby heads to the Crucible aiming to capture the crown for the fourth time since 2014. He has now won 11 of his last 12 ranking finals, going back to the 2014 World Championship, and Selby re-asserts his grip on the world number one place, having seen his lead dented by Ronnie O’Sullivan in recent months. He has held top spot since February 2015 and is now sure to remain there well into next season. Hawkins missed the chance to win a fourth ranking title and has now lost two finals within five weeks having finished runner-up to John Higgins at the Welsh Open. The 38-year-old Londoner earns £90,000 and moves up two places to sixth in the rankings. The opening frame of the final went to Hawkins thanks to a break of 53, but Selby then took the next three with top runs of 65 and 53, before winning frame fives and six with crucial clearances to lead 5-1. Hawkins pulled one back with a break of 75 but his opponent stamped his authority on the match as runs of 90, 75 and 43 left Selby 8-2 up at the end of the first session. When they returned it was more of the same from Selby as breaks of 112 and 83 extended his lead to 10-2. Hawkins won frame 13 on the colours but Selby finished in style in the 14th with a 132 total clearance. “I played good matchplay snooker in the first session and capitalised on the balls that Barry missed,” said Selby. “Then I scored well in the second session. I have felt good all week, as if my game was coming back. It’s very satisfying to be able to go out there knowing my game is in good shape. Coming here I didn’t know what to expect, but it couldn’t have gone any better. “In the early part of my career I got to a lot of ranking finals and lost. I doubted myself for a while. Since then it has been hard work, dedication and practice, I started winning them and gained more belief. “The way I have performed in most of my matches here, playing well and scoring well, my confidence will be high going to Sheffield.” Hawkins said: “I’m very disappointed because I played so well yesterday in the semi-finals. I didn’t give Mark a game today, I made it so easy for him. I just kept missing easy balls and I don’t know why. I was confident going into the match, but as it went on that faded away. “Mark is so tough to play against. He’s happy to scrap it out, but then when he comes back to the table he finds his rhythm again. I struggle to do that, maybe that’s something I need to learn. He makes his opponents play badly and that’s a great weapon to have.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Selby conquers the Crucible again', 'selby-conquers-the-crucible-again', 'Professional Snooker', '[]'::jsonb, 'Mark Selby won his third Betfred World Championship crown since 2014 by beating John Higgins 18-15 in the final, becoming only the fourth player to successfully defend the title at the Crucible.', null, '“It is such a hard tournament to win physically and mentally. Snooker is one of the toughest sports in the world. There’s only four players that have ever defended it and you look at the greats who have played the game.', 'Mark Selby won his third Betfred World Championship crown since 2014 by beating John Higgins 18-15 in the final, becoming only the fourth player to successfully defend the title at the Crucible.

more Selby rubber-stamped his reputation as the best player of the current era as he came from 10-4 down to win 14 of the last 19 frames against four-time champion Higgins. Having lifted the trophy in 2014 and 2016, Leicester’s 33-year-old Selby follows Steve Davis (1983-4 and 1987-9), Stephen Hendry (1992-96) and Ronnie O’Sullivan (2012-13) as the only players to win back to back titles in the Crucible era, which began 1977. Scotland’s Higgins, at 41 the oldest world finalist in 35 years, dominated the early exchanges on Sunday and at 10-4 looked to be cruising to a fifth world crown, which would have equalled O’Sullivan’s tally. But, worn out by the effort of reaching the final at snooker’s toughest endurance test, Higgins faded through the key part of the battle. He made an impressive late rally but in the end was no match for his unflappable and determined opponent. The same two players met in 2007 when Higgins won 18-13, but in the decade since, Selby has matured immeasurably. Ice cool under pressure, tough as nails as a competitor, and superb in every department of the game, he is the successor to Davis and Higgins himself as the best all-round player in the sport. He has held the world number one position for 27 months – with his lead at the top of the rankings only increasing. With this win, Selby…

• Becomes the fifth player to win three world titles at the Crucible, after Hendry (7), Davis (6), O’Sullivan (5) and Higgins (4)
• Banks the biggest prize in snooker history, £375,000
• Smashes Hendry’s long-standing record of £740,000 for the most prize money earned in a single season. Selby has won £932,000 in 2016/17
• Equals the record of five ranking events won in a single season, set by Hendry and Ding Junhui
• Wins his 12th career ranking title, bringing him equal sixth on the all-time list alongside Neil Robertson and Ding
• Captures his eighth Triple Crown title having won three Masters and two UK Championships
• Becomes the sixth player to win the World and UK titles in the same season after Davis, Hendry, O’Sullivan, Higgins and Mark Williams
• Takes back to back ranking titles for the first time in his career and becomes the first player to win the China Open and World Championship consecutively

Leading 13-11 after the third session, Selby won the opening frame tonight with breaks of 35 and 37 to extend his lead. He might have taken the next as well from 45 points behind, but after making 14 went for a risky long pot on the final red to a baulk corner and missed his target, allowing Higgins to claw one back. Selby ignored that set-back and made a break of 71 to win frame 27, and he dominated the next as well, sealing it with a run of 70 to make it 16-12 at the interval. Higgins hit back with an 88 clearance to pull one back,and he gathered momentum with a brilliant 111 to make it 16-14. Frame 31 came down to a safety battle on the last red, and Higgins, leading 50-47, got the better of the exchange and made a fine clearance which included an excellent pot on the final brown. Embracing the pressure, Selby responded with a marvellous 131 to go two up with three to play at 17-15. There were no signs of nerves for Selby as he saw the finish line. He compiled 71, a break of steel inside the heat of Sheffield’s Crucible, to clinch the title. “It’s a fantastic feeling,” said a jubilant Selby. “I was confident coming here because of the season I’d had. I was just taking one frame at a time. When I was 10-4 down yesterday I thought there’s no way in the world I was going to come back from that, I was trying to make it respectable. At one stage I was thinking I could lose with a session to spare. “To get out 10-7, it felt like I was leading. I don’t know how I managed to win those three frames, because before that I was shattered. My game was all over the place, missing ball after ball, making it easy for John. The harder I was trying the worse it got. I managed to nick those three frames and that gave me confidence. I think John went to bed that night thinking he’d let one go. “It is such a hard tournament to win physically and mentally. Snooker is one of the toughest sports in the world. There’s only four players that have ever defended it and you look at the greats who have played the game. “I respect John as much as anyone in the game, he’s a great guy, a fantastic player, one of the all-time greats. He’s played as good as anyone this season.” Wishaw’s Higgins collected a runner-up prize of £160,000 and moves up to number two in the world. He was quick to pay tribute to Selby. “I think Mark will add to that, whether it’s one, two, three or four,” said Higgins, winning of 28 ranking titles. “He looks as though he could be the challenger to Stephen Hendry’s seven world titles. He’s just granite and really tough to play against, so I take my hat off to him. It’s up to the likes of Robertson, Trump and Ding to challenge him. They’ll be watching that tonight and it will make them desperate to get back on the practice table. “He was really strong today. He plays such a tough game, you’re off the table for so long, then when you get back to the table you’re out of your rhythm. He just keeps on punishing you and every credit to him, he’s a great champion. “I think I acquitted myself well this tournament. I enjoyed the way I played and how I kept myself under control. Even at the end I felt under control, a couple of little positional shots went awry and he punished me. I’m delighted to have got to the final. It’s just a pity I couldn’t go one better, but I’m proud of myself.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Selby crushes Ding in Daqing', 'selby-crushes-ding-in-daqing', 'Professional Snooker', '[]'::jsonb, 'Mark Selby won the International Championship for the first time by thrashing Ding Junhui 10-1 in the final in Daqing, China.', null, '“I’ve had a great start to the season and I’m really enjoying my snooker. Hopefully I can stay at the top of the rankings for as long as possible. There will be no time to celebrate this because I’ve got an early flight tomorrow to the China Championship in Guangzhou.', 'Mark Selby won the International Championship for the first time by thrashing Ding Junhui 10-1 in the final in Daqing, China.

more Selby dominated the contest, winning the last seven frames in a row, in the most one-sided ranking event final since the 2012 Haikou World Open when Mark Allen beat Stephen Lee 10-1. Leicester’s Selby made seven breaks over 50 while China’s Ding managed a top run of just 47. Selby collected a cheque for £125,000 after winning his third ranking title within six months, and ninth of his career, bringing him level with Peter Ebdon and John Parrott on the all-time list. The result also strengthens the 33-year-old’s grip on the world number one position which he has held for 20 consecutive months. The most consistent player in the world, Selby has now won 47 of his last 56 matches on the professional tour. Today’s match was a repeat of May’s World Championship final, which Selby won 18-14, and September’s Shanghai Masters final, when Ding gained a measure of revenge with a 10-6 success. This time, China’s top player was never in contention as his opponent controlled the contest. Runs of 87 and 83 put Selby 2-0 up and he cleared the colours in frame three to extend his lead. Ding pulled one back by clearing from green to black in frame four, but he scored just 58 points in the next five frames as Selby stormed 8-1 ahead with top breaks of 67, 66 and 50. And when they returned for the evening session there was no hint of a Ding fight-back, as Selby made a 62 clearance to win frame ten from 54-0 down, then sealed the result in the next with a run of 78. “Ding is a fantastic player but he didn’t really play his game today,” said Selby. “That was down to me playing some good match snooker and not giving him many chances. I didn’t miss anything easy and I was happy with the way stayed focused and I closed the match out. I’m really happy to get another ranking title under my belt. “I’ve had a great start to the season and I’m really enjoying my snooker. Hopefully I can stay at the top of the rankings for as long as possible. There will be no time to celebrate this because I’ve got an early flight tomorrow to the China Championship in Guangzhou. “The tournament here in Daqing is really well supported and the conditions are fantastic to play in. All of the players enjoy coming here.” Ding missed out on what would have been the 13th ranking title of his career, and had to settle for the runner-up prize of £65,000. He said: “I hoped to turn the match around but I wasn’t playing well. I wasn’t concentrating on the match today so the result didn’t bother me much.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Selby lands second world crown', 'selby-lands-second-world-crown', 'Professional Snooker', '[]'::jsonb, 'Mark Selby became the sixth player to lift snooker’s most famous trophy more than once at the Crucible by beating Ding Junhui 18-14 in the final of the Betfred World Championship.', null, '“Just before the last frame, someone I know in the crowd told me Spurs had drawn with Chelsea which meant Leicester were champions. That was the only time I knew, I tried to not to think about it, I didn’t want to distract myself from what I had to do".', 'Mark Selby became the sixth player to lift snooker’s most famous trophy more than once at the Crucible by beating Ding Junhui 18-14 in the final of the Betfred World Championship.

more A thrilling final saw Ding, the first Asian player to contest the final, make a late surge from 16-11 down to 16-14, only for Leicester’s Selby to win a tense 31st frame before sealing victory in the next. Selby, who first won the title in 2014 by beating Ronnie O’Sullivan by the same scoreline, joins Steve Davis, Stephen Hendry, Mark Williams, John Higgins and O’Sullivan as the only players to lift the trophy more than once at the Crucible. Overall he is the 13th multiple winner in the sport’s history. It was a remarkable night for Selby’s home city as Leicester secured football’s Premier League title just minutes before the last balls went down in Sheffield. Collecting a record cheque for £330,000, 32-year-old Selby retains his world number spot and has now been top dog in the rankings at the end of the season for the past five consecutive years. This is his seventh ranking title and sixth success in a Triple Crown event having won three Masters crowns and one UK Championship. Selby produced fluent snooker only in brief spells throughout the Championship, making nine centuries. His impregnable safety game and matchplay toughness, allied with a cool temperament, made him as hard to beat as ever. He produced his best performance of the fortnight in the final, when the pressure was at its most intense. In withdrawing from the two ranking events before the Championship for personal reasons, Selby arrived in Sheffield without having played a competitive match for over a month. But any rustiness was was soon shaken off and perhaps his extra freshness helped him go all the way to the title in a tournament which demands endurance. Ding, by contrast, had to go through three qualifying matches just to make it to the Crucible having dropped out of the top 16. He played the best snooker of the tournament, making 15 centuries, just one short of Stephen Hendry’s record for the most by one player. The 29-year-old lost the final in the early exchanges, going 6-0 down, and he could never get back on level terms. But having enjoyed his best run at the Crucible so far, the 11-time ranking event winner is bound to return next year feeling more confident of his chances, and less weighed down by the expectation of tens of millions of fans in his homeland. Ding’s £137,500 runner-up prize sees him jump eight places to ninth in the rankings. Selby led 14-11 going into the final session and made a break of 57 in the opening frame before missing a red to a centre pocket. But he got another chance and added 46 to stretch his lead. In the crucial 27th frame, Ding made 60 before running out of position with two reds left, leading by 29 points. Selby played a clever cross double on the red to set up a 36 clearance which included an excellent thin cut on the final black with the long rest. Ding kept battling and took the next three frames without conceding a point, compiling runs of 73, 70 and 103 to close to 16-14. The third of those breaks was the 86th century of the tournament, equalling the record. Frame 31 lasted 51 minutes and was controlled by Selby, who built a 51-11 lead before potting the third-last red to go three up with four to play. And he needed just one chance in the next as a run of 74 secured the crown. “It’s a great feeling,” said Selby. “To win it once was a huge achievement, and something that I wanted to do, but I never dreamed of winning twice, I’m quite emotional. “The first time is always special, especially at the World Championship, the same when you win your first ranking tournament. And when you look at the people to have won it twice, to join that elite group is amazing. “I feel shattered. Last night I was so tired, to come out of that 10-7 up was huge because it was the first time I’d been ahead after the first day of the final. “Ding was under a lot of pressure, it was his first world final and there’s massive expectation from China. I knew I had to capitalise early doors, every time I got a chance I punished him and scored. I missed a blue to go 7-0 up and if I had done that I might have won more easily. Ding showed class and came back to within a frame at times, but I managed to dig deep. “For a lot of this tournament my game has been average, whereas Ding has played great, the only bad session he had was in the first session in the final. I was second favourite, but here I am sitting here as world champion. I think it was just grit and determination, I never give in, no matter how badly I’m playing. Until that final ball is potted I still keep believing inside that I can win.” Selby admitted that during the final session he tried to keep away from news of the football score in order to retain his focus. “Just before the last frame, someone I know in the crowd told me Spurs had drawn with Chelsea which meant Leicester were champions. That was the only time I knew, I tried to not to think about it, I didn’t want to distract myself from what I had to do. “I don’t know what is more of a shock, me winning the world title twice or Leicester becoming Premier League champions!” Ding said: “I played well in the last session. The start was very bad, I went 6-0 down and I was too far away from Mark. He played good safety and he knows how to win frames. The match got harder but I enjoyed it more towards the end. “Five years ago I got to the semi-finals and now this year I have gone one step further. Maybe next time I’m going to win this. It’s good experience for my career, I’m enjoyed the final and not many players have got to the final here. “This season I have been working with Terry Griffiths for the first time and I think I have improved. If I keep playing like this I can win more tournaments.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Selby rules UK again', 'selby-rules-uk-again', 'Professional Snooker', '[]'::jsonb, 'Mark Selby won his second Betway UK Championship title with a 10-7 victory over Ronnie O’Sullivan in a classic final in York.', null, 'Reflecting on his achievements in the sport, Selby added: “All of the records are special really, to win all of the three majors is a great feeling, but to do it twice is even better. Now even if I didn’t win another tournament I would be happy with my achievements so I have to set my goals a little differently and to win the UK again was definitely one of them.”', 'Mark Selby won his second Betway UK Championship title with a 10-7 victory over Ronnie O’Sullivan in a classic final in York.

more The world number one becomes only the sixth player to win the World and UK Championship tournaments in the same calendar year and scoops the top prize of £170,000 to consolidate his already dominant position at the top of the world ranking list. Victory in York represents Selby’s third ranking event success of the season and fourth in 2016, following the World Championship, Paul Hunter Classic and International Championship titles. He moves level with Jimmy White on ten career ranking titles. Leicester’s 33-year Selby is also the sixth player to win all three Triple Crown events on multiple occasions, after O’Sullivan, Stephen Hendry, John Higgins, Steve Davis and Mark Williams. Defeat for O’Sullivan brought his previously unbeaten record in UK Championship finals to an end, but during the second session of the match he demonstrated his famed ability and fighting qualities to push Selby all the way. The Rocket trailed 6-2 after the opening session and following a break of 56 from Selby to start the evening session, looked to be facing a mountain to climb at 7-2. O’Sullivan, however, snapped his six-frame losing streak with breaks of 56 and 80 in frame ten, before adding the next following a missed pink from Selby. From 7-4 the match caught fire, a total clearance of 134 from O’Sullivan – his 850th career century break – followed by an equally brilliant total clearance of 137 from Selby either side of the interval. Back came O’Sullivan again with another big break of 130, before he added a run of 82 to close to just one behind at 8-7 as it looked as though the match might go all the way. Selby had other ideas though and would ultimately close out the match with back-to-back century breaks of 134 and 107 to secure the title. “It feels amazing,” said Selby. “Just to win the UK is a great feeling anyway, but as I said when I won the world for the first time, if I was to go on and win a big tournament I’d like to play Ronnie in the final and to go on and win. I have done that in the Masters, World and the UK so that is a fantastic feeling. “This afternoon I played ok in patches and played quite solid. Ronnie missed a few and wasn’t really on his game, but tonight he put me under pressure, asked the questions and I was really pleased with myself with how I held up in the end. “At the interval to go 7-5, I was thinking to myself that if I am playing anybody else you don’t panic because they don’t do it as quick as Ronnie. But because he is so quick, before you know it he is within two frames and your head is spinning a little bit. But I just tried to stay in the moment, remember that I was still in the lead and just take one frame at a time.” Reflecting on his achievements in the sport, Selby added: “All of the records are special really, to win all of the three majors is a great feeling, but to do it twice is even better. Now even if I didn’t win another tournament I would be happy with my achievements so I have to set my goals a little differently and to win the UK again was definitely one of them.” O’Sullivan was disappointed with defeat, however was pleased with his own attitude and how he approached the final: “I think that the fans here enjoyed it and the people watching at home would have enjoyed it,” said O’Sullivan, who remains stuck on 28 ranking titles and five UK crowns. “Mark has done well to win so congratulations to him. “I was pleased with my attitude. I was pleased that when I came to the table I just played the shot and didn’t get bogged down looking around too much, which can happen when you are playing long frames. I enjoyed my game, but I just missed too many easy balls to win tournaments, that’s probably why I haven’t won anything this season. I missed some pretty easy ones all day.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Selby wins back to back in Daqing', 'selby-wins-back-to-back-in-daqing', 'Professional Snooker', '[]'::jsonb, 'Mark Selby won his first title of the season by beating Mark Allen 10-7 in the final of the OPPO International Championship in Daqing, China.', null, '“Mark never knows when he’s beaten and he has a lot of bottle. It didn’t surprise me when he came back at me. I just had to stay calm and wait for my chance. To defend a big title like this is a great feeling. As long as I keep winning tournaments I can be world number one for a lot longer. The events come thick and fast over the next few weeks and as I’m playing well I prefer that.”', 'Mark Selby won his first title of the season by beating Mark Allen 10-7 in the final of the OPPO International Championship in Daqing, China.

more World number one Selby won the prestigious title for the second consecutive year having beaten Ding Junhui 10-1 in the 2016 final. This time the Leicester cueman was pushed much harder – especially when Allen came from 8-3 down to 9-7 – but Selby eventually got over the winning line to secure the £150,000 top prize. It’s the 13th ranking title of his career, bringing him level with Ding, joint-sixth on the all-time list. Selby made a slow start to the current season, suffering a toe injury in June which caused him to miss the early stages of the campaign, and then failing to go beyond the quarter-finals of the next five ranking events. But – as he does so often – he has risen to the occasion in one of the biggest tournaments on the calendar this week and will go home with the trophy. It’s Selby’s sixth ranking title in the last 16 months, a golden spell which has also seen him win his third World Championship and second UK Championship crowns. The 34-year-old is now nearly £800,000 ahead of Ding at the top of the world rankings, while Allen’s £75,000 runner-up prize sees him jump from 11th to sixth. Northern Irishman Allen missed the chance to win his fourth ranking title, but it’s still a welcome return to form for the 31-year-old from Antrim, who had not previously reached a ranking final since winning the Players Championship 20 months ago. Selby won the opening frame with a break of 67 then Allen levelled with a 110. Runs of 50 and 61 helped put Selby 3-1 up, before Allen pulled one back with a 98. Selby then took control by winning three frames in a row with top breaks of 55, 60 and 61. Allen won the last frame of the opening session with a superb 137 to keep himself in touch at 6-3. The early exchanges of the evening session went Selby’s way as he won two frames without his opponent scoring a point, making it 8-3. Frame 12 could have gone either way but Allen took it with a yellow-to-pink clearance, and he went on to make 78 in the next to close to 8-5 at the interval. Selby’s run of 90 put him four up with five to play and he had chances to seal victory in frame 15, but couldn’t take one and his opponent won it on the colours. Allen got the better of a scrappy 16th as well to close to 9-7. But Selby took control of frame 17 with a run of 49 and later got back in to add 19 points to clinch the title. “The standard of the final was very good,” said Selby. “I knew it would be tough. We both played at the top of our game and I’m happy to be on the winning side. “Mark never knows when he’s beaten and he has a lot of bottle. It didn’t surprise me when he came back at me. I just had to stay calm and wait for my chance. To defend a big title like this is a great feeling. As long as I keep winning tournaments I can be world number one for a lot longer. The events come thick and fast over the next few weeks and as I’m playing well I prefer that.” Allen said: “I never gave up, even at 8-3 down. At 9-7 I felt I was back in the match. But I was always hanging on to his coat tails, I missed too many chances and played too many careless safeties, and you can’t do that against the best player in the world. Overall I’m disappointed with the way I played. “Mark is a so good in every department, he’s a great role-model for our sport and someone we all look up to. He’s just a bit better than everyone else. He’s definitely in the top five players of all-time now, along with Stephen Hendry, Ronnie O’Sullivan, John Higgins and Steve Davis. I need to go away and work hard and try to get better.” The result means that Neil Robertson earns the 16th and final spot in the 188BET Champion of Champions which starts on Monday. Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Selby''s greatest triumph', 'selbys-greatest-triumph', 'Professional Snooker', '[]'::jsonb, 'Mark Selby wakes up today as the new UK champion - the greatest triumph of his career so far.', null, '"Sport has never been about making friends. The huge piece of silverware Selby can put in his trohpy cabinet is all that matters. ".', 'Mark Selby wakes up today as the new UK champion - the greatest triumph of his career so far.

more The world number one beat his close friend Shaun Murphy 10-6 in a gripping final that went on beyond midnight in York. Question the quality if you will but this was still a fantastic final. Anxiety and pressure was at the heart of the drama as there were plenty of twists and turns, but Selby was a worthy winner. Murphy showed again he is a great potter but, in the end, Selby had too much nous in his toolkit to be denied the trophy, as he won eight of the final 10 frames. This was a massive win for Selby. It has been a difficult year for him with a nasty neck injury threatening his future in the game. But being the tough player he is, he has come back fighting. Before this week Selby was already a two-time winner of the Masters but victory in either of two biggest events, the World and UK Championships, was long overdue. Selby is often unfairly criticised for his style of play because people don''t understand what an excellent match player he is. He can play fluid snooker along with the best of them. In fact, for each of the past two seasons in succession he has scored more centuries than anyone. Above this, he''s also a born winner. He''s not afraid to dig his heels in and fight his way to victory and this fine win will go a long way to proving some of the doubters wrong. Sport has never been about making friends. The huge piece of silverware Selby can put in his trohpy cabinet is all that matters. Shaun was unsurprisingly gracious in defeat because he knows how much Selby deserves this. He is one of the most hardworking and hard to beat players on the circuit. Christmas celebrations will be enjoyed this year in the Selby household. He pocketed the £125,000 top prize at the Barbican and ends a trying year reborn. He is back on top of the world rankings, the UK Championship winner, free from injury and back believing in himself again. Article courtesy of the OneCue Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Senior success for Davis', 'senior-success-for-davis', 'Professional Snooker', '[]'::jsonb, 'Mark Davis won the 888sport World Seniors Championship for the first time by beating Darren Morgan 2-1 in the final in Preston.', null, null, 'Mark Davis won the 888sport World Seniors Championship for the first time by beating Darren Morgan 2-1 in the final in Preston.

more World number 23 Davis won four matches at the Guild Hall to claim the £18,000 first prize. Davis clinched the opening frame of the final with a break of 35 before Morgan, who won this title in 2011, made a 55 in the second as he levelled at 1-1. But it was Davis, age 43 from Hastings, who took the decider with a run of 76. His previous career highlights include winning the Six-Red World Championship in 2012 and 2013 as well as the B&H Championship in 2003. In the semi-finals, Davis edged out Rory McLeod 2-1 while Welshman Morgan beat Jimmy White 2-0. Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Six matches finish 3-2 in first week', 'six-matches-finish-3-2-in-first-week', 'Match Reports', '[]'::jsonb, 'The first week of the new St Blazey and District Snooker League saw six matches finish 3-2 in what promises to be an exciting season.', null, '"Pete Chambers made a successful return to the league after many years away as he saw off Barry McIntosh with the help of a 31 break as Mevagissey ‘A’ beat Tregonissey ‘A’ by the odd frame, Matty Mills and Chris Kendall also on target for the Seasiders."', 'The first week of the new St Blazey and District Snooker League saw six matches finish 3-2 in what promises to be an exciting season.

more New play-off games have been introduced for the new campaign, which will be held at the end of the season. Newcomers to the Victory League Bethel ‘C’ deserved a better result than losing to their ‘A’ side 4-1. Roger Smithson carried on his fine form from last season seeing off Leon Collard but Allen, Stephens, Green and Hawken took their team to the top of the table – at this early stage of the season. Defending champions Bugle ‘A’ edged out last season’s runners-up St Blazey ‘B’ by the odd frame with three breaks of the night from Andrew Best who had a great 68, Paul Barron with 54 and Paul Sturtridge a 31 as Bugle made a solid start to their campaign. Pete Chambers made a successful return to the league after many years away as he saw off Barry McIntosh with the help of a 31 break as Mevagissey ‘A’ beat Tregonissey ‘A’ by the odd frame, Matty Mills and Chris Kendall also on target for the Seasiders. St Blazey ‘A’ gained a good 3-2 home win over Bugle ‘B’ with Stewart Dewing, Nick Kendall and Matt Woodward successful with Jake Moore and Dave Rundle replying. Gorran Haven sit proudly at the top of the Rees League after whitewashing newcomers St Stephen ‘B’ 5-0 and will be looking to improve greatly on last year’s eighth place. The league’s other newcomers Tregonissey ‘B’ picked up a fantastic 3-2 home win over much-fancied Mevagissey ‘C’ with Ryan Thomas, Chris Robins and Jake Hooley their winners with Joe Chesterfield and Charlie Prynn responding for the visitors. The Bethel derby went the way of the ‘D’ side who are looking to bounce right back to the top league this season. Steve Benallack, Jason Pascoe and Andy Spearman were on target with Guy Buckle and Dave Morshead who beat Ryan Tonkin victorious for the ‘B’ side. Finally Bugle ‘C’ picked up two good points at St Stephen ‘A’ to make a positive start after being wooden spoonists last year. The Mevagissey ‘D’ and Lerryn game was postponed due to ill health and will be re-arranged shortly.

FULL RESULTS

Victory League: St Blazey ‘A’ 3 (S Dewings, N Kendall, M Woodward) Bugle ‘B’ 2 (J Moore, D Rundle), Mevagissey ‘A’ 3 (C Kendall, M Mills, P Chambers (31)) Tregonissey ‘A’ 2 (M Knight, R Bilson), Bethel ‘C’ 1 (R Smithson) Bethel ‘A’ 4 (S Allen, M Green, G Stephens, G Hawken), Bugle ‘A’ 3 (A Best (68), G Spencer, P Sturtridge (31)) St Blazey ‘B’ 2 (D Kirwan, P Baron (54). Rees Memorial League: St Stephen ‘A’ 3 (A Harrison, A Garside, J Bennett) Bugle ‘C’ 2 (K Spencer, K Moore), Bethel ‘B’ 2 (G Buckle, D Morshead) Bethel ‘D’ 3 (S Benallack, J Pascoe, A Spearman), Gorran Haven 5 (A Reddall, P Grimmett, R Holmes, R Bunney, L McKinstry) St Stephen ‘B’ 0, Tregonissey ‘B’ 3 (J Hooley, C Robins, R Thomas) Mevagissey ‘C’ 2 (J Chesterfield, C Prynn). Top breaks of the week: A Best 68, P Baron 54, P Chambers 31, P Sturtridge 31. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Snooker League AGM - Tuesday 9th July @ 7:30pm', 'snooker-league-agm-tuesday-9th-july-730pm', 'League Meetings', '[]'::jsonb, 'Dear All, Can I give you all notice that the Snooker League AGM for the coming season is to be held at Tywardreath RBL on Tuesday 9th July at 19:30. more I will circulate a full agenda by the end of this weekend to…', null, null, 'Dear All, Can I give you all notice that the Snooker League AGM for the coming season is to be held at Tywardreath RBL on Tuesday 9th July at 19:30. more I will circulate a full agenda by the end of this weekend to give you a better idea of what is to be discussed. For the purposes of adding to that agenda, can I ask that anything pressing from last season that you wish to be discussed on the night, be forwarded to me by Sunday 30th June. Anything received after that date will not be eligible for discussion at this years meeting. A representative from ALL teams should attend In order to register their team for the coming season. 2014 fees will be circulated at the same time as the agenda. For those of you aware of anyone that may be interested in joining the league, please spread the word and invite them to attend. More details to follow.', '2014-01-01', false, 'Richard Pearson'),
  ('Some shocks in the Team Handicap competition', 'some-shocks-in-the-team-handicap-competition', 'Competitions', '[]'::jsonb, 'The team handicap competition bought about some shock results and several near upsets.', null, 'Pelynt picked up a great victory at Tregonissey ‘A’. Great wins for Andy Parnell (Martin Knight), Phil Ormand’s black-ball win over Matt Woodward and Len Flower, despite Ryan Bilson’s 47 break, got them over the line.', 'The team handicap competition bought about some shock results and several near upsets.

more It all started on Monday night as Bethel ‘A’ luckily got past a luckless Lerryn, who could only muster four players on the night. Charles McMiram pushed Matt Green all the way but a in-off on the brown gave Matt the chance to cease victory then Terry Middleton was only defeated by an excellent pink and black clearance by Gary Stephens. Sadly a walkover on frame three saw Bethel through. Mevagissey ‘A’ were pushed all the way by Tregonissey ‘B’ but prevailed 3-1. Mike Hooley hammered Matt Mills in the first frame but Meva levelled with Leighton Varcoe’s black-ball victory over Justin Hooley and James Popperwell also winning on the black against Richard Opie, despite his opponent having a 40 break and Phil Staley produced a captain’s performance to see off Phil Hooley. The win seeing Meva through to play St Stephen ‘B’ next. Mevagissey ‘B’ got off to a great start at St Neot as Predator Tregale beat Antony Maddams. Chris Perring and Ben Rothwell were locked at 34 a piece in the second only for Chris to produce a fine 33 clearance to level things. Dave Kendall put up a great fight only to lose to Darren Lock on the black after Lock had knocked in a 34 and St Neot got over the line with Steve Court’s victory over Nathan Shaw. St Blazey ‘A’ made short work of Bethel ‘C’. Graham Taylor’s win over Ben Stunnell got them up and running with Mark Craddock’s black-ball win over Howard Brett pivotal on the night. Stewart Dewings completed the rout by beating Courtney Crockford whilst on the other table Mevagissey ‘D’ made light work of Bethel ‘D’ again winning 3-0 with a lot to spare. Ian Latham, Rob Blamey and Scott Mills got them home. Bugle ‘B’ dumped their ‘A’ team out of the competition with a 3-2 win. Colin Rundle, Tony Conroy and Dave Rundle were their marksmen. Pelynt picked up a great victory at Tregonissey ‘A’. Great wins for Andy Parnell (Martin Knight), Phil Ormand’s black-ball win over Matt Woodward and Len Flower, despite Ryan Bilson’s 47 break, got them over the line. Bethel ‘B’ won 3-1 at St Stephen ‘A’ with Clive Stuthridge, Jim Tamblyn and Martin Isted on target to set up a trip to Pelynt next. In two re-arranged games Bugle ‘A’ climbed to equal second with a close 4-1 victory over St Neot. Darren Lock hit a 43 in his win over Andrew Best but Ian Ball’s black ball win, Paul Sturtridge respot win and Jake Moore’s pink ball victory along with Gary Spencer, who made a 36 break saw them home. Also in the Rees League Mevagissey ‘D’ moved up the table after defeating St Stephen ‘B’ 4-1. Rob Garside defeated Neil Parker to get the away side off to a good start but comfortable wins for Rob Blamey, George Lory, Ian Latham and Rich Lakeman saw the Seasiders home.

FULL RESULTS

The draws for the next round of the team competition have been made and are as follows. Team handicap to be played on Tuesday, November 29. Draw made by Ian Ball (Bugle) and John Bennett (St Stephen). St Blazey ‘A’ v Mevagissey ‘A’ or St Stephen ‘B’, Mevagissey ‘D’ v Bugle ‘B’, Pelynt v Bethel ‘B’, St Neot v Bethel ‘A’. Team Paris to be played on Tuesday, October 8. Draw made by Nick Kendall (St Blazey) and Rob Blamey (Mevagissey). Mevagissey ‘A’ v Bethel ‘A’, Bethel ‘C’ or St Neot v Bugle ‘A’, Bugle ‘B’ v Pelynt, Tregonissey ‘A’ or St Blazey ‘A’ v St Stephen ‘A’. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Spaceman Into Orbit With Shoot-Out Triumph', 'spaceman-into-orbit-with-shoot-out-triumph', 'Professional Snooker', '[]'::jsonb, 'Dominic Dale won the 888casino Shoot-Out in Blackpool, snooker''s quick-fire one-frame knockout event, beating Stuart Bingham in the final.', null, '""I have practised harder in the last three or four years than I had done in my whole career. We have so many tournaments now and that gives me motivation to do well. I''ve won a big cheque today and that will keep me going for a while."', 'Dominic Dale won the 888casino Shoot-Out in Blackpool, snooker''s quick-fire one-frame knockout event, beating Stuart Bingham in the final.

more Colourful character Dale, nicknamed the Spaceman, won six matches to take the £32,000 top prize, the third biggest pay-day of his 22-year career. Cheered on by an enthusiastic crowd, 42-year-old Dale rose to the challenge of the exhilarating tournament, deadly potting and quick thinking his key attributes. The Welshman, sporting a peroxide blonde hair-cut, knocked out Fergal O''Brien, Barry Hawkins, Mark Allen, Andrew Higginson and Ryan Day to reach the final before getting the better of Basilson''s Bingham. A superb break of 61 put Dale in control, though he missed a red to a centre pocket to gift Bingham a chance. But having made just 15, the Essex cueman missed an easy pink, allowing Dale to wrap up victory by a 77-19 scoreline. "In the last few years at this event I have been a nervous wreck, I found it hard to strike the cue ball," admitted Dale, who has won two world ranking events, the 1997 Grand Prix and 2007 Shanghai Masters. "But this time I felt very calm and I potted a lot of good pressure balls. "The crowd adored me because I''m an extrovert and I relish this type of occasion. It''s wonderful to be popular and I wanted to win it for them. It''s a fantastic venue and a one-off tournament so to win a prestigious trophy at the age of 42 is very special. "I have practised harder in the last three or four years than I had done in my whole career. We have so many tournaments now and that gives me motivation to do well. I''ve won a big cheque today and that will keep me going for a while." Dale, who sang a few lines of ''My Way'' after collecting the trophy in the arena, plans to keep his hair blonde for the time being. "It must be lucky so I won''t change it until I have a bad run!" he joked. The tournament, first staged in 2011, featured frames lasting a maximum of ten minutes, with a 15 second shot clock for the first five minutes and 10 seconds for the last five. Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Spencer seals the win in the shoot-out', 'spencer-seals-the-win-in-the-shoot-out', 'Competitions', '[]'::jsonb, 'The St Blazey and District Snooker League’s first snooker shoot-out was played at Mevagissey Social Club at the start of the month.', null, 'Meva ‘B’ have the bragging rights after beating the ‘A’ team 3-2, Mark Gregory and Dave Kendall put them two up but Paul Williams and James Popplewell levelled things up only for Ben Rothwell to hammer Phil Staley in the decider.', 'The St Blazey and District Snooker League’s first snooker shoot-out was played at Mevagissey Social Club at the start of the month.

more Superbly arranged by Matt, Leighton and the rest of the team 26 players entered. Games of 15 minutes maximum took place on both tables until the quarter-final line-up was completed. For each of the remaining frames the players were introduced to the crowd as they entered the arena with the Chelsea Dagger blazing out from the sound system and noisy applause from all watching. The first semi-final saw Matt Mills come from behind to defeat Mark Ashton who was fancied by many to win the event with Gary Spencer beating local hero Phil Staley in the other semi-final. The final itself was a close affair with Gary going 25 points up only for Matt to pick away at the deficit and eventually took the lead but with the less than two minutes remaining he did the dreaded in-off giving Gary the ball in hand with the yellow over the pocket and his potting and good use of the ever-decreasing clock saw him home. A great event which is sure to be repeated. During the interval an excellent raffle was drawn with many local traders donating great prizes gratefully received the highlight for many was James Popplewell winning a haircut – a prize originally turned down by Matt Green. Defending champions Tregonissey ‘A’ had to come back from 2-0 down at Bugle ‘A’ after Jake Moore and Andrew Best who knocked in a 46 break put the home side in a good place but wins for Barrie McIntosh (34 break), Martin Knight despite Paul Sturtridge’s 30 break and Jason Simmons saw Treggy home. Last year’s strugglers Bugle ‘B’ are joint top after whitewashing Tregonissey ‘B’ 5-0. There were a couple of close frames but they also went the way of the away side. Meva ‘B’ have the bragging rights after beating the ‘A’ team 3-2, Mark Gregory and Dave Kendall put them two up but Paul Williams and James Popplewell levelled things up only for Ben Rothwell to hammer Phil Staley in the decider. St Blazey found themselves three down at home to St Neot as Darren Lock, Andrew Pearce and Cyril Dickenson picked up good points for the visitors. The home side responded with wins for Liam Reynolds and Chris Morford, who is back playing after a nine-year break. Rob Blamey and Mark Ashton got Meva ‘D’ two good points at Pelynt with Phil Ormond, Andy Parnell and John Daniell replying. Answeres on a postcard please as to who is going to win the Rees League this year as the first three weeks have been so unpredictable. Bethel ‘D’ got their first win against their ‘C’ team as Gavin and Dayle Dyche along with Ross McMenemy and Jason Pascoe recorded win, with Howard Brett replying. Lostwithiel had a cracking win at Bethel ‘B’ with Josh Doherty and Terry and Craig Nicholls winning with Clive Stuthridge and Richie Bolt replying. Gorran picked up four good points at home to Lerryn with wins for Lee McKinstry, Rob Bunney, Paul Grimmett and Matt Fox on a rare appearance. Graham Hoskin beat Andy Reddall in the last frame to get Lerryn’s point. Robert and Anthony Garside got St Stephen’s points at Mevagissey ‘C’, who claimed the win through Ben Prynn, ‘The Predator’ Tregale and Joe Chesterfield. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('St Blazey & District Snooker League Presentation & Dance', 'st-blazey-district-snooker-league-presentation-dance', 'League News', '[]'::jsonb, 'St Blazey & District Snooker League is proud to announce it''s Presentation evening & Dance...', null, '"The committee is extremely excited and proud about holding this years presentation evening at Mevagissey Social Club, throughout the years they have been great ambassadors for the league and fully deserve this recognition"', 'St Blazey & District Snooker League is proud to announce it''s Presentation evening & Dance...

more Full details are as follows: St Blazey & District Snooker League Presents it''s annual Presentation & Dance 20.04.13 at Mevagissey Social Club A special night featuring live music from Citizen Smith Evening also includes Trophies, Buffet, Music & Raffle Plus the chance to win 2 VIP tickets to a Snooker Legends event in Plymouth with our new ''Where''s the Cue Ball'' competition Doors open at 7pm for a strict 7:30 start, due to a tight schedule £10 entry & cheap drinks until midnight Tickets available from behind the bar or direct from the venue by calling Paul on 01726 842441 Limited free parking available at the firestation Mevagissey Social Club has been given the green light to host both the Gordon Boynton trophy on Saturday 6th April followed by the Presentation & Dance on Saturday 20th April. Doors will open at 7pm for a 7:30 pm start and tickets will go on sale shortly. This year we wanted to do something a little different and have decided not to have an exhibition evening, we want you all to let your hair down and have some fun:-). Please spread the word and we hope to see as many of you as possible, any family members are also warmly invited, the more the merrier. The committee is also extremely excited and proud about holding this years presentation evening at Mevagissey Social Club, throughout the years they have been great ambassadors for the league and fully deserve this recognition. Arrangements for parking for both events will be announced shortly as will the entertainment, ticket prices, food and potential guest houses if you wish to stay. Further details to follow.', '2014-01-01', false, 'Richard Pearson'),
  ('St Blazey & District Snooker League Presentation & Dance 2014', 'st-blazey-district-snooker-league-presentation-dance-2014', 'League News', '[]'::jsonb, 'St Blazey & District Snooker League is proud to announce it''s Presentation evening & Dance...', null, null, 'St Blazey & District Snooker League is proud to announce it''s Presentation evening & Dance...

more Presentation night is the 12th April at Bethel Social Club, it will include a buffet and entertainment, this year we aim to topple last years phenomenal success and make this an amazing night to remember. With some awesome live music and a raffle prize that''s out of this world it''s an evening no-one will want to miss. More details to follow in the following few weeks, stay tuned St Blazey potters...', '2014-01-01', false, 'Richard Pearson'),
  ('St Blazey Snooker goes to the Masters at Ally Pally', 'st-blazey-snooker-goes-to-the-masters-at-ally-pally', 'League News', '[]'::jsonb, 'The Betfair Masters starts at Alexandra Palace on Sunday with the best players in the world battling for the 175,000 pound top prize.', null, '"The stars of the green baize including Judd Trump, John Higgins, Mark Selby, Ding Junhui and defending champion Neil Robertson will be at the London venue from January 13-20"', 'The Betfair Masters starts at Alexandra Palace on Sunday with the best players in the world battling for the 175,000 pound top prize.

more St Blazey Snooker have been lucky enough to be invited to the final Saturday (Semi Final day) where we will get as many Professional CueViews, Interviews and Photos as possible, stayed tuned for a full report and photo gallery after the event has finished. And if you fancy any tickets the details are below for your perusal. Click here for the draw and here for the match schedule The stars of the green baize including Judd Trump, John Higgins, Mark Selby, Ding Junhui and defending champion Neil Robertson will be at the London venue from January 13-20. It''s snooker''s most prestigious invitation event with a top prize of £175,000 up for grabs. TICKETS ARE ON SALE NOW and are a fantastic present for anyone who enjoys snooker. Call 0871 620 7052 (calls cost 10p per minute plus network extras) or CLICK HERE There are also some superb VIP packages available - for details click here', '2014-01-01', false, 'Richard Pearson'),
  ('St Blazey blow chance to keep up with Bugle boys', 'st-blazey-blow-chance-to-keep-up-with-bugle-boys', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ have moved clear at the top of the St Blazey and District Snooker League Victory League thanks to a 4-1 win away at Mevagissey ‘A’.', null, '"Bethel ‘A’ picked up a good 3-2 away win at Bugle ‘B’, Dave Rundle and Ian Ball, who had a good 43-break featured for the home side but Neil Rowe’s black-ball final frame win over Arsene Moore saw the victory go back to St Austell."', 'Bugle ‘A’ have moved clear at the top of the St Blazey and District Snooker League Victory League thanks to a 4-1 win away at Mevagissey ‘A’.

more Leighton Varcoe saw off Andrew Best for Meva’s point, with a 41-break by Andrew Peers the highlight of the evening. St Blazey ‘B’ slipped up for a second week in succession as they suffered a 3-2 home loss to Tregonissey. Mike Hancock produced a 36 and 34 clearance breaks but veteran Mike Fox, Chris Stephenson and Barry McIntosh brought back the bacon for Treggy. Bethel ‘A’ picked up a good 3-2 away win at Bugle ‘B’, Dave Rundle and Ian Ball, who had a good 43-break featured for the home side but Neil Rowe’s black-ball final frame win over Arsene Moore saw the victory go back to St Austell. St Blazey ‘A’ keep up their good form coming away from Lostwithiel ‘A’ with a 3-2 win – Chris Perring and the prolific Darren Lock capturing the home points. Lostwithiel ‘B’ made a great start at St Neot with Bryan Warne giving them an early lead. It was nip and tuck all night but home captain Steve Courts compiled a studious 38-break to seal the win. Mevagissey ‘B’ made a huge move towards the Rees League title by thrashing previously joint-leaders Bethel ‘C’ 4-1 – only Howard Brett got going for the home side but Phil Staley, Matt Rowe, Dave Kendall and Ben Rothwell made sure of the victory for the now title favourites. Graham Hoskin and Terry Middleton claimed Lerryn’s points in a 3-2 home loss to Bethel ‘C’ Jim Tamblyn winning the deciding frame for the Bethel boys. St Stephen consolidated fourth place after overcoming Mevagissey ‘D’ 3-2 – Rob Blamey and James Tomlinson gave Meva hope but John Bennetts’ victory over Richard Lakeman proved pivotal on the night. Bugle ‘C’ made the trip to Gorran Haven but due to a power cut were unable to play and hope to fulfil the fixture this week.

FULL RESULTS

Victory League: Bugle ‘B’ 2 (D Rundle, I Ball (43)) Bethel ‘A’ 3 (G Hawken, G Stephens, N Rowe), Mevagissey ‘A’ 1 (L Varcoe) Bugle ‘A’ 4 (P Sturtridge, G Spencer, I Powell, A Peers (41)), St Neot 3 (A Courts, I Wilton, S Courts (38) Lostwithiel ‘B’ 2 (B Warne, J Hill), Lostwithiel ‘A’ 2 (C Perring, D Lock) St Blazey ‘A’ 3 (C Brown, M Woodward, S Dewings), St Blazey ‘B’ 2 (M Hancock (36 and 34 clearance), G Taylor) Tregonissey 3 (M Fox, C Stephenson, B McIntosh). Rees Memorial League: St Stephen 3 (A Harrison, J Bennett, C Clark) Mevagissey ‘D’ 2 (R Blamey, J Tomlinson), Bethel ‘C’ 1 (H Brett) Mevagissey ‘B’ 4 (P Staley, M Rowe, D Kendall, B Rothwell), Lerryn 2 (G Hoskin, T Middleton) Bethel ‘B’ 3 (S Hicks, G Buckle, J Tamblyn). Top breaks of the week: I Ball 43, A Peers 41, S Courts 38 M Hancock 36, 34 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('St Blazey cause cup upset', 'st-blazey-cause-cup-upset', 'Match Reports', '[]'::jsonb, 'There were some shocks in the second round of the team handicap competition, the biggest being St Blazey’s 3-2 victory over Bugle ‘A’ with Liam Reynolds securing the winning frame over Paul ‘stir-fry’ Sturtridge.', null, '"Bethel ‘D’ triumphed over higher league opponents Bodmin Sparks 3-0 with Andy Spearman’s fine victory over Steve Bampton the pick of the frames."', 'There were some shocks in the second round of the team handicap competition, the biggest being St Blazey’s 3-2 victory over Bugle ‘A’ with Liam Reynolds securing the winning frame over Paul ‘stir-fry’ Sturtridge.

more Bethel ‘D’ triumphed over higher league opponents Bodmin Sparks 3-0 with Andy Spearman’s fine victory over Steve Bampton the pick of the frames. Bugle ‘C’ races into a 2-0 lead at Bethel ‘A’ only to be pegged back to 2-2, but the dependable Andy Fooks posted a great win over Ryan Tonkin to secure the victory.

FULL RESULTS

St Blazey ‘A’ 3-2 Bugle ‘A’, St Neot 3-1 Bethel ‘C’, Lostwithiel ‘B’ 0-3 Tregonissey, Bethel ‘A’ 2-3 Bugle ‘C’, Sparks 0-3 Bethel ‘D’, Lerryn 1-4 Lostwithiel ‘A’. Quarter-final draw: Tywardreath ‘A’ or Bethel ‘B’ v St Blazey, St Neot v Tregonissey, Bugle ‘C’ v Bethel ‘D’, Lostwithiel ‘A’ v Tywardreath ‘B’ or Mevagissey ‘A’. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('St Blazey green with envy', 'st-blazey-green-with-envy', 'Match Reports', '[]'::jsonb, 'St Blazey suffered their first defeat of the St Blazey and District Snooker League season as Bethel ‘B’ closed the gap at the top of the table with a 3-2 win.', null, '"Matt Green’s 36 break equalled the top break in the Rees League so far."', 'St Blazey suffered their first defeat of the St Blazey and District Snooker League season as Bethel ‘B’ closed the gap at the top of the table with a 3-2 win.

more Matt Green’s 36 break equalled the top break in the Rees League so far. Tywardreath ‘B’ have jumped to third by beating Bethel ‘C’ 3-2 and also secured the Runabout Shield as Alan Dennis potted the black for victory. Mevagissey ‘C’ have moved menacingly into fourth place with a game in hand after battering Bethel ‘D’ 4-1. Lostwithiel ‘A’ inflicted Bugle ‘A’’s first defeat, 3-2 to stand alone at the top of the league but with Tywardreath ‘A’ scoring four points and St Neot getting all five against Lostwithiel ‘B’ and Mevagissey ‘B’ respectively and Tregonissey with a game in hand it is really hotting up at the summit. Bodmin Sparks visited Bethel ‘A’ and came away with their first win of the season 3-2 to leave the hosts in real trouble at the bottom. Mevagissey ‘A’ recovered from last week’s defeat to gain a credible 4-1 win at Bugle ‘B’. Graham Taylor’s 35 the only bright spot for the hosts.

FULL RESULTS

Victory League: Tywardreath ‘A’ 4 (A Gooch, P Baron, D Kirwan, J Wilson) Lostwithiel ‘B’ 1 (J Daniell), Lostwithiel ‘A’ 3 (R Broad, D Grose, D Lock) Bugle ‘A’ 2 (J Moore, A Best), Bethel ‘A’ 2 (R Tonkins, G Stephens) Sparks 3 (C Stutridge, M Williams, S Bampton), Bugle ‘B’ 1 (G Taylor (35)) Mevagissey ‘A’ 4 (M Fox, P Staley, L Varcoe, M Towsey), Mevagissey ‘B’ 0 St Neot 5 (M Courts, M Rowe, A Courts, T Farrant, S Courts). Rees Memorial League: Bethel ‘C’ 2 (H Brett, L Pearce) Tywardreath 3 (P Hunt, N Rowe (32), A Dennis), Mevagissey ‘C’ 4 (M Chesterfield, B Prynn, J Chesterfield, D Tregale) Bethel ‘D’ 1 (T Stephen), St Blazey 2 (S Dewings, M Woodward) Bethel ‘B’ 3 (M Green (36), S Hicks, G Buckle), Bethel ‘C’ 3 (J Conroy, K Moore, J Moore) Mevagissey 2 (J Prynn, P Staley). Top breaks of the week: Matt Green 36, Graham Taylor 35. Additional Information League Tables Rankings Competitions Breaks

WEEK 4 IN PICTURES

Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('St Blazey still in the title hunt', 'st-blazey-still-in-the-title-hunt', 'Match Reports', '[]'::jsonb, 'St Blazey ‘B’ have not given up on their title hopes just yet after thrashing Bethel ‘A’ 5-0, thanks to breaks of 54 by Paul Baron, 43 by Mike Hancock and a 38 by Brian Phillips.', null, '"Mevagissey ‘D’ continue to close the gap on second place thanks to an excellent 5-0 home win over Tregonissey ‘B’ Scott Mills, Rich Lakeman, James Tomlinson, Rob Blamey and Neil Parker the successful cue-men."', 'St Blazey ‘B’ have not given up on their title hopes just yet after thrashing Bethel ‘A’ 5-0, thanks to breaks of 54 by Paul Baron, 43 by Mike Hancock and a 38 by Brian Phillips.

more There was also wins for Andy Hall and Graham Taylor thus closing the gap on leaders Tregonissey ‘A’ by a point as Bethel ‘C’s Martin Powell beat Jason Cocks to stop the whitewash. Barry McIntosh and Ryan Bilson both collecting 30 breaks. A 32 break by Ian Powell in the last frame saw Bugle ‘A’ win 3-2 at St Blazey ‘A’. Chris Brown and great victory for Stewart Dewings over Andrew Best put Blazey 2-1 up but Gary Spencer’s victory over Nick Kendall and Poweller’s win saw Bugle home. But Bugle ‘B’s hold on to the Runabout Shield didn’t last long as Lostwithiel ‘A’ returned home with the shield after a 3-2 victory. Darren Lock’s 30 and 46 breaks followed by a victory for Chris Perring set the stage for Steve Courts, courtesy of a fine 47 clearance in the fourth frame to get their hands on the silverware. In the Rees League runaway leaders Lostwithiel ‘A’ won 4-1 at home to an understrength Mevagissey ‘C’ for who Charlie Prynn took their only point. In joint second are the B and D teams from Bethel as they both collected 5-0 wins. St Stephen ‘B’ were unlucky not to collect a couple of frames against the ‘D’ team, while Bethel ‘B’ went to Lerryn and came away with a nap hand which included a win for Mike Williams, formerly of Bodmin Sparks. Mevagissey ‘D’ continue to close the gap on second place thanks to an excellent 5-0 home win over Tregonissey ‘B’ Scott Mills, Rich Lakeman, James Tomlinson, Rob Blamey and Neil Parker the successful cue-men. St Stephen ‘A’ took three points at home to Gorran Haven. Anthony Garside, Dan Allen and Cary Clark took their points with Rob Bunney beating Johnny Bennetts and Paul Grimmett doing brilliantly to overcome Anthony Harrison for the Seasiders.

FULL RESULTS

Victory League: St Blazey ‘A’ 2 (C Brown, S Dewings) Bugle ‘A’ 3 (P Sturtridge, G Spencer, I Powell (32)), Bugle ‘B’ 2 (I Ball, J Moore) Lostwithiel ‘A’ 3 (C Perring, S Courts (47), D Lock (46+30)), Tregonissey ‘A’ 4 (B McIntosh (30), R Bilson (30), C Stephenson, M Knight) Bethel ‘C’ 1 (M Powell), Bethel ‘A’ 0 St Blazey ‘B’ 5 (P Baron (54), M Hancock (43), A Hall, G Taylor, B Phillips (38). Rees Memorial League: St Stephen ‘A’ 3 (A Garside, D Allen, C Clark) Gorran Haven 2 (R Bunney, P Grimmett), Lostwithiel ‘B’ 4 (R Broad, G Lory, J Daniell, A Parnell) Mevagissey ‘C’ 1 (C Prynn), Mevagissey ‘D’ 5 (S Mills, R Lakeman, J Tomlinson, R Blamey, N Parker) Tregonissey ‘B’ 0, Lerryn 0 Bethel ‘B’ 5 (M Williams, D Morshead, G Buckle, R Allen, C Stuthridge), Bethel ‘D’ 5 (A Spearman, B Stunnell, J Pascoe, R Tonkin, S Hicks) St Stephen ‘B’ 0. Top breaks of the week: I Powell 32, D Lock 46,30, B McIntosh 30, R Bilson 30, P Baron 54, M Hancock 43, B Phillips 38, S Courts 47 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('St Neot pick up shock win as Blazey clinch promotion', 'st-neot-pick-up-shock-win-as-blazey-clinch-promotion', 'Match Reports', '[]'::jsonb, 'St Neot put a spanner in the works of Tywardreath A’s title ambitions as Steve and Aaron Courts along with Nigel Collins, who had a 36 break, pulled off a fine 3-2 victory.', null, '"This leaves Bugle five points clear but the Legion boys have a game in hand as have Tregonissey who trounced Mevagissey ‘A’ 5-0, with Barry McIntosh continuing his good form with 30 and 40 breaks."', 'St Neot put a spanner in the works of Tywardreath A’s title ambitions as Steve and Aaron Courts along with Nigel Collins, who had a 36 break, pulled off a fine 3-2 victory.

more League leaders Bugle ‘A’ took full advantage as they defeated Bethel ‘A’ 4-1 with Bob Stephens the home marksman. This leaves Bugle five points clear but the Legion boys have a game in hand as have Tregonissey who trounced Mevagissey ‘A’ 5-0, with Barry McIntosh continuing his good form with 30 and 40 breaks. The battle at the bottom is really hotting up – Lostwithiel ‘B’ leapfrogged Mevagissey ‘A’ in the table despite losing by the odd frame at Mevagissey ‘B’ and Bodmin Sparks picked up a couple of frames at Lostwithiel ‘A’ to further boost their chances of survival. St Blazey clinched promotion to the Victory League after seeing off Gorran Haven 4-1, Chris Brown’s 36 break getting them off to a flyer on the night. Bethel ‘D’ closed in on the other promotion spot after leaving Lerryn with a 5-0 victory and Bugle ‘C’ keep alive their slim hopes after beating Tywardreath 4-1 and the final game of the night saw Bethel ‘C’ beat Mevagissey ‘D’ 3-2. In a night of very close frames the dependable Rob Blamey and Scott Mills taking frames for the away side.

FULL RESULTS

Victory League: Tregonissey ‘A’ 5 (C Stevenson, C Kendall, R Bison, R Pearson, B McIntosh (30 and 40) Mevagissey ‘A’ 0, Bethel ‘A’ 1 (B Stephens) Bugle ‘A’ 4 (A Best, A Peers, G Spencer, P Sturtridge), Mevagissey ‘B’ 3 (B Rothwell, M Mills, M Gregory) Lostwithiel ‘B’ 2 (J Hill, G Lory) Lostwithiel ‘A’ 3 (D Lock (30), R Broad, C Perring) Sparks 2 (S Bampton, M Bolt), Tywardreath ‘A’ 2 (P Baron, M Hancock) St Neot 3 (S Courts, A Courts, N Collins (36)). Rees Memorial League: Bethel ‘C’ 3 (J Cocks, M Powell, C Crockford) Mevagissey ‘D’ 2 (R Blamey, S Mills), St Blazey 4 (C Brown (36), L Rosevear, L Reynolds, M Meares) Gorran Haven 1 (L McKinstry), Bugle ‘C’ 4 (N Couchman, J Moore, K Moore, J Conroy) Tywardreath ‘B’ 1 (G Kent), Lerryn 0 Bethel ‘D’ 5 (J Pascoe, R Allen, V Hathaway, A Spearman, R Allen). Top breaks of the week: Barrie McIntosh 40, 30, Darren Lock 30, Nigel Collins 36, Chris Brown 36. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('St Neot to host County Singles Final', 'st-neot-to-host-county-singles-final', 'League News', '[]'::jsonb, 'This year sees St Neot hosting the county singles final again', null, null, 'This year sees St Neot hosting the county singles final again

more A showcase final between Barrie McIntosh and holder Richard Lloyd will take place on Friday 11th April at 7.15pm, everyone is welcome. It''s a great venue with large bar, parking and plenty of space around the table to enjoy this match. St Neot club would love to see as many of you as possible to show your support to the players. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Stephen Hendry Retires', 'stephen-hendry-retires', 'Professional Snooker', '[]'::jsonb, 'Stephen Hendry’s 2012 World Championship started with a maximum and ended with a 13-2 drubbing to Stephen Maguire and his retirement from tournament snooker.', null, '“Jimmy White would probably feel that even though he''s not at the cutting edge any more, but that he''s enjoyed the challenge of trying to stay within the game, and I''ve enjoyed the same challenge, but obviously Stephen didn''t."', 'Stephen Hendry’s 2012 World Championship started with a maximum and ended with a 13-2 drubbing to Stephen Maguire and his retirement from tournament snooker.

more This was a typically newsworthy tournament for Hendry, who at 43 has taken the decision to put away his cue for good. He is still better than most players on the circuit but not good enough by his own imperious standards. All the plaudits and accolades coming his way tonight are heartfelt and well deserved but Hendry doesn’t need them. He has his unparalleled record of success to reflect on. It was a surprise, spur of the moment Christmas present from his parents in 1982 which set the ball rolling for a remarkable career.

6 WORLD TITLES WILL NEVER BE BEATEN

MAXIMUM VIDEO

You don’t need me to recount the wins and the moments which have defined an entire snooker era. Suffice to say that Hendry can walk away from his playing career with his head held high as the player whose achievements all others are still aiming for. He was a truly driven individual who never allowed himself to get comfortable. Once he won a tournament he targeted the next one. He once won five ranking events in succession. He was a relentless scoring machine who pioneered the modern, attacking era in which we now live. As a man he has always been something of an enigma. It wasn’t only on the table where he kept his emotions hidden. I’ve seen him rendered speechless by defeat but in his dealings with the media and in his role as a snooker legend he has been a great ambassador for the sport. Like Steve Davis before him he has made the sacrifices necessary to be the best. Unlike Davis, though, he isn’t in love with playing but winning. He has decided that he can no longer consistently produce a standard with which he is happy. His retirement is therefore understandable if regrettable. In many ways it is admirable. He is a realist. He has accepted his fate. Ask any snooker player of the last 20 years and they will have nothing but respect for Hendry. His achievements will stand in time. Good luck to him in the future. He will be working in China, will doubtless do BBC commentary and undertake exhibitions. But there’s nothing like the visceral thrill of playing. And Stephen Hendry has thrilled many of us over the years with his talent, his guts, his uncompromising game. He has chosen not to rage against the dying of the light by slogging around qualifiers but to make a typically dignified, unfussy exit from the stage he once owned. This is surely the final triumph of the game’s greatest champion. Article courtesy of the Snooker Scene Images Courtesy of: Action Images & Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Steve Davis, Stephen Hendry, Jimmy White and Joe Johnson break off at the pavilion', 'steve-davis-stephen-hendry-jimmy-white-and-joe-johnson-break-off-at-the-pavilion', 'Professional Snooker', '[]'::jsonb, 'We are excited to announce that 4 of the biggest, and most decorated names, in Snooker are coming together for a very special Snooker Legends exhibition at the Pavilions', null, '"We always get a great crowd in at Plymouth, snooker is very strong in the West Country and this is Joe’s first show with us so it’ll be great to see him playing Steve again recreating their finals from the 1980’s!"', 'We are excited to announce that 4 of the biggest, and most decorated names, in Snooker are coming together for a very special Snooker Legends exhibition at the Pavilions

more 7 times World Champion, Stephen Hendry, teams up with 6 times Champion Steve Davis, to take on the Whirlwind Jimmy White and 1986 World Champion Joe Johnson! Doubles and Singles, only one team can win! This is a once in a lifetime chance to see, and meet, 4 legends of the game. The date for this event is Sunday 19th May 2013 John Virgo will be on hand to provide expert analysis and generally keep the crowds entertained and Bristol’s own, leading referee, Michaela Tabb will officiate on this special night. Stephen said "It’s great to be playing in Plymouth with the Legends Tour and get the chance to say thank you to all the local fans who supported me through my career" Jimmy said “We always get a great crowd in at Plymouth, snooker is very strong in the West Country and this is Joe’s first show with us so it’ll be great to see him playing Steve again recreating their finals from the 1980’s!” VIP packages are available which guarantees the holder a prime seat at the event and entrance to the pre-event Champagne reception where you can meet Stephen, Jimmy, Michaela and JV. Box office 0845 1461460, or book online www.plymouthpavilions.com This exhibition is produced by Snooker Legends Snooker Legends logo and all content copyright © 2013 Snooker Legends. All rights reserved Article courtesy of the Snooker Legends Images Courtesy of: Snooker Legends', '2014-01-01', false, 'Richard Pearson'),
  ('Still tight at the top after victories for the leading teams', 'still-tight-at-the-top-after-victories-for-the-leading-teams', 'Match Reports', '[]'::jsonb, 'With both Mevagissey ‘A’ and Bugle ‘B’ gaining 3-2 victories the gap at the top of the Victory League remains at two points – at the halfway stage.', null, 'Tregonissey ‘B’ picked up a 3-2 victory at Mevagissey ‘C’. They raced into an unassailable lead through Justin Hooley, Ryan Thomas and Gary Wherry but Ben Prynn and Matt Chesterfield picked up comfortable wins over Phil Hooley and Alan Meades for their points.', 'With both Mevagissey ‘A’ and Bugle ‘B’ gaining 3-2 victories the gap at the top of the Victory League remains at two points – at the halfway stage.

more Ian Ball and Paul Sturtridge put Bugle 2-0 up at home to St Neot. Anthony Maddams beat Ian Powell to cut the deficit but Gary Spencer’s fine 43 break, when beating Steve Courts got them home as Darren Lock comprehensively beat Andrew Best in the final frame. Phil Staley beat Steve Allen in the last frame to give Meva’s boys a victory at St Blazey ‘A’. Nick Kendall beat Leighton Varcoe on the blackball for the home side’s second point after Mickey Meares had beaten Chris Kendall in the first frame. Paul Williams and Matt Mills also recorded wins for the table toppers. Tregonissey ‘A’ continued their good run by beating Bethel ‘A’ 4-1. Andy Peers got Bethel off to a good start beating Jason Cocks and it was looking good for them in the net frame with Gary Stephens 27 points to the good over Ryan Bilson. But Ryan went potting mad and took the frame on a respotted black. Martin Knight has a 34 break in his victory and wins from Jason Simmonds and Chris Stephenson leaved Treggy on the fringe of the title race. Pelynt had an excellent victory at home to Bugle ‘B’. Jake Moore’s victory over Len Flower levelled the match at 1-1 but Pelynt won all their four frames convincingly through Richard Broad, Andy Parnell, John Daniell and Phil Ormand. Bethel ‘C’ beat their ‘D’ team 4-1 to really close the gap at the wrong end of the table. Ryan Tonkin’s good form continued as he beat Howard Brett first off. But Courtney Crockford’s first win of the season followed by victories for Tony Green, Martin Powell and Roger Smithson got the basement boys home. In the Rees League St Stephen ‘B’s first win of the season at Q-Bar was a real shock. Darren Biggen’s maiden victory followed up by Rob Garside’s win put the visitors 2-0 up. But Richard Bolt and Phil Ashton levelled things up only for Craig Nicholls’ single point victory over Steve Bampton saw St Stephen home. That result allowed St Stephen ‘A’ to move into second place on their own when they squeezed through 3-2 over Gorran Haven. Wins for Dan Allen and Anthony Garside equalled by Paul Grimmett and Lee McKinstry saw a last frame shoot-out between Anthony Harrison and Rob Bunney which Harry sealed on the black. Tregonissey ‘B’ picked up a 3-2 victory at Mevagissey ‘C’. They raced into an unassailable lead through Justin Hooley, Ryan Thomas and Gary Wherry but Ben Prynn and Matt Chesterfield picked up comfortable wins over Phil Hooley and Alan Meades for their points. Bethel ‘B’ and Mevagissey ‘D’ fought out a very close match. Clive Sturtridge and Guy Buckle traded frames with Neil Parker and Rich Lakeman which left Rich Allen and Rob Blamey in the final frame shootout with the Bethel boys just coming out on top, on the black.

FULL RESULTS

Victory League: Bugle ‘A’ 3 (Ian Ball, Paul Sturtridge, Gary Spencer (43)) St Neot 2 (Anthony Maddams, Darren Lock), St Blazey ‘A’ 2 (Mickey Meares, Nick Kendall) Mevagissey ‘A’ 3 (Paul Williams, Matt Mills, Phil Staley), Tregonissey ‘A’ 4 (Ryan Bilson, Martin Knight (34), Chris Stephenson, Jason Simmons) Bethel ‘A’ 1 (Andy Peers), Pelynt 4 (Richard Broad, Andy Parnell, John Daniell, Phil Ormand) Bugle ‘B’ 1 (Jake Moore), Bethel ‘C’ 4 (Courtney Crockford, Tony Green, Martin Powell, Roger Smithson) Bethel ‘D 1 (Ryan Tonkin). Rees Memorial League: St Stephen ‘A’ 3 (Dan Allen, Anthony Garside, Anthony Harrison) Gorran Haven 2 (Paul Grimmett, Lee McKinstry), Bethel ‘B’ 3 (Clive Sturtridge, Guy Buckle, Rich Allen) Mevagissey ‘D’ 2 (Rich Lakeman, Neil Parker), Bodmin Q-Bar 2 (Richard Bolt, Phil Ashton) St Stephen ‘B’ 3 (Darren Biggin, Rob Garside, Craig Nicholls), Mevagissey ‘C’ 2 (Ben Prynn, Matt Chesterfield) Tregonissey ‘B’ 3 (Justin Hooley, Ryan Thomas, Gary Wherry). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: G Spencer 43,M Knight 34 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson');
insert into articles (title, slug, category, more_categories, excerpt, lead, quote_text, body, published_at, is_published, author, featured, hub_featured, awaiting_approval)
  select r.title, case when exists (select 1 from articles a where a.slug = r.slug) then r.slug || '-old' else r.slug end,
    r.category, r.more_categories, r.excerpt, r.lead, r.quote_text, r.body, r.published_at, r.is_published, r.author, false, false, false
  from _news r;

do $$ begin
  raise notice 'Done: part 6 of 7 — % articles added (drafts).', (select count(*) from _news);
end $$;
